{
  "name": "NeuroLearn AI",
  "description": "An AI-powered adaptive learning platform designed for mobile. Generate custom courses on any topic, chat with an AI tutor, and track your progress in a native-app-like experience."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Lesson {
  id: string;
  title: string;
  description: string;
  content?: string; // Markdown content
  isCompleted: boolean;
  duration: string;
}

export interface Module {
  id: string;
  title: string;
  lessons: Lesson[];
}

export interface Course {
  id: string;
  title: string;
  description: string;
  thumbnail: string;
  author: string;
  category: string;
  rating: number;
  students: number;
  modules: Module[];
  progress: number; // 0-100
  isGenerated?: boolean;
}

export interface User {
  name: string;
  avatar: string;
  streak: number;
  points: number;
}

export type Tab = 'home' | 'search' | 'create' | 'chat' | 'profile';

import { GoogleGenAI, Type } from "@google/genai";
import { Course, Module, Lesson } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const COURSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    description: { type: Type.STRING },
    category: { type: Type.STRING },
    modules: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lessons: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                description: { type: Type.STRING },
                duration: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  }
};

export const generateCourseStructure = async (topic: string): Promise<Partial<Course>> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Create a comprehensive course structure for the topic: "${topic}". 
      The course should be structured for a mobile learning app. 
      Include 3-5 modules, each with 2-4 lessons. 
      Keep descriptions punchy and engaging.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: COURSE_SCHEMA,
      },
    });

    const data = JSON.parse(response.text || "{}");

    // Transform to match our internal types with IDs
    const modules: Module[] = data.modules?.map((mod: any, mIdx: number) => ({
      id: `m-${Date.now()}-${mIdx}`,
      title: mod.title,
      lessons: mod.lessons?.map((les: any, lIdx: number) => ({
        id: `l-${Date.now()}-${mIdx}-${lIdx}`,
        title: les.title,
        description: les.description,
        duration: les.duration || "5 min",
        isCompleted: false,
      })) || []
    })) || [];

    return {
      title: data.title,
      description: data.description,
      category: data.category,
      modules,
      thumbnail: `https://picsum.photos/seed/${topic.replace(/\s/g, '')}/400/300`,
      author: "Gemini AI",
      rating: 5.0,
      students: 1,
      progress: 0,
      isGenerated: true
    };
  } catch (error) {
    console.error("Error generating course:", error);
    throw error;
  }
};

export const generateLessonContent = async (courseTitle: string, lessonTitle: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are an expert tutor. Write a concise, engaging, and educational lesson content for the lesson "${lessonTitle}" which is part of the course "${courseTitle}".
      Use Markdown formatting.
      Include:
      1. A brief introduction.
      2. Key concepts with examples.
      3. A short summary or key takeaway.
      Keep it under 400 words suitable for reading on a mobile device.`,
    });
    return response.text || "Failed to load content.";
  } catch (error) {
    console.error("Error generating lesson content:", error);
    return "Sorry, we couldn't generate the content for this lesson at the moment.";
  }
};

export const chatWithTutor = async (history: { role: 'user' | 'model', text: string }[], message: string) => {
  try {
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        history: history.map(h => ({
            role: h.role,
            parts: [{ text: h.text }]
        })),
        config: {
            systemInstruction: "You are Neuro, a friendly and encouraging AI learning companion. Help the student understand concepts, answer questions, and keep them motivated. Keep answers concise."
        }
      });

      const result = await chat.sendMessage({ message });
      return result.text;
  } catch (error) {
      console.error("Chat error", error);
      return "I'm having trouble connecting right now. Try again later!";
  }
}

import React from 'react';
import { Home, Search, PlusSquare, MessageSquare, User } from 'lucide-react';
import { Tab } from '../types';

interface BottomNavProps {
  currentTab: Tab;
  onTabChange: (tab: Tab) => void;
}

const BottomNav: React.FC<BottomNavProps> = ({ currentTab, onTabChange }) => {
  const navItems: { id: Tab; icon: React.FC<any>; label: string }[] = [
    { id: 'home', icon: Home, label: 'Home' },
    { id: 'search', icon: Search, label: 'Explore' },
    { id: 'create', icon: PlusSquare, label: 'Create' },
    { id: 'chat', icon: MessageSquare, label: 'Tutor' },
    { id: 'profile', icon: User, label: 'Profile' },
  ];

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-3 pb-safe z-50 md:max-w-md md:mx-auto">
      <div className="flex justify-between items-center">
        {navItems.map((item) => {
          const isActive = currentTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => onTabChange(item.id)}
              className={`flex flex-col items-center justify-center space-y-1 transition-colors duration-200 ${
                isActive ? 'text-indigo-600' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              <item.icon size={24} strokeWidth={isActive ? 2.5 : 2} />
              <span className="text-[10px] font-medium">{item.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default BottomNav;

import React from 'react';
