      <div className="p-3">
        <div className="flex items-center justify-between mb-1">
            <span className="text-xs font-semibold text-indigo-600 uppercase tracking-wide">{course.category}</span>
            <div className="flex items-center space-x-1 text-yellow-500">
                <Star size={12} fill="currentColor" />
                <span className="text-xs font-bold text-gray-700">{course.rating}</span>
            </div>
        </div>
        <h3 className="font-bold text-gray-800 text-sm mb-1 line-clamp-2 leading-tight">
          {course.title}
        </h3>
        <p className="text-xs text-gray-500 line-clamp-1 mb-2">
          by {course.author}
        </p>

        <div className="flex items-center justify-between mt-2">
             <div className="flex items-center text-gray-400 space-x-1">
                <Users size={12} />
                <span className="text-[10px]">{course.students.toLocaleString()} students</span>
             </div>
             {course.progress > 0 && (
                 <div className="flex items-center space-x-2">
                     <div className="w-12 h-1.5 bg-gray-200 rounded-full overflow-hidden">
                         <div className="h-full bg-green-500 rounded-full" style={{ width: `${course.progress}%` }}></div>
                     </div>
                     <span className="text-[10px] text-gray-500">{course.progress}%</span>
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

export default CourseCard;

import React from 'react';
import { Course, User } from '../types';
import CourseCard from '../components/CourseCard';
