export default Home;

import React, { useState } from 'react';
import { Sparkles, Loader2, BookOpen, ArrowRight } from 'lucide-react';
import { generateCourseStructure } from '../services/geminiService';
import { Course } from '../types';

interface CourseGeneratorProps {
  onCourseGenerated: (course: Course) => void;
}

const CourseGenerator: React.FC<CourseGeneratorProps> = ({ onCourseGenerated }) => {
  const [topic, setTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!topic.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      const partialCourse = await generateCourseStructure(topic);

      const newCourse: Course = {
        id: `gen-${Date.now()}`,
        title: partialCourse.title || topic,
        description: partialCourse.description || "AI Generated Course",
        thumbnail: partialCourse.thumbnail || "",
        author: "Neuro AI",
        category: partialCourse.category || "General",
        rating: 5.0,
        students: 0,
        modules: partialCourse.modules || [],
        progress: 0,
        isGenerated: true
      };

      onCourseGenerated(newCourse);
    } catch (err) {
      setError("Failed to generate course. Please try a different topic or try again later.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 pt-14 px-6 pb-24">
      <div className="text-center mb-8">
        <div className="inline-flex items-center justify-center w-16 h-16 bg-indigo-100 rounded-full mb-4 text-indigo-600">
            <Sparkles size={32} />
        </div>
        <h1 className="text-2xl font-bold text-gray-900 mb-2">AI Course Generator</h1>
        <p className="text-gray-500 text-sm">
          Type any topic, and our AI will build a complete structured course for you in seconds.
        </p>
      </div>

      <div className="bg-white rounded-3xl p-6 shadow-sm border border-gray-100 mb-6">
        <label className="block text-sm font-medium text-gray-700 mb-2">
            What do you want to learn?
        </label>
        <div className="relative mb-4">
            <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder="e.g., Advanced Pottery, Quantum Physics, Vegan Cooking..."
            className="w-full px-4 py-4 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all text-gray-800 placeholder-gray-400"
            disabled={isGenerating}
            />
        </div>

        <button
            onClick={handleGenerate}
            disabled={!topic.trim() || isGenerating}
            className={`w-full py-4 rounded-xl font-bold text-white flex items-center justify-center space-x-2 transition-all transform active:scale-[0.98] ${
                !topic.trim() || isGenerating 
                ? 'bg-gray-300 cursor-not-allowed' 
                : 'bg-indigo-600 shadow-lg shadow-indigo-200 hover:bg-indigo-700'
            }`}
        >
            {isGenerating ? (
                <>
                    <Loader2 className="animate-spin" size={20} />
                    <span>Generating Magic...</span>
                </>
            ) : (
                <>
                    <Sparkles size={20} />
                    <span>Generate Course</span>
                </>
            )}
        </button>

        {error && (
            <p className="mt-4 text-sm text-center text-red-500 bg-red-50 py-2 rounded-lg">
                {error}
            </p>
        )}
      </div>

      <div className="space-y-4">
        <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider ml-2">Popular Ideas</h3>
        {['Introduction to Python', 'Digital Marketing 101', 'Yoga for Beginners'].map((idea) => (
            <button
                key={idea}
                onClick={() => setTopic(idea)}
                className="w-full bg-white p-4 rounded-2xl border border-gray-100 flex items-center justify-between group hover:border-indigo-100 transition-colors"
            >
                <div className="flex items-center space-x-3">
                    <div className="w-8 h-8 rounded-full bg-orange-50 text-orange-500 flex items-center justify-center">
                        <BookOpen size={14} />
                    </div>
                    <span className="text-gray-700 font-medium text-sm">{idea}</span>
                </div>
                <ArrowRight size={16} className="text-gray-300 group-hover:text-indigo-500 transition-colors" />
            </button>
        ))}
      </div>
    </div>
  );
};

export default CourseGenerator;

import React, { useState } from 'react';
import { Course, Module, Lesson } from '../types';
import { ChevronLeft, PlayCircle, CheckCircle, Lock, Clock, BookOpen, ChevronDown, ChevronUp, ArrowLeft } from 'lucide-react';
import { generateLessonContent } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';

interface CourseDetailProps {
  course: Course;
  onBack: () => void;
}

const CourseDetail: React.FC<CourseDetailProps> = ({ course, onBack }) => {
  const [activeModuleId, setActiveModuleId] = useState<string | null>(course.modules[0]?.id || null);
  const [selectedLesson, setSelectedLesson] = useState<Lesson | null>(null);
  const [lessonContent, setLessonContent] = useState<string>("");
  const [loadingLesson, setLoadingLesson] = useState(false);

  const handleLessonSelect = async (lesson: Lesson) => {
    setSelectedLesson(lesson);
    if (!lesson.content) {
      setLoadingLesson(true);
      try {
        const content = await generateLessonContent(course.title, lesson.title);
        setLessonContent(content);
      } catch (e) {
        setLessonContent("Error loading content.");
      } finally {
        setLoadingLesson(false);
      }
    } else {
      setLessonContent(lesson.content);
    }
  };

  const toggleModule = (id: string) => {
    setActiveModuleId(activeModuleId === id ? null : id);
  };

  if (selectedLesson) {
    return (
      <div className="fixed inset-0 bg-white z-50 overflow-y-auto no-scrollbar">
        <div className="sticky top-0 bg-white border-b border-gray-100 px-4 py-4 flex items-center space-x-4 z-10">
          <button 
            onClick={() => setSelectedLesson(null)}
            className="p-2 rounded-full hover:bg-gray-100"
          >
            <ChevronLeft size={24} className="text-gray-700" />
          </button>
          <div className="flex-1">
            <h3 className="text-sm font-bold text-gray-900 line-clamp-1">{selectedLesson.title}</h3>
            <p className="text-xs text-gray-500">{course.title}</p>
          </div>
        </div>

        <div className="p-6 max-w-2xl mx-auto pb-24">
            {loadingLesson ? (
                <div className="flex flex-col items-center justify-center h-64 space-y-4">
                    <div className="w-10 h-10 border-4 border-indigo-200 border-t-indigo-600 rounded-full animate-spin"></div>
                    <p className="text-gray-500 text-sm animate-pulse">AI is preparing your lesson...</p>
                </div>
            ) : (
                <div className="prose prose-indigo prose-sm sm:prose-base max-w-none">
                    <h1 className="text-2xl font-bold text-gray-900 mb-6">{selectedLesson.title}</h1>
                    <ReactMarkdown>{lessonContent}</ReactMarkdown>
                </div>
            )}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white border-t border-gray-100 md:max-w-md md:mx-auto">
            <button 
                onClick={() => setSelectedLesson(null)} // In a real app, this would mark complete and go to next
                className="w-full bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg shadow-indigo-200 active:scale-[0.98] transition-transform"
            >
                Complete Lesson
            </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-24 md:max-w-md md:mx-auto relative">
      {/* Hero Header */}
      <div className="relative h-64 bg-gray-900">
        <img 
            src={course.thumbnail} 
            alt={course.title}
            className="w-full h-full object-cover opacity-60" 
        />
        <div className="absolute inset-0 bg-gradient-to-t from-gray-900 to-transparent"></div>
        <button 
            onClick={onBack}
            className="absolute top-4 left-4 p-2 bg-black/30 backdrop-blur-md rounded-full text-white hover:bg-black/50 transition-colors"
        >
            <ArrowLeft size={20} />
        </button>
        <div className="absolute bottom-6 left-6 right-6">
            <span className="inline-block px-2 py-1 rounded-md bg-indigo-600 text-white text-[10px] font-bold uppercase tracking-wider mb-2">
                {course.category}
            </span>
            <h1 className="text-2xl font-bold text-white mb-2 leading-tight">{course.title}</h1>
            <div className="flex items-center text-gray-300 text-xs space-x-4">
                <span className="flex items-center"><Users size={12} className="mr-1"/> {course.students} students</span>
                <span className="flex items-center"><Star size={12} className="mr-1 text-yellow-400"/> {course.rating}</span>
            </div>
        </div>
      </div>

      {/* Course Info */}
      <div className="bg-white rounded-t-3xl -mt-6 relative px-6 py-6 shadow-[0_-4px_20px_rgba(0,0,0,0.05)] min-h-[500px]">
        <div className="flex items-center justify-between mb-6">
            <div className="flex items-center space-x-2">
                <div className="w-10 h-10 rounded-full bg-gray-200 overflow-hidden">
                    <img src={`https://ui-avatars.com/api/?name=${course.author}&background=random`} alt={course.author} />
                </div>
                <div>
                    <p className="text-xs text-gray-400">Instructor</p>
                    <p className="text-sm font-bold text-gray-800">{course.author}</p>
                </div>
            </div>
            <div className="text-right">
                <p className="text-xs text-gray-400">Progress</p>
                <p className="text-sm font-bold text-indigo-600">{course.progress}%</p>
            </div>
        </div>

        <div className="mb-6">
            <h2 className="text-lg font-bold text-gray-900 mb-2">About Course</h2>
            <p className="text-sm text-gray-500 leading-relaxed">{course.description}</p>
        </div>

        <h2 className="text-lg font-bold text-gray-900 mb-4">Curriculum</h2>
        <div className="space-y-4">
            {course.modules.map((module, idx) => {
                const isActive = activeModuleId === module.id;
                return (
                    <div key={module.id} className="border border-gray-100 rounded-2xl overflow-hidden bg-gray-50/50">
                        <button 
                            onClick={() => toggleModule(module.id)}
                            className="w-full flex items-center justify-between p-4 bg-white hover:bg-gray-50 transition-colors"
                        >
                            <div className="flex items-center space-x-3">
                                <div className="w-8 h-8 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold text-sm">
                                    {idx + 1}
                                </div>
                                <div className="text-left">
                                    <h3 className="text-sm font-bold text-gray-800">{module.title}</h3>
                                    <p className="text-xs text-gray-400">{module.lessons.length} Lessons</p>
                                </div>
                            </div>
                            {isActive ? <ChevronUp size={18} className="text-gray-400" /> : <ChevronDown size={18} className="text-gray-400" />}
                        </button>

                        {isActive && (
                            <div className="bg-gray-50 p-2 space-y-1">
                                {module.lessons.map((lesson) => (
                                    <button
                                        key={lesson.id}
                                        onClick={() => handleLessonSelect(lesson)}
                                        className="w-full flex items-center justify-between p-3 rounded-xl hover:bg-white transition-colors group"
                                    >
                                        <div className="flex items-center space-x-3">
                                            <div className={`w-6 h-6 rounded-full flex items-center justify-center ${lesson.isCompleted ? 'text-green-500' : 'text-gray-300'}`}>
                                                {lesson.isCompleted ? <CheckCircle size={16} fill="currentColor" className="text-white" /> : <PlayCircle size={16} />}
                                            </div>
                                            <div className="text-left">
