  const handleTabChange = (tab: Tab) => {
    setCurrentTab(tab);
    setActiveCourse(null); // Reset detail view when switching tabs
  };

  const handleCourseClick = (course: Course) => {
    setActiveCourse(course);
  };

  const handleCourseGenerated = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
    setActiveCourse(newCourse); // Open the new course immediately
    // currentTab stays on 'create' technically, but the view is overlaid by course detail
    // or we can switch tab to home to see it in list. Let's keep it simple.
  };

  // Main content renderer based on Tab state
  // In a real app with React Router, these would be Routes.
  // We use conditional rendering here to mimic the single-page-app feel strongly,
  // but wrap in Router for hash management if needed. 

  // Since instructions said use HashRouter, I will implement a hybrid approach where Tabs control view, 
  // but "pages" are components.

  const renderContent = () => {
    if (activeCourse) {
      return <CourseDetail course={activeCourse} onBack={() => setActiveCourse(null)} />;
    }

    switch (currentTab) {
      case 'home':
        return <Home user={MOCK_USER} courses={courses} onCourseClick={handleCourseClick} />;
      case 'search':
        return <div className="pt-20 text-center text-gray-400">Tính năng tìm kiếm sắp ra mắt...</div>;
      case 'create':
        return <CourseGenerator onCourseGenerated={handleCourseGenerated} />;
      case 'chat':
        return <ChatTutor />;
      case 'profile':
        return <div className="pt-20 text-center text-gray-400">Hồ sơ sắp ra mắt...</div>;
      default:
        return <Home user={MOCK_USER} courses={courses} onCourseClick={handleCourseClick} />;
    }
  };

  return (
    <Router>
      <div className="min-h-screen bg-gray-50 font-sans text-gray-900 md:max-w-md md:mx-auto md:shadow-2xl md:min-h-screen md:overflow-hidden relative">
        <main className="h-full">
          {renderContent()}
        </main>

        {!activeCourse && (
            <BottomNav currentTab={currentTab} onTabChange={handleTabChange} />
        )}
      </div>
    </Router>
  );
};

export default App;

