import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User as UserIcon, Loader2 } from 'lucide-react';
import { chatWithTutor } from '../services/geminiService';

const ChatTutor: React.FC = () => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model'; text: string }[]>([
    { role: 'model', text: "Chào! Mình là Neuro, Gia sư AI của bạn. Hãy hỏi mình bất cứ điều gì về các khóa học, lập trình hoặc cuộc sống nhé!" }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      // Pass the previous history excluding the last user message we just added visually
      const history = messages.slice(); 
      const response = await chatWithTutor(history, userMessage);

      setMessages(prev => [...prev, { role: 'model', text: response }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'model', text: "Xin lỗi, mình đang gặp chút khó khăn khi suy nghĩ. Thử lại nhé?" }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-screen bg-gray-50 dark:bg-gray-900 pb-20 pt-10 transition-colors duration-200">
      <div className="flex-none px-6 py-4 bg-white dark:bg-gray-800 shadow-sm z-10 border-b border-gray-100 dark:border-gray-700 transition-colors">
        <div className="flex items-center space-x-3">
            <div className="w-10 h-10 bg-indigo-100 dark:bg-indigo-900/30 rounded-full flex items-center justify-center text-indigo-600 dark:text-indigo-400">
                <Bot size={24} />
            </div>
            <div>
                <h1 className="text-lg font-bold text-gray-900 dark:text-white">Gia sư Neuro</h1>
                <div className="flex items-center space-x-1">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                    <span className="text-xs text-green-600 dark:text-green-400 font-medium">Trực tuyến</span>
                </div>
            </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
        {messages.map((msg, idx) => (
          <div 
            key={idx} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div 
              className={`max-w-[80%] p-4 rounded-2xl text-sm leading-relaxed shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-indigo-600 text-white rounded-br-none' 
                  : 'bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-100 border border-gray-100 dark:border-gray-700 rounded-bl-none'
              }`}
            >
              {msg.text}
            </div>
          </div>
        ))}
        {isLoading && (
            <div className="flex justify-start">
                <div className="bg-white dark:bg-gray-800 p-4 rounded-2xl rounded-bl-none border border-gray-100 dark:border-gray-700 shadow-sm flex items-center space-x-2">
                    <Loader2 size={16} className="animate-spin text-indigo-600 dark:text-indigo-400" />
                    <span className="text-xs text-gray-400 dark:text-gray-500">Đang suy nghĩ...</span>
                </div>
            </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-700 transition-colors">
        <div className="relative flex items-center bg-gray-50 dark:bg-gray-700 rounded-2xl border border-gray-200 dark:border-gray-600 focus-within:ring-2 focus-within:ring-indigo-500 focus-within:border-transparent transition-all">
            <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyPress}
                placeholder="Hỏi bất cứ điều gì..."
                className="flex-1 bg-transparent px-4 py-3 outline-none text-sm text-gray-800 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500"
            />
            <button 
                onClick={handleSend}
                disabled={!input.trim() || isLoading}
                className={`p-2 mr-2 rounded-xl transition-colors ${input.trim() ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-200 dark:bg-gray-600 text-gray-400 dark:text-gray-400'}`}
            >
                <Send size={18} />
            </button>
        </div>
      </div>
    </div>
  );
};

