const App: React.FC = () => {
  const [currentTab, setCurrentTab] = useState<Tab>('home');
  const [courses, setCourses] = useState<Course[]>(MOCK_COURSES);
  const [activeCourse, setActiveCourse] = useState<Course | null>(null);

  // State lifted to App level
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('vi');

  const t = TRANSLATIONS[language];

  const toggleDarkMode = () => {
    setIsDarkMode(prev => {
      const newMode = !prev;
      if (newMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
      return newMode;
    });
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'vi' ? 'en' : 'vi');
  };

  const handleTabChange = (tab: Tab) => {
    setCurrentTab(tab);
    setActiveCourse(null);
  };

  const handleCourseClick = (course: Course) => {
    setActiveCourse(course);
  };

  const handleCourseGenerated = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
    setActiveCourse(newCourse); 
  };

  const renderContent = () => {
    if (activeCourse) {
      return <CourseDetail course={activeCourse} onBack={() => setActiveCourse(null)} language={language} />;
    }

    switch (currentTab) {
      case 'home':
        return <Home user={MOCK_USER} courses={courses} onCourseClick={handleCourseClick} t={t.home} />;
      case 'search':
        return <div className="pt-20 text-center text-gray-400 dark:text-gray-500">{t.search.comingSoon}</div>;
      case 'create':
        return <CourseGenerator onCourseGenerated={handleCourseGenerated} t={t.generator} language={language} />;
      case 'chat':
        return <ChatTutor t={t.chat} language={language} />;
      case 'settings':
        return <Settings 
          user={MOCK_USER} 
          isDarkMode={isDarkMode} 
          onToggleDarkMode={toggleDarkMode}
          language={language}
          onToggleLanguage={toggleLanguage}
          t={t.settings}
        />;
      default:
        return <Home user={MOCK_USER} courses={courses} onCourseClick={handleCourseClick} t={t.home} />;
    }
  };

  return (
    <div className={`min-h-screen bg-gray-50 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 md:max-w-md md:mx-auto md:shadow-2xl md:min-h-screen md:overflow-hidden relative transition-colors duration-200`}>
      <main className="h-full">
        {renderContent()}
      </main>

      {!activeCourse && (
          <BottomNav currentTab={currentTab} onTabChange={handleTabChange} labels={t.nav} />
      )}
    </div>
  );
};

export default App;

