import React, { useState } from 'react';
import { Sparkles, Loader2, BookOpen, ArrowRight } from 'lucide-react';
import { generateCourseStructure } from '../services/geminiService';
import { Course, Language } from '../types';

interface CourseGeneratorProps {
  onCourseGenerated: (course: Course) => void;
  t: any;
  language: Language;
}

const CourseGenerator: React.FC<CourseGeneratorProps> = ({ onCourseGenerated, t, language }) => {
  const [topic, setTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleGenerate = async () => {
    if (!topic.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      const partialCourse = await generateCourseStructure(topic, language);

      const newCourse: Course = {
        id: `gen-${Date.now()}`,
        title: partialCourse.title || topic,
        description: partialCourse.description || "Khóa học tạo bởi AI",
        thumbnail: partialCourse.thumbnail || "",
        author: "Neuro AI",
        category: partialCourse.category || "Tổng quát",
        rating: 5.0,
        students: 0,
        modules: partialCourse.modules || [],
        progress: 0,
        isGenerated: true
      };

      onCourseGenerated(newCourse);
    } catch (err) {
      setError(t.error);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pt-14 px-6 pb-24 transition-colors duration-200">
      <div className="text-center mb-8">
        <div className="inline-flex items-center justify-center w-16 h-16 bg-indigo-100 dark:bg-indigo-900/30 rounded-full mb-4 text-indigo-600 dark:text-indigo-400">
            <Sparkles size={32} />
