                <div className="w-10 h-10 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden">
                    <img src={`https://ui-avatars.com/api/?name=${course.author}&background=random`} alt={course.author} />
                </div>
                <div>
                    <p className="text-xs text-gray-400 dark:text-gray-500">{language === 'vi' ? 'Giảng viên' : 'Instructor'}</p>
                    <p className="text-sm font-bold text-gray-800 dark:text-white">{course.author}</p>
                </div>
            </div>
            <div className="text-right">
                <p className="text-xs text-gray-400 dark:text-gray-500">{language === 'vi' ? 'Tiến độ' : 'Progress'}</p>
                <p className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{course.progress}%</p>
            </div>
        </div>

        <div className="mb-6">
            <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-2">{language === 'vi' ? 'Giới thiệu' : 'Description'}</h2>
            <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed">{course.description}</p>
        </div>

        <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-4">{language === 'vi' ? 'Giáo trình' : 'Curriculum'}</h2>
        <div className="space-y-4">
            {course.modules.map((module, idx) => {
                const isActive = activeModuleId === module.id;
                return (
                    <div key={module.id} className="border border-gray-100 dark:border-gray-700 rounded-2xl overflow-hidden bg-gray-50/50 dark:bg-gray-800/50 transition-colors">
                        <button 
                            onClick={() => toggleModule(module.id)}
                            className="w-full flex items-center justify-between p-4 bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors"
                        >
                            <div className="flex items-center space-x-3">
                                <div className="w-8 h-8 rounded-full bg-indigo-50 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm">
                                    {idx + 1}
                                </div>
                                <div className="text-left">
                                    <h3 className="text-sm font-bold text-gray-800 dark:text-gray-200">{module.title}</h3>
                                    <p className="text-xs text-gray-400 dark:text-gray-500">{module.lessons.length} {language === 'vi' ? 'Bài học' : 'Lessons'}</p>
                                </div>
                            </div>
                            {isActive ? <ChevronUp size={18} className="text-gray-400 dark:text-gray-500" /> : <ChevronDown size={18} className="text-gray-400 dark:text-gray-500" />}
                        </button>

                        {isActive && (
                            <div className="bg-gray-50 dark:bg-gray-800/50 p-2 space-y-1">
                                {module.lessons.map((lesson) => (
                                    <button
                                        key={lesson.id}
                                        onClick={() => handleLessonSelect(lesson, module.id)}
                                        className="w-full flex items-center justify-between p-3 rounded-xl hover:bg-white dark:hover:bg-gray-700 transition-colors group"
                                    >
                                        <div className="flex items-center space-x-3">
                                            <div className={`w-6 h-6 rounded-full flex items-center justify-center ${lesson.isCompleted ? 'text-green-500' : 'text-gray-300 dark:text-gray-600'}`}>
                                                {lesson.isCompleted ? <CheckCircle size={16} fill="currentColor" className="text-white dark:text-gray-900" /> : <PlayCircle size={16} />}
                                            </div>
                                            <div className="text-left">
                                                <p className={`text-sm font-medium ${lesson.isCompleted ? 'text-gray-400 dark:text-gray-600 line-through' : 'text-gray-700 dark:text-gray-200 group-hover:text-indigo-600 dark:group-hover:text-indigo-400'}`}>
                                                    {lesson.title}
                                                </p>
                                                <p className="text-[10px] text-gray-400 dark:text-gray-500">{lesson.duration}</p>
                                            </div>
                                        </div>
                                        {false ? <Lock size={14} className="text-gray-300 dark:text-gray-600" /> : <div className="w-6 h-6 rounded-full border border-gray-200 dark:border-gray-600 group-hover:bg-indigo-600 dark:group-hover:bg-indigo-500 group-hover:border-indigo-600 dark:group-hover:border-indigo-500 transition-colors flex items-center justify-center">
                                            <PlayCircle size={12} className="text-gray-300 dark:text-gray-600 group-hover:text-white" />
                                        </div>}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                )
            })}
        </div>
      </div>
    </div>
  );
};

