const App: React.FC = () => {
  const [currentTab, setCurrentTab] = useState<Tab>('home');
  const [courses, setCourses] = useState<Course[]>(MOCK_COURSES);
  const [activeCourse, setActiveCourse] = useState<Course | null>(null);
  const [user, setUser] = useState<User>(MOCK_USER);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // State lifted to App level
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('vi');

  const t = TRANSLATIONS[language];

  const toggleDarkMode = () => {
    setIsDarkMode(prev => {
      const newMode = !prev;
      if (newMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
      return newMode;
    });
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'vi' ? 'en' : 'vi');
  };

  const handleLogin = (userData: User) => {
    setUser(userData);
    setIsAuthenticated(true);
    setCurrentTab('home');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(MOCK_USER);
  };

  const handleTabChange = (tab: Tab) => {
    setCurrentTab(tab);
    setActiveCourse(null);
  };

  const handleCourseClick = (course: Course) => {
    setActiveCourse(course);
  };

  const handleCourseGenerated = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
    setActiveCourse(newCourse); 
  };

  const handleLessonComplete = (courseId: string, moduleId: string, lessonId: string) => {
    const updateCourseData = (course: Course) => {
      // Deep clone and update modules
      const newModules = course.modules.map(mod => {
        if (mod.id !== moduleId) return mod;
        return {
          ...mod,
          lessons: mod.lessons.map(les => {
            if (les.id !== lessonId) return les;
            return { ...les, isCompleted: true };
          })
        };
      });

      // Recalculate progress
      let totalLessons = 0;
      let completedLessons = 0;
      newModules.forEach(m => m.lessons.forEach(l => {
        totalLessons++;
        if (l.isCompleted) completedLessons++;
      }));

      const newProgress = totalLessons === 0 ? 0 : Math.round((completedLessons / totalLessons) * 100);

      return {
        ...course,
        modules: newModules,
        progress: newProgress
      };
    };

    // Update global courses state
    setCourses(prevCourses => prevCourses.map(c => 
      c.id === courseId ? updateCourseData(c) : c
    ));

    // Update active course if needed (so UI updates immediately)
    if (activeCourse && activeCourse.id === courseId) {
      setActiveCourse(prev => prev ? updateCourseData(prev) : null);
    }
  };

  // Auth Guard
  if (!isAuthenticated) {
    return (
        <div className={`min-h-screen ${isDarkMode ? 'dark' : ''}`}>
             <Auth 
                onLogin={handleLogin} 
                language={language}
                onToggleLanguage={toggleLanguage}
                t={t.auth}
             />
        </div>
    );
  }

  const renderContent = () => {
    if (activeCourse) {
      return (
        <CourseDetail 
          course={activeCourse} 
          onBack={() => setActiveCourse(null)} 
          language={language}
          onLessonComplete={handleLessonComplete}
        />
      );
    }

    switch (currentTab) {
      case 'home':
        return <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} />;
      case 'search':
        return <Search courses={courses} onCourseClick={handleCourseClick} t={t.search} />;
      case 'create':
        return <CourseGenerator onCourseGenerated={handleCourseGenerated} t={t.generator} language={language} />;
      case 'chat':
        return <ChatTutor t={t.chat} language={language} />;
      case 'settings':
        return <Settings 
          user={user} 
          isDarkMode={isDarkMode} 
          onToggleDarkMode={toggleDarkMode}
          language={language}
          onToggleLanguage={toggleLanguage}
          onLogout={handleLogout}
          t={t.settings}
        />;
      default:
        return <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} />;
    }
  };

  return (
    <div className={`min-h-screen bg-gray-50 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 md:max-w-md md:mx-auto md:shadow-2xl md:min-h-screen md:overflow-hidden relative transition-colors duration-200`}>
      <main className="h-full">
        {renderContent()}
      </main>

      {!activeCourse && (
          <BottomNav currentTab={currentTab} onTabChange={handleTabChange} labels={t.nav} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Sparkles, Loader2, BookOpen, ArrowRight, PenTool, ChevronLeft } from 'lucide-react';
import { generateCourseStructure } from '../services/geminiService';
import { Course, Language } from '../types';

interface CourseGeneratorProps {
  onCourseGenerated: (course: Course) => void;
  t: any;
  language: Language;
}

type Mode = 'select' | 'ai' | 'manual';

const CourseGenerator: React.FC<CourseGeneratorProps> = ({ onCourseGenerated, t, language }) => {
  const [mode, setMode] = useState<Mode>('select');
  const [topic, setTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Manual creation state
  const [manualTitle, setManualTitle] = useState('');
  const [manualDesc, setManualDesc] = useState('');
  const [manualCategory, setManualCategory] = useState('');

  const handleAiGenerate = async () => {
    if (!topic.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      const partialCourse = await generateCourseStructure(topic, language);

      const newCourse: Course = {
        id: `gen-${Date.now()}`,
        title: partialCourse.title || topic,
        description: partialCourse.description || "Khóa học tạo bởi AI",
        thumbnail: partialCourse.thumbnail || "",
        author: "Neuro AI",
        category: partialCourse.category || "Tổng quát",
        rating: 5.0,
        students: 0,
        modules: partialCourse.modules || [],
        progress: 0,
        isGenerated: true
      };

      onCourseGenerated(newCourse);
    } catch (err) {
      setError(t.error);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleManualCreate = () => {
      if (!manualTitle.trim()) return;

      const newCourse: Course = {
          id: `manual-${Date.now()}`,
          title: manualTitle,
          description: manualDesc || (language === 'vi' ? 'Khóa học thủ công' : 'Manual Course'),
          thumbnail: `https://picsum.photos/seed/${manualTitle.replace(/\s/g, '')}/400/300`,
          author: 'Me',
          category: manualCategory || 'General',
          rating: 0,
          students: 0,
          progress: 0,
          modules: [
              {
                  id: `m-${Date.now()}`,
                  title: language === 'vi' ? 'Chương 1' : 'Module 1',
                  lessons: []
              }
          ]
      };
      onCourseGenerated(newCourse);
  };

  const resetManualForm = () => {
      setManualTitle('');
      setManualDesc('');
      setManualCategory('');
  };

  const renderSelectMode = () => (
      <div className="flex flex-col space-y-4">
          <button 
            onClick={() => setMode('manual')}
            className="flex flex-col items-center justify-center p-8 bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-sm hover:border-indigo-500 dark:hover:border-indigo-500 transition-all group"
          >
              <div className="w-16 h-16 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mb-4 group-hover:scale-110 transition-transform">
                  <PenTool size={32} />
              </div>
              <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-1">{t.modeManual}</h3>
              <p className="text-sm text-gray-500 dark:text-gray-400 text-center">{t.modeManualDesc}</p>
          </button>

          <button 
            onClick={() => setMode('ai')}
            className="flex flex-col items-center justify-center p-8 bg-gradient-to-br from-indigo-600 to-purple-600 rounded-3xl shadow-lg shadow-indigo-200 dark:shadow-none text-white transition-all transform active:scale-[0.98]"
          >
              <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mb-4 backdrop-blur-sm">
                  <Sparkles size={32} />
              </div>
              <h3 className="text-lg font-bold mb-1">{t.modeAI}</h3>
              <p className="text-sm text-indigo-100 text-center">{t.modeAIDesc}</p>
          </button>
      </div>
  );

  const renderAiMode = () => (
    <>
      <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 mb-6 transition-colors">
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            {t.label}
        </label>
        <div className="relative mb-4">
            <input
            type="text"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            placeholder={t.placeholder}
            className="w-full px-4 py-4 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 placeholder-gray-400 dark:placeholder-gray-500 focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all"
            disabled={isGenerating}
            />
        </div>

        <button
            onClick={handleAiGenerate}
            disabled={!topic.trim() || isGenerating}
            className={`w-full py-4 rounded-xl font-bold text-white flex items-center justify-center space-x-2 transition-all transform active:scale-[0.98] ${
                !topic.trim() || isGenerating 
                ? 'bg-gray-300 dark:bg-gray-600 cursor-not-allowed' 
                : 'bg-indigo-600 dark:bg-indigo-500 shadow-lg shadow-indigo-200 dark:shadow-none hover:bg-indigo-700 dark:hover:bg-indigo-600'
            }`}
        >
            {isGenerating ? (
                <>
                    <Loader2 className="animate-spin" size={20} />
                    <span>{t.generating}</span>
                </>
            ) : (
                <>
                    <Sparkles size={20} />
                    <span>{t.button}</span>
                </>
            )}
        </button>

        {error && (
            <p className="mt-4 text-sm text-center text-red-500 dark:text-red-400 bg-red-50 dark:bg-red-900/20 py-2 rounded-lg">
                {error}
            </p>
        )}
      </div>

      <div className="space-y-4">
        <h3 className="text-sm font-semibold text-gray-400 dark:text-gray-500 uppercase tracking-wider ml-2">{t.ideas}</h3>
        {['Nhập môn Python', 'Marketing Kỹ thuật số 101', 'Yoga cho người mới'].map((idea) => (
            <button
                key={idea}
                onClick={() => setTopic(idea)}
                className="w-full bg-white dark:bg-gray-800 p-4 rounded-2xl border border-gray-100 dark:border-gray-700 flex items-center justify-between group hover:border-indigo-100 dark:hover:border-indigo-800 transition-colors"
            >
                <div className="flex items-center space-x-3">
                    <div className="w-8 h-8 rounded-full bg-orange-50 dark:bg-orange-900/20 text-orange-500 dark:text-orange-400 flex items-center justify-center">
                        <BookOpen size={14} />
                    </div>
                    <span className="text-gray-700 dark:text-gray-200 font-medium text-sm">{idea}</span>
                </div>
                <ArrowRight size={16} className="text-gray-300 dark:text-gray-600 group-hover:text-indigo-500 dark:group-hover:text-indigo-400 transition-colors" />
            </button>
        ))}
      </div>
    </>
  );

  const renderManualMode = () => (
      <div className="bg-white dark:bg-gray-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-gray-700 transition-colors space-y-4">
          <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">{t.courseTitle}</label>
              <input
                  type="text"
                  value={manualTitle}
                  onChange={(e) => setManualTitle(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none"
              />
          </div>
          <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">{t.category}</label>
              <input
                  type="text"
                  value={manualCategory}
                  onChange={(e) => setManualCategory(e.target.value)}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none"
              />
          </div>
          <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">{t.courseDesc}</label>
              <textarea
                  value={manualDesc}
                  onChange={(e) => setManualDesc(e.target.value)}
                  rows={3}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-gray-600 bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none resize-none"
              />
          </div>
          <button 
              onClick={handleManualCreate}
              disabled={!manualTitle.trim()}
              className={`w-full py-3.5 rounded-xl font-bold text-white transition-all active:scale-[0.98] ${
                  !manualTitle.trim() 
                  ? 'bg-gray-300 dark:bg-gray-600 cursor-not-allowed' 
                  : 'bg-indigo-600 dark:bg-indigo-500 hover:bg-indigo-700'
              }`}
          >
              {t.createManual}
          </button>
      </div>
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pt-14 px-6 pb-24 transition-colors duration-200">
      <div className="text-center mb-8">
        {mode === 'select' ? (
            <>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">{t.title}</h1>
                <p className="text-gray-500 dark:text-gray-400 text-sm">{t.selectMode}</p>
            </>
        ) : (
            <div className="flex items-center justify-between">
                <button 
                    onClick={() => {
                        setMode('select');
                        setError(null);
                        setTopic('');
                        resetManualForm();
                    }}
                    className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                >
                    <ChevronLeft className="text-gray-600 dark:text-gray-300" />
                </button>
                <h1 className="text-xl font-bold text-gray-900 dark:text-white">
                    {mode === 'ai' ? t.modeAI : t.modeManual}
                </h1>
                <div className="w-10"></div> {/* Spacer for centering */}
            </div>
        )}
      </div>

      {mode === 'select' && renderSelectMode()}
      {mode === 'ai' && renderAiMode()}
      {mode === 'manual' && renderManualMode()}
    </div>
  );
};

