import React, { useState } from 'react';
import { Sparkles, Loader2, BookOpen, ArrowRight, PenTool, ChevronLeft, Plus, Trash2, FileText, Save, GripVertical } from 'lucide-react';
import { generateCourseStructure } from '../services/geminiService';
import { Course, Language, Module, Lesson } from '../types';

interface CourseGeneratorProps {
  onCourseGenerated: (course: Course) => void;
  t: any;
  language: Language;
}

type Mode = 'select' | 'ai' | 'manual';

const CourseGenerator: React.FC<CourseGeneratorProps> = ({ onCourseGenerated, t, language }) => {
  const [mode, setMode] = useState<Mode>('select');
  const [topic, setTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Manual creation state
  const [manualTitle, setManualTitle] = useState('');
  const [manualDesc, setManualDesc] = useState('');
  const [manualCategory, setManualCategory] = useState('');
  const [manualModules, setManualModules] = useState<Module[]>([
    { id: `m-${Date.now()}`, title: '', lessons: [] }
  ]);
  const [editingLessonId, setEditingLessonId] = useState<{modId: string, lesId: string} | null>(null);

  const handleAiGenerate = async () => {
    if (!topic.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      const partialCourse = await generateCourseStructure(topic, language);

      const newCourse: Course = {
        id: `gen-${Date.now()}`,
        title: partialCourse.title || topic,
        description: partialCourse.description || "Khóa học tạo bởi AI",
        thumbnail: partialCourse.thumbnail || "",
        author: "Neuro AI",
        category: partialCourse.category || "Tổng quát",
        rating: 5.0,
        students: 0,
        modules: partialCourse.modules || [],
        progress: 0,
        isGenerated: true
      };

      onCourseGenerated(newCourse);
    } catch (err) {
      setError(t.error);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleManualCreate = () => {
      if (!manualTitle.trim()) return;

      const newCourse: Course = {
          id: `manual-${Date.now()}`,
          title: manualTitle,
          description: manualDesc || (language === 'vi' ? 'Khóa học thủ công' : 'Manual Course'),
          thumbnail: `https://picsum.photos/seed/${manualTitle.replace(/\s/g, '')}/400/300`,
          author: 'Me',
          category: manualCategory || 'General',
          rating: 0,
          students: 0,
          progress: 0,
          modules: manualModules.filter(m => m.title.trim() !== '')
      };
      onCourseGenerated(newCourse);
  };

  const resetManualForm = () => {
      setManualTitle('');
      setManualDesc('');
      setManualCategory('');
      setManualModules([{ id: `m-${Date.now()}`, title: '', lessons: [] }]);
      setEditingLessonId(null);
  };

  // --- Curriculum Builders ---

  const addModule = () => {
    setManualModules([...manualModules, { id: `m-${Date.now()}`, title: '', lessons: [] }]);
  };

  const deleteModule = (moduleId: string) => {
    if (manualModules.length <= 1) return;
    setManualModules(manualModules.filter(m => m.id !== moduleId));
  };

  const updateModuleTitle = (moduleId: string, title: string) => {
    setManualModules(manualModules.map(m => m.id === moduleId ? { ...m, title } : m));
  };

  const addLesson = (moduleId: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return {
                ...m,
                lessons: [...m.lessons, {
                    id: `l-${Date.now()}`,
                    title: '',
                    description: '',
                    duration: '5 min',
                    isCompleted: false,
                    content: ''
                }]
            };
        }
