  const updateLesson = (moduleId: string, lessonId: string, field: keyof Lesson, value: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return {
                ...m,
                lessons: m.lessons.map(l => l.id === lessonId ? { ...l, [field]: value } : l)
