export type Tab = 'home' | 'search' | 'create' | 'chat' | 'settings';

export type Language = 'vi' | 'en';

import { GoogleGenAI, Type } from "@google/genai";
import { Course, Module, Lesson, Language, VerificationResult } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const COURSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    description: { type: Type.STRING },
    category: { type: Type.STRING },
    modules: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lessons: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                description: { type: Type.STRING },
                duration: { type: Type.STRING }
              }
            }
          }
        }
      }
    }
  }
};

const LESSON_CONTENT_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    markdownContent: { type: Type.STRING, description: "The educational content in Markdown format." },
    youtubeVideos: {
      type: Type.ARRAY,
      description: "A list of 1-2 highly relevant YouTube videos found via search.",
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          videoId: { type: Type.STRING, description: "The YouTube Video ID (e.g., dQw4w9WgXcQ)" }
        }
      }
    }
  }
};

const VERIFICATION_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    status: { 
      type: Type.STRING, 
      enum: ['ACCURATE', 'PARTIALLY_ACCURATE', 'INACCURATE'],
      description: "Overall accuracy assessment of the content." 
    },
    analysis: { 
      type: Type.STRING, 
      description: "A detailed analysis of the facts checked using Google Search." 
    },
    suggestedCorrections: { 
      type: Type.STRING, 
      description: "If there are inaccuracies, suggest corrections. Otherwise empty." 
    }
  }
};

export const generateCourseStructure = async (topic: string, language: Language): Promise<Partial<Course>> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Create a comprehensive course structure for the topic: "${topic}". 
      The content MUST be in ${langPrompt} language.
      The course should be structured for a mobile learning app. 
      Include 3-5 modules, each with 2-4 lessons. 
      Keep descriptions punchy and engaging in ${langPrompt}.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: COURSE_SCHEMA,
      },
    });

    const data = JSON.parse(response.text || "{}");

    // Transform to match our internal types with IDs
    const modules: Module[] = data.modules?.map((mod: any, mIdx: number) => ({
      id: `m-${Date.now()}-${mIdx}`,
      title: mod.title,
      lessons: mod.lessons?.map((les: any, lIdx: number) => ({
        id: `l-${Date.now()}-${mIdx}-${lIdx}`,
        title: les.title,
        description: les.description,
        duration: les.duration || "5 min",
        isCompleted: false,
      })) || []
    })) || [];

    return {
      title: data.title,
      description: data.description,
      category: data.category,
      modules,
      thumbnail: `https://picsum.photos/seed/${topic.replace(/\s/g, '')}/400/300`,
      author: "Gemini AI",
      rating: 5.0,
      students: 1,
      progress: 0,
      isGenerated: true
    };
  } catch (error) {
    console.error("Error generating course:", error);
    throw error;
  }
};

export const generateLessonContent = async (courseTitle: string, lessonTitle: string, language: Language): Promise<{ content: string; sources: { title: string; uri: string }[]; videos: { title: string; videoId: string }[] }> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are an expert tutor. 
      1. Write a concise, engaging, and educational lesson content in ${langPrompt} for the lesson "${lessonTitle}" which is part of the course "${courseTitle}".
      2. USE Google Search to find 2 highly relevant YouTube videos explaining this.

      For the Markdown Content:
      - Include a brief introduction.
      - Key concepts with examples.
      - A short summary.
      - Keep it under 400 words.

      For the Videos:
      - ONLY include videos found in the search results.
      - Extract the real Video ID.
      `,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: LESSON_CONTENT_SCHEMA,
      }
    });

    const json = JSON.parse(response.text || "{}");
    const content = json.markdownContent || (language === 'vi' ? "Không tải được nội dung." : "Content could not be loaded.");

    // Extract grounding chunks from the metadata (for the web sources)
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => chunk.web)
      .filter((web: any) => web)
      .map((web: any) => ({ title: web.title, uri: web.uri })) || [];

    // Helper to extract YouTube ID
    const extractYouTubeId = (url: string) => {
        if (!url) return null;
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? match[2] : null;
    };

    // 1. Get videos from Sources (Grounding) - TRUST THESE MORE
    const sourceVideos = sources
        .filter((s: any) => s.uri && (s.uri.includes('youtube.com') || s.uri.includes('youtu.be')))
        .map((s: any) => ({
            title: s.title,
            videoId: extractYouTubeId(s.uri)
        }))
        .filter((v: any) => v.videoId);

    // 2. Get videos from JSON (Model generation)
    let modelVideos = json.youtubeVideos || [];

    // Combine: Start with source videos, then add model videos if they are different and valid
    const allVideos = [...sourceVideos];
    const existingIds = new Set(allVideos.map(v => v.videoId));

    modelVideos.forEach((v: any) => {
        if (v.videoId && v.videoId.length === 11 && !existingIds.has(v.videoId)) {
            allVideos.push(v);
            existingIds.add(v.videoId);
        }
    });

    return { content, sources, videos: allVideos };
  } catch (error) {
    console.error("Error generating lesson content:", error);
    return {
      content: language === 'vi' 
        ? "Xin lỗi, chúng tôi không thể tạo nội dung cho bài học này ngay bây giờ." 
        : "Sorry, we cannot generate content for this lesson right now.",
      sources: [],
      videos: []
    };
  }
};

export const verifyLessonContent = async (content: string, language: Language): Promise<VerificationResult> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Verify the accuracy of the following educational content using Google Search.
      Language: ${langPrompt}

      Content to verify:
      """
      ${content.substring(0, 1000)}...
      """

      Task:
      1. Check key facts, definitions, and claims against reliable web sources.
      2. Identify any inaccuracies or hallucinations.
      3. Provide a status (ACCURATE, PARTIALLY_ACCURATE, INACCURATE).
      4. Write a brief analysis explaining your findings.
      `,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: VERIFICATION_SCHEMA,
      }
    });

    const json = JSON.parse(response.text || "{}");

    // Extract sources from the verification step
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => chunk.web)
      .filter((web: any) => web)
      .map((web: any) => ({ title: web.title, uri: web.uri })) || [];

    return {
      status: json.status || 'ACCURATE',
      analysis: json.analysis || 'Verification complete.',
      suggestedCorrections: json.suggestedCorrections,
      sources: sources
    };
  } catch (error) {
    console.error("Verification error:", error);
    return {
      status: 'ACCURATE', // Default fallback
      analysis: language === 'vi' ? "Không thể xác minh lúc này." : "Could not verify at this time.",
      sources: []
    };
  }
};

export const chatWithTutor = async (history: { role: 'user' | 'model', text: string }[], message: string, language: Language) => {
  const langInstruction = language === 'vi' ? 'Vietnamese' : 'English';
  try {
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        history: history.map(h => ({
            role: h.role,
            parts: [{ text: h.text }]
        })),
        config: {
            systemInstruction: `You are Neuro, a friendly and encouraging AI learning companion. Help the student understand concepts, answer questions, and keep them motivated. You MUST converse in ${langInstruction}. Keep answers concise.`
        }
      });

      const result = await chat.sendMessage({ message });
      return result.text;
  } catch (error) {
      console.error("Chat error", error);
      return language === 'vi' 
        ? "Mình đang gặp chút sự cố kết nối. Thử lại sau nhé!"
        : "I'm having some connection issues. Please try again later!";
  }
}

