// pages/CourseDetail.tsx
import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { Course, Lesson } from '../types'; // Adjust the import path if needed
import { getCourse, getLessons, verifyLessonContent } from '../services/geminiService';
import { FaChevronDown, FaChevronUp } from 'react-icons/fa';
import { Button, Spinner, Alert } from 'react-bootstrap';

const CourseDetail: React.FC = () => {
    const router = useRouter();
    const { courseId } = router.query;
    const [course, setCourse] = useState<Course | null>(null);
    const [lessons, setLessons] = useState<Lesson[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [selectedLesson, setSelectedLesson] = useState<string | null>(null);
    const [verificationStatus, setVerificationStatus] = useState<{ [key: string]: 'pending' | 'verified' | 'failed' }>({});

    useEffect(() => {
        const fetchCourseDetails = async () => {
            if (!courseId || typeof courseId !== 'string') return;
            setLoading(true);
            try {
                const fetchedCourse = await getCourse(courseId);
                setCourse(fetchedCourse);
                const fetchedLessons = await getLessons(courseId);
                setLessons(fetchedLessons);
            } catch (error: any) {
                setError(error.message || 'Failed to fetch course details.');
            } finally {
                setLoading(false);
            }
        };

        fetchCourseDetails();
    }, [courseId]);

    const handleLessonClick = (lessonId: string) => {
        setSelectedLesson(selectedLesson === lessonId ? null : lessonId);
    };

    const handleVerifyClick = async (lessonId: string) => {
        setVerificationStatus(prevStatus => ({ ...prevStatus, [lessonId]: 'pending' }));
        try {
            const result = await verifyLessonContent(lessonId);
            if (result.success) {
                setVerificationStatus(prevStatus => ({ ...prevStatus, [lessonId]: 'verified' }));
                alert('Lesson verified successfully!');
            } else {
                setVerificationStatus(prevStatus => ({ ...prevStatus, [lessonId]: 'failed' }));
                alert(`Verification failed: ${result.error}`);
            }
        } catch (error: any) {
            setVerificationStatus(prevStatus => ({ ...prevStatus, [lessonId]: 'failed' }));
            alert(`Verification failed: ${error.message || 'An unexpected error occurred.'}`);
        }
    };

    if (loading) return <Spinner animation="border" />;
    if (error) return <Alert variant="danger">{error}</Alert>;
    if (!course) return <Alert variant="warning">Course not found.</Alert>;

    return (
        <div>
            <h1>{course.title}</h1>
            <p>{course.description}</p>
            <Button onClick={() => router.back()}>Back to Courses</Button>

            {/* Modules Section */}
            <div>
                <h2>Modules</h2>
                {lessons.map((lesson) => (
                    <div key={lesson.id} style={{ border: '1px solid #ccc', margin: '10px', padding: '10px' }}>
                        <div onClick={() => handleLessonClick(lesson.id)} style={{ cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                {lesson.title}
                            </div>
                            <div>
                                {selectedLesson === lesson.id ? <FaChevronUp /> : <FaChevronDown />}
                            </div>
                        </div>

                        {selectedLesson === lesson.id && (
                            <div>
                                <p>{lesson.content}</p>
                                <Button
                                    variant="primary"
                                    onClick={() => handleVerifyClick(lesson.id)}
                                    disabled={verificationStatus[lesson.id] === 'pending'}
