import React, { useState } from 'react';
import { Course, Module, Lesson, Language, VerificationResult } from '../types';
import { ChevronLeft, PlayCircle, CheckCircle, Lock, Clock, BookOpen, ChevronDown, ChevronUp, ArrowLeft, Users, Star, Sparkles, Loader2, Link as LinkIcon, Youtube, ShieldCheck, AlertTriangle, Check } from 'lucide-react';
import { generateLessonContent, verifyLessonContent } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';
import CourseCard from '../components/CourseCard';

interface CourseDetailProps {
  course: Course;
  allCourses?: Course[];
  onCourseClick?: (course: Course) => void;
  onBack: () => void;
  language?: Language;
  onLessonComplete?: (courseId: string, moduleId: string, lessonId: string) => void;
}

const CourseDetail: React.FC<CourseDetailProps> = ({ 
    course, 
    allCourses = [], 
    onCourseClick, 
    onBack, 
    language = 'vi', 
    onLessonComplete 
}) => {
  const [activeModuleId, setActiveModuleId] = useState<string | null>(course.modules[0]?.id || null);
  const [selectedLesson, setSelectedLesson] = useState<Lesson | null>(null);
  const [selectedModuleId, setSelectedModuleId] = useState<string | null>(null);
  const [lessonContent, setLessonContent] = useState<string>("");
  const [lessonSources, setLessonSources] = useState<{title: string, uri: string}[]>([]);
  const [lessonVideos, setLessonVideos] = useState<{title: string, videoId: string}[]>([]);
  const [loadingLesson, setLoadingLesson] = useState(false);

  // Verification State
  const [verificationResult, setVerificationResult] = useState<VerificationResult | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);

  // Determine related courses: same category, excluding current course
  const relatedCourses = allCourses
    .filter(c => c.id !== course.id)
    .sort((a, b) => {
        // Boost score if category matches
        const aScore = a.category === course.category ? 1 : 0;
        const bScore = b.category === course.category ? 1 : 0;
        return bScore - aScore;
    })
    .slice(0, 5);

  const handleLessonSelect = (lesson: Lesson, moduleId: string) => {
    setSelectedLesson(lesson);
    setSelectedModuleId(moduleId);
    setVerificationResult(null); // Reset verification on new lesson
    // If content exists, show it. Otherwise, reset content to empty to show the Generate UI.
    if (lesson.content) {
      setLessonContent(lesson.content);
      setLessonSources(lesson.sources || []);
      setLessonVideos(lesson.videos || []);
    } else {
      setLessonContent("");
      setLessonSources([]);
      setLessonVideos([]);
    }
  };

  const handleGenerateContent = async () => {
    if (!selectedLesson || loadingLesson) return;

    setLoadingLesson(true);
    setLessonSources([]);
    setLessonVideos([]);
    setVerificationResult(null);
    try {
      const result = await generateLessonContent(course.title, selectedLesson.title, language);
      setLessonContent(result.content);
      setLessonSources(result.sources);
      setLessonVideos(result.videos);

      // Update the local lesson object so it persists in memory for this session
      selectedLesson.content = result.content;
      selectedLesson.sources = result.sources;
      selectedLesson.videos = result.videos;
    } catch (e) {
      setLessonContent(language === 'vi' ? "Lỗi tải nội dung." : "Error loading content.");
    } finally {
      setLoadingLesson(false);
    }
  };

  const handleVerifyContent = async () => {
    if (!lessonContent || isVerifying) return;

    setIsVerifying(true);
    try {
        const result = await verifyLessonContent(lessonContent, language);
        setVerificationResult(result);
    } catch (e) {
        console.error(e);
    } finally {
        setIsVerifying(false);
    }
  };

  const handleCompleteLesson = () => {
    if (onLessonComplete && selectedLesson && selectedModuleId) {
        onLessonComplete(course.id, selectedModuleId, selectedLesson.id);
    }
    setSelectedLesson(null);
  };

  const toggleModule = (id: string) => {
    setActiveModuleId(activeModuleId === id ? null : id);
  };

  const renderVerificationResult = () => {
      if (!verificationResult) return null;

      let bgColor = "bg-green-50 dark:bg-green-900/20";
      let borderColor = "border-green-200 dark:border-green-800";
      let textColor = "text-green-800 dark:text-green-200";
      let icon = <Check size={20} className="text-green-600 dark:text-green-400" />;
      let title = language === 'vi' ? "Thông tin chính xác" : "Information Accurate";

      if (verificationResult.status === 'PARTIALLY_ACCURATE') {
          bgColor = "bg-yellow-50 dark:bg-yellow-900/20";
          borderColor = "border-yellow-200 dark:border-yellow-800";
          textColor = "text-yellow-800 dark:text-yellow-200";
          icon = <AlertTriangle size={20} className="text-yellow-600 dark:text-yellow-400" />;
          title = language === 'vi' ? "Lưu ý một số điểm" : "Partially Accurate";
      } else if (verificationResult.status === 'INACCURATE') {
          bgColor = "bg-red-50 dark:bg-red-900/20";
          borderColor = "border-red-200 dark:border-red-800";
          textColor = "text-red-800 dark:text-red-200";
          icon = <AlertTriangle size={20} className="text-red-600 dark:text-red-400" />;
          title = language === 'vi' ? "Thông tin không chính xác" : "Inaccurate Information";
      }

      return (
          <div className={`mt-6 rounded-xl border ${borderColor} ${bgColor} p-4 transition-all duration-300`}>
              <div className="flex items-center space-x-2 mb-2">
                  {icon}
                  <h4 className={`font-bold ${textColor}`}>{title}</h4>
              </div>
              <p className="text-sm text-gray-700 dark:text-gray-300 mb-3 leading-relaxed">
                  {verificationResult.analysis}
              </p>
              {verificationResult.suggestedCorrections && (
                  <div className="mb-3 text-sm bg-white dark:bg-gray-800 p-3 rounded-lg border border-gray-100 dark:border-gray-700">
                      <span className="font-bold text-gray-900 dark:text-white block mb-1">
                        {language === 'vi' ? "Đề xuất chỉnh sửa:" : "Correction:"}
                      </span>
                      <span className="text-gray-600 dark:text-gray-400">
                          {verificationResult.suggestedCorrections}
                      </span>
                  </div>
              )}
              {verificationResult.sources.length > 0 && (
                  <div>
                      <span className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-2">
                        {language === 'vi' ? "Nguồn xác minh:" : "Verified Sources:"}
                      </span>
                      <div className="space-y-1">
                          {verificationResult.sources.map((src, i) => (
                              <a 
                                key={i} 
                                href={src.uri} 
                                target="_blank" 
                                rel="noreferrer" 
                                className="block text-xs text-indigo-600 dark:text-indigo-400 truncate hover:underline"
                              >
                                  {src.title}
                              </a>
                          ))}
                      </div>
                  </div>
              )}
          </div>
      );
  };

  if (selectedLesson) {
    return (
      <div className="fixed inset-0 bg-white dark:bg-gray-900 z-50 overflow-y-auto no-scrollbar transition-colors duration-200">
        <div className="sticky top-0 bg-white dark:bg-gray-900 border-b border-gray-100 dark:border-gray-800 px-4 py-4 flex items-center space-x-4 z-10 transition-colors">
          <button 
            onClick={() => setSelectedLesson(null)}
            className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
          >
            <ChevronLeft size={24} className="text-gray-700 dark:text-gray-200" />
          </button>
          <div className="flex-1">
            <h3 className="text-sm font-bold text-gray-900 dark:text-white line-clamp-1">{selectedLesson.title}</h3>
            <p className="text-xs text-gray-500 dark:text-gray-400">{course.title}</p>
          </div>
        </div>

        <div className="p-6 max-w-2xl mx-auto pb-24">
            {loadingLesson ? (
                <div className="flex flex-col items-center justify-center h-64 space-y-4">
                    <div className="w-10 h-10 border-4 border-indigo-200 border-t-indigo-600 dark:border-indigo-900 dark:border-t-indigo-500 rounded-full animate-spin"></div>
                    <p className="text-gray-500 dark:text-gray-400 text-sm animate-pulse">AI đang soạn bài học cho bạn...</p>
                </div>
            ) : lessonContent ? (
                <div className="prose prose-indigo dark:prose-invert prose-sm sm:prose-base max-w-none">
                    <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-6">{selectedLesson.title}</h1>
                    <ReactMarkdown>{lessonContent}</ReactMarkdown>

                    {/* Verification Button */}
                    {!verificationResult && (
                        <div className="mt-8 flex justify-center">
                            <button
                                onClick={handleVerifyContent}
                                disabled={isVerifying}
                                className={`flex items-center space-x-2 px-5 py-2.5 rounded-full text-sm font-semibold transition-all border ${
                                    isVerifying 
                                    ? 'bg-gray-100 text-gray-400 border-gray-200 dark:bg-gray-800 dark:border-gray-700' 
                                    : 'bg-white text-indigo-600 border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300 dark:bg-gray-800 dark:text-indigo-400 dark:border-gray-700 dark:hover:bg-gray-750'
                                }`}
                            >
                                {isVerifying ? (
                                    <>
                                        <Loader2 size={16} className="animate-spin" />
                                        <span>{language === 'vi' ? 'Đang kiểm tra...' : 'Verifying...'}</span>
                                    </>
                                ) : (
                                    <>
                                        <ShieldCheck size={16} />
                                        <span>{language === 'vi' ? 'Kiểm tra lại bằng Google' : 'Verify with Google'}</span>
                                    </>
                                )}
                            </button>
                        </div>
                    )}

                    {/* Verification Result Area */}
                    {renderVerificationResult()}

                    {/* YouTube Videos Section */}
                    {lessonVideos.length > 0 && (
                        <div className="mt-8 pt-6 border-t border-gray-100 dark:border-gray-800">
                            <h4 className="flex items-center text-sm font-bold text-gray-700 dark:text-gray-300 mb-4">
                                <Youtube size={16} className="mr-2 text-red-600" />
                                {language === 'vi' ? 'Video bài giảng' : 'Video Tutorial'}
                            </h4>
                            <div className="space-y-4">
                                {lessonVideos.map((video, idx) => (
                                    <div key={idx} className="overflow-hidden rounded-xl bg-black shadow-lg">
                                        <div className="relative pb-[56.25%] h-0">
                                            <iframe
                                                src={`https://www.youtube.com/embed/${video.videoId}`}
                                                title={video.title}
                                                className="absolute top-0 left-0 w-full h-full"
                                                frameBorder="0"
                                                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                                allowFullScreen
                                            />
                                        </div>
                                        <div className="p-3 bg-gray-50 dark:bg-gray-800">
                                            <p className="text-xs font-medium text-gray-900 dark:text-white line-clamp-1">{video.title}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Sources Section */}
                    {lessonSources.length > 0 && (
                        <div className="mt-8 pt-6 border-t border-gray-100 dark:border-gray-800">
                            <h4 className="flex items-center text-sm font-bold text-gray-700 dark:text-gray-300 mb-3">
                                <LinkIcon size={14} className="mr-2" />
                                {language === 'vi' ? 'Nguồn tham khảo' : 'Sources'}
                            </h4>
                            <div className="grid grid-cols-1 gap-2">
                                {lessonSources.map((source, idx) => (
                                    <a 
                                        key={idx} 
                                        href={source.uri} 
                                        target="_blank" 
                                        rel="noopener noreferrer"
                                        className="flex items-start p-3 bg-gray-50 dark:bg-gray-800 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-750 transition-colors group"
                                    >
                                        <div className="flex-1 min-w-0">
                                            <p className="text-xs font-medium text-indigo-600 dark:text-indigo-400 truncate group-hover:underline">
                                                {source.title}
                                            </p>
                                            <p className="text-[10px] text-gray-400 dark:text-gray-500 truncate mt-0.5">
                                                {source.uri}
                                            </p>
                                        </div>
                                    </a>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            ) : (
                <div className="flex flex-col items-center justify-center py-10 text-center space-y-4">
                    <div className="w-20 h-20 bg-indigo-50 dark:bg-indigo-900/20 rounded-full flex items-center justify-center mb-2">
                        <Sparkles size={32} className="text-indigo-600 dark:text-indigo-400" />
                    </div>
                    <div>
                        <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-2">
                            {language === 'vi' ? 'Nội dung chưa sẵn sàng' : 'Content Not Ready'}
                        </h3>
                        <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs mx-auto">
                            {language === 'vi' 
                                ? 'Bài học này chưa có nội dung chi tiết. Hãy để AI tạo nội dung tùy chỉnh cho bạn.' 
                                : 'This lesson does not have detailed content yet. Let AI generate custom content for you.'}
                        </p>
                    </div>
                    <button 
                        onClick={handleGenerateContent}
                        disabled={loadingLesson}
                        className={`flex items-center space-x-2 font-bold py-3 px-8 rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none transition-all active:scale-[0.98] ${
                            loadingLesson 
                            ? 'bg-gray-300 dark:bg-gray-700 text-gray-500 cursor-not-allowed' 
                            : 'bg-indigo-600 hover:bg-indigo-700 text-white'
                        }`}
                    >
                        {loadingLesson ? <Loader2 size={18} className="animate-spin" /> : <Sparkles size={18} />}
                        <span>{language === 'vi' ? 'Tạo nội dung với AI' : 'Generate with AI'}</span>
                    </button>
                </div>
            )}
        </div>

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 md:max-w-md md:mx-auto transition-colors">
            <button 
                onClick={handleCompleteLesson} 
                disabled={!lessonContent || loadingLesson}
                className={`w-full font-bold py-3 rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none transition-all active:scale-[0.98] ${
                    !lessonContent || loadingLesson
                    ? 'bg-gray-200 dark:bg-gray-800 text-gray-400 dark:text-gray-600 cursor-not-allowed shadow-none'
                    : 'bg-indigo-600 dark:bg-indigo-500 text-white'
                }`}
            >
                {language === 'vi' ? 'Hoàn thành bài học' : 'Complete Lesson'}
            </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-24 md:max-w-md md:mx-auto relative transition-colors duration-200">
      {/* Hero Header */}
      <div className="relative h-64 bg-gray-900">
        <img 
            src={course.thumbnail} 
            alt={course.title}
            className="w-full h-full object-cover opacity-60" 
        />
        <div className="absolute inset-0 bg-gradient-to-t from-gray-900 to-transparent"></div>
        <button 
            onClick={onBack}
            className="absolute top-4 left-4 p-2 bg-black/30 backdrop-blur-md rounded-full text-white hover:bg-black/50 transition-colors"
        >
            <ArrowLeft size={20} />
        </button>
        <div className="absolute bottom-6 left-6 right-6">
            <span className="inline-block px-2 py-1 rounded-md bg-indigo-600 text-white text-[10px] font-bold uppercase tracking-wider mb-2">
                {course.category}
            </span>
            <h1 className="text-2xl font-bold text-white mb-2 leading-tight">{course.title}</h1>
            <div className="flex items-center text-gray-300 text-xs space-x-4">
                <span className="flex items-center"><Users size={12} className="mr-1"/> {course.students} {language === 'vi' ? 'học viên' : 'students'}</span>
                <span className="flex items-center"><Star size={12} className="mr-1 text-yellow-400"/> {course.rating}</span>
            </div>
        </div>
      </div>

      {/* Course Info */}
      <div className="bg-white dark:bg-gray-900 rounded-t-3xl -mt-6 relative px-6 py-6 shadow-[0_-4px_20px_rgba(0,0,0,0.05)] min-h-[500px] transition-colors">
        <div className="flex items-center justify-between mb-6">
            <div className="flex items-center space-x-2">
                <div className="w-10 h-10 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden">
                    <img src={`https://ui-avatars.com/api/?name=${course.author}&background=random`} alt={course.author} />
                </div>
                <div>
                    <p className="text-xs text-gray-400 dark:text-gray-500">{language === 'vi' ? 'Giảng viên' : 'Instructor'}</p>
                    <p className="text-sm font-bold text-gray-800 dark:text-white">{course.author}</p>
                </div>
            </div>
            <div className="text-right">
                <p className="text-xs text-gray-400 dark:text-gray-500">{language === 'vi' ? 'Tiến độ' : 'Progress'}</p>
                <p className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{course.progress}%</p>
            </div>
        </div>

        <div className="mb-6">
            <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-2">{language === 'vi' ? 'Giới thiệu' : 'Description'}</h2>
            <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed">{course.description}</p>
        </div>

        <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-4">{language === 'vi' ? 'Giáo trình' : 'Curriculum'}</h2>
        <div className="space-y-4">
            {course.modules.map((module, idx) => {
                const isActive = activeModuleId === module.id;
                return (
                    <div key={module.id} className="border border-gray-100 dark:border-gray-700 rounded-2xl overflow-hidden bg-gray-50/50 dark:bg-gray-800/50 transition-colors">
                        <button 
                            onClick={() => toggleModule(module.id)}
                            className="w-full flex items-center justify-between p-4 bg-white dark:bg-gray-800 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors"
                        >
                            <div className="flex items-center space-x-3">
                                <div className="w-8 h-8 rounded-full bg-indigo-50 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 flex items-center justify-center">
                                    <span className="text-sm font-bold">{idx + 1}</span>
                                </div>
                                <div className="text-left">
                                    <h3 className="text-sm font-bold text-gray-900 dark:text-white">{module.title}</h3>
                                    <p className="text-xs text-gray-500 dark:text-gray-400">{module.lessons.length} {language === 'vi' ? 'bài học' : 'lessons'}</p>
                                </div>
                            </div>
                            {isActive ? <ChevronUp size={20} className="text-gray-400" /> : <ChevronDown size={20} className="text-gray-400" />}
                        </button>

                        {isActive && (
                            <div className="border-t border-gray-100 dark:border-gray-700">
                                {module.lessons.map((lesson, lIdx) => (
                                    <button 
                                        key={lesson.id}
                                        onClick={() => handleLessonSelect(lesson, module.id)}
                                        className="w-full flex items-center justify-between p-4 hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors group"
                                    >
                                        <div className="flex items-center space-x-3">
                                            {lesson.isCompleted ? (
                                                <CheckCircle size={18} className="text-green-500" />
                                            ) : (
                                                <div className="w-[18px] h-[18px] rounded-full border-2 border-gray-300 dark:border-gray-600 group-hover:border-indigo-500 transition-colors"></div>
                                            )}
                                            <div className="text-left">
                                                <p className={`text-sm font-medium ${lesson.isCompleted ? 'text-gray-400 line-through' : 'text-gray-700 dark:text-gray-200'}`}>
                                                    {lesson.title}
                                                </p>
                                            </div>
                                        </div>
                                        <div className="flex items-center space-x-2">
                                            <span className="text-xs text-gray-400">{lesson.duration}</span>
                                            {lesson.isCompleted ? null : <PlayCircle size={16} className="text-gray-300 dark:text-gray-600 group-hover:text-indigo-500" />}
                                        </div>
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                );
            })}
        </div>

        {relatedCourses.length > 0 && (
            <div className="mt-8">
                <h2 className="text-lg font-bold text-gray-900 dark:text-white mb-4">{language === 'vi' ? 'Khóa học liên quan' : 'Related Courses'}</h2>
                <div className="flex overflow-x-auto space-x-4 pb-4 -mx-6 px-6 no-scrollbar">
                    {relatedCourses.map(relCourse => (
                        <div key={relCourse.id} className="min-w-[260px]">
                            <CourseCard 
                                course={relCourse} 
                                onClick={(c) => {
                                    if (onCourseClick) onCourseClick(c);
                                }} 
                            />
                        </div>
                    ))}
                </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default CourseDetail;

