const App: React.FC = () => {
  const [currentTab, setCurrentTab] = useState<Tab>('home');
  const [courses, setCourses] = useState<Course[]>(MOCK_COURSES);
  const [activeCourse, setActiveCourse] = useState<Course | null>(null);
  const [user, setUser] = useState<User>(MOCK_USER);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // State lifted to App level
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('vi');

  const t = TRANSLATIONS[language];

  const toggleDarkMode = () => {
    setIsDarkMode(prev => {
      const newMode = !prev;
      if (newMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
      return newMode;
    });
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'vi' ? 'en' : 'vi');
  };

  const handleLogin = (userData: User) => {
    setUser(userData);
    setIsAuthenticated(true);
    setCurrentTab('home');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(MOCK_USER);
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
  };

  const handleTabChange = (tab: Tab) => {
    setCurrentTab(tab);
    setActiveCourse(null);
  };

  const handleCourseClick = (course: Course) => {
    setActiveCourse(course);
  };

  const handleCourseGenerated = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
    setActiveCourse(newCourse); 
  };

  const handleLessonComplete = (courseId: string, moduleId: string, lessonId: string) => {
    const updateCourseData = (course: Course) => {
      // Deep clone and update modules
      const newModules = course.modules.map(mod => {
        if (mod.id !== moduleId) return mod;
        return {
          ...mod,
          lessons: mod.lessons.map(les => {
            if (les.id !== lessonId) return les;
            return { ...les, isCompleted: true };
          })
        };
      });

      // Recalculate progress
      let totalLessons = 0;
      let completedLessons = 0;
      newModules.forEach(m => m.lessons.forEach(l => {
        totalLessons++;
        if (l.isCompleted) completedLessons++;
      }));

      const newProgress = totalLessons === 0 ? 0 : Math.round((completedLessons / totalLessons) * 100);

      return {
        ...course,
        modules: newModules,
        progress: newProgress
      };
    };

    // Update global courses state
    setCourses(prevCourses => prevCourses.map(c => 
      c.id === courseId ? updateCourseData(c) : c
    ));

    // Update active course if needed (so UI updates immediately)
    if (activeCourse && activeCourse.id === courseId) {
      setActiveCourse(prev => prev ? updateCourseData(prev) : null);
    }
  };

  // Auth Guard
  if (!isAuthenticated) {
    return (
        <div className={`min-h-screen ${isDarkMode ? 'dark' : ''}`}>
             <Auth 
                onLogin={handleLogin} 
                language={language}
                onToggleLanguage={toggleLanguage}
                t={t.auth}
             />
        </div>
    );
  }

  const renderContent = () => {
    if (activeCourse) {
      return (
        <CourseDetail 
          key={activeCourse.id}
          course={activeCourse} 
          allCourses={courses}
          onCourseClick={handleCourseClick}
          onBack={() => setActiveCourse(null)} 
          language={language}
          onLessonComplete={handleLessonComplete}
        />
      );
    }

    switch (currentTab) {
      case 'home':
        return <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} />;
      case 'search':
        return <Search courses={courses} onCourseClick={handleCourseClick} t={t.search} />;
      case 'create':
        return <CourseGenerator onCourseGenerated={handleCourseGenerated} t={t.generator} language={language} />;
      case 'chat':
        return <ChatTutor t={t.chat} language={language} />;
      case 'settings':
        return <Settings 
          user={user} 
          onUpdateUser={handleUpdateUser}
          isDarkMode={isDarkMode} 
          onToggleDarkMode={toggleDarkMode}
          language={language}
          onToggleLanguage={toggleLanguage}
          onLogout={handleLogout}
          t={t.settings}
        />;
      default:
        return <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} />;
    }
  };

  return (
    <div className={`min-h-screen bg-gray-50 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 md:max-w-md md:mx-auto md:shadow-2xl md:min-h-screen md:overflow-hidden relative transition-colors duration-200`}>
      <main className="h-full">
        {renderContent()}
      </main>

      {!activeCourse && (
          <BottomNav currentTab={currentTab} onTabChange={handleTabChange} labels={t.nav} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Sparkles, Loader2, BookOpen, ArrowRight, PenTool, ChevronLeft, Plus, Trash2, FileText, Save, GripVertical, Check, UploadCloud, FileType } from 'lucide-react';
import { generateCourseStructure } from '../services/geminiService';
import { Course, Language, Module, Lesson } from '../types';

interface CourseGeneratorProps {
  onCourseGenerated: (course: Course) => void;
  t: any;
  language: Language;
}

type Mode = 'select' | 'ai' | 'manual' | 'upload';

const CourseGenerator: React.FC<CourseGeneratorProps> = ({ onCourseGenerated, t, language }) => {
  const [mode, setMode] = useState<Mode>('select');
  const [topic, setTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Upload State
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [fileData, setFileData] = useState<{ mimeType: string; data: string } | null>(null);

  // Manual creation state
  const [manualTitle, setManualTitle] = useState('');
  const [manualDesc, setManualDesc] = useState('');
  const [manualCategory, setManualCategory] = useState('');
  const [manualModules, setManualModules] = useState<Module[]>([
    { id: `m-${Date.now()}`, title: '', lessons: [] }
  ]);
  const [editingLessonId, setEditingLessonId] = useState<{modId: string, lesId: string} | null>(null);

  // Drag and Drop State
  const [draggedItem, setDraggedItem] = useState<{ type: 'module' | 'lesson', id: string, parentId?: string } | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const [lastMovedId, setLastMovedId] = useState<string | null>(null);

  const handleAiGenerate = async () => {
    // Determine if we have enough input: either a topic text OR a file
    if (!topic.trim() && !fileData) return;

    setIsGenerating(true);
    setError(null);

    try {
      // Pass fileData if it exists
      const partialCourse = await generateCourseStructure(
          topic, 
          language, 
          fileData || undefined
      );

      const newCourse: Course = {
        id: `gen-${Date.now()}`,
        title: partialCourse.title || topic || "Uploaded Course",
        description: partialCourse.description || "Khóa học tạo bởi AI",
        thumbnail: partialCourse.thumbnail || "",
        author: "Neuro AI",
        category: partialCourse.category || "Tổng quát",
        rating: 5.0,
        students: 0,
        modules: partialCourse.modules || [],
        progress: 0,
        isGenerated: true
      };

      onCourseGenerated(newCourse);
    } catch (err) {
      setError(t.error);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];

          // Basic validation (size < 5MB)
          if (file.size > 5 * 1024 * 1024) {
              setError("File is too large (Max 5MB)");
              return;
          }

          setSelectedFile(file);
          setError(null);

          // Read file as Base64
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64String = reader.result as string;
              // Remove the Data URL prefix (e.g., "data:application/pdf;base64,")
              const base64Data = base64String.split(',')[1];
              setFileData({
                  mimeType: file.type,
                  data: base64Data
              });
          };
          reader.readAsDataURL(file);
      }
  };

  const handleManualCreate = () => {
      if (!manualTitle.trim()) return;

      const newCourse: Course = {
          id: `manual-${Date.now()}`,
          title: manualTitle,
          description: manualDesc || (language === 'vi' ? 'Khóa học thủ công' : 'Manual Course'),
          thumbnail: `https://picsum.photos/seed/${manualTitle.replace(/\s/g, '')}/400/300`,
          author: 'Me',
          category: manualCategory || 'General',
          rating: 0,
          students: 0,
          progress: 0,
          modules: manualModules.filter(m => m.title.trim() !== '')
      };
      onCourseGenerated(newCourse);
  };

  const resetManualForm = () => {
      setManualTitle('');
      setManualDesc('');
      setManualCategory('');
      setManualModules([{ id: `m-${Date.now()}`, title: '', lessons: [] }]);
      setEditingLessonId(null);
  };

  // --- Curriculum Builders ---

  const addModule = () => {
    setManualModules([...manualModules, { id: `m-${Date.now()}`, title: '', lessons: [] }]);
  };

  const deleteModule = (moduleId: string) => {
    if (manualModules.length <= 1) return;
    setManualModules(manualModules.filter(m => m.id !== moduleId));
  };

  const updateModuleTitle = (moduleId: string, title: string) => {
    setManualModules(manualModules.map(m => m.id === moduleId ? { ...m, title } : m));
  };

  const addLesson = (moduleId: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return {
                ...m,
                lessons: [...m.lessons, {
                    id: `l-${Date.now()}`,
                    title: '',
                    description: '',
                    duration: '5 min',
                    isCompleted: false,
                    content: ''
                }]
            };
        }
        return m;
    }));
  };

  const deleteLesson = (moduleId: string, lessonId: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return { ...m, lessons: m.lessons.filter(l => l.id !== lessonId) };
        }
        return m;
    }));
  };

  const updateLesson = (moduleId: string, lessonId: string, field: keyof Lesson, value: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return {
                ...m,
                lessons: m.lessons.map(l => l.id === lessonId ? { ...l, [field]: value } : l)
            };
        }
        return m;
    }));
  };

  const getEditingLesson = () => {
      if (!editingLessonId) return null;
      const mod = manualModules.find(m => m.id === editingLessonId.modId);
      if (!mod) return null;
      return mod.lessons.find(l => l.id === editingLessonId.lesId);
  };

  // --- Drag and Drop Handlers ---

  const triggerDropAnimation = (id: string) => {
      setLastMovedId(id);
      setTimeout(() => setLastMovedId(null), 700);
  };

  const onModuleDragStart = (e: React.DragEvent, id: string) => {
     setDraggedItem({ type: 'module', id });
     e.dataTransfer.effectAllowed = 'move';
     // Just a little hint for mobile polyfill if needed, mostly automatic
  };

  const onModuleDragOver = (e: React.DragEvent, id: string) => {
     e.preventDefault();
     if (draggedItem?.type !== 'module' || draggedItem.id === id) return;
     setDragOverId(id);
  };

  const onModuleDrop = (e: React.DragEvent, targetId: string) => {
     e.preventDefault();
     setDragOverId(null);
     if (!draggedItem || draggedItem.type !== 'module') return;

     const oldIndex = manualModules.findIndex(m => m.id === draggedItem.id);
     const newIndex = manualModules.findIndex(m => m.id === targetId);

     if (oldIndex !== -1 && newIndex !== -1 && oldIndex !== newIndex) {
         const newModules = [...manualModules];
         const [moved] = newModules.splice(oldIndex, 1);
         newModules.splice(newIndex, 0, moved);
         setManualModules(newModules);
         triggerDropAnimation(draggedItem.id);
     }
     setDraggedItem(null);
  };

  const onLessonDragStart = (e: React.DragEvent, id: string, parentId: string) => {
     e.stopPropagation();
     setDraggedItem({ type: 'lesson', id, parentId });
     e.dataTransfer.effectAllowed = 'move';
  };

  const onLessonDragOver = (e: React.DragEvent, id: string, parentId: string) => {
     e.preventDefault();
     e.stopPropagation();
     // Only allow drop if it's a lesson from the SAME module
     if (draggedItem?.type !== 'lesson' || draggedItem.id === id || draggedItem.parentId !== parentId) return;
     setDragOverId(id);
  };

  const onLessonDrop = (e: React.DragEvent, targetId: string, parentId: string) => {
     e.preventDefault();
     e.stopPropagation();
     setDragOverId(null);

     if (!draggedItem || draggedItem.type !== 'lesson' || draggedItem.parentId !== parentId) return;

     const modIndex = manualModules.findIndex(m => m.id === parentId);
     if (modIndex === -1) return;

     const module = manualModules[modIndex];
     const oldIndex = module.lessons.findIndex(l => l.id === draggedItem.id);
     const newIndex = module.lessons.findIndex(l => l.id === targetId);

     if (oldIndex !== -1 && newIndex !== -1 && oldIndex !== newIndex) {
         const newModules = [...manualModules];
         const newLessons = [...module.lessons];
         const [moved] = newLessons.splice(oldIndex, 1);
         newLessons.splice(newIndex, 0, moved);
         newModules[modIndex] = { ...module, lessons: newLessons };
         setManualModules(newModules);
         triggerDropAnimation(draggedItem.id);
     }
     setDraggedItem(null);
  };

  // --- Renderers ---

  const renderSelectMode = () => (
      <div className="flex flex-col space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <button 
                onClick={() => setMode('manual')}
                className="flex flex-col items-center justify-center p-6 bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-sm hover:border-indigo-500 dark:hover:border-indigo-500 transition-all group active:scale-[0.98]"
            >
                <div className="w-12 h-12 bg-blue-50 dark:bg-blue-900/20 text-blue-600 dark:text-blue-400 rounded-full flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                    <PenTool size={24} />
                </div>
                <h3 className="text-base font-bold text-gray-900 dark:text-white mb-1">{t.modeManual}</h3>
                <p className="text-xs text-gray-500 dark:text-gray-400 text-center leading-tight">{t.modeManualDesc}</p>
            </button>

            <button 
                onClick={() => setMode('upload')}
                className="flex flex-col items-center justify-center p-6 bg-white dark:bg-gray-800 rounded-3xl border border-gray-100 dark:border-gray-700 shadow-sm hover:border-indigo-500 dark:hover:border-indigo-500 transition-all group active:scale-[0.98]"
            >
                <div className="w-12 h-12 bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 rounded-full flex items-center justify-center mb-3 group-hover:scale-110 transition-transform">
                    <UploadCloud size={24} />
