                    {step === 'email' ? (
                        <>
                             {!isLogin && (
                                <div className="relative group">
                                    <input
                                        type="text"
                                        required
                                        value={formData.name}
                                        onChange={(e) => setFormData({...formData, name: e.target.value})}
                                        className="w-full bg-transparent border border-[#5f6368] rounded-md px-3 py-3.5 text-[#e8eaed] outline-none focus:border-[#8ab4f8] focus:ring-1 focus:ring-[#8ab4f8] transition-all peer"
                                        placeholder=" "
                                    />
                                    <label className="absolute left-3 top-3.5 text-[#9aa0a6] text-base cursor-text transition-all peer-focus:-top-2.5 peer-focus:left-2 peer-focus:text-xs peer-focus:text-[#8ab4f8] peer-focus:bg-[#131314] peer-focus:px-1 peer-not-placeholder-shown:-top-2.5 peer-not-placeholder-shown:left-2 peer-not-placeholder-shown:text-xs peer-not-placeholder-shown:text-[#9aa0a6] peer-not-placeholder-shown:bg-[#131314] peer-not-placeholder-shown:px-1 pointer-events-none">
                                        {t.fullName}
