                                    value={formData.email}
                                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                                    className="w-full bg-transparent border border-[#5f6368] rounded-md px-3 py-3.5 text-[#e8eaed] outline-none focus:border-[#8ab4f8] focus:ring-1 focus:ring-[#8ab4f8] transition-all peer"
