      case 'chat':
        return <ChatTutor t={t.chat} language={language} />;
      case 'settings':
        return <Settings 
          user={user} 
          onUpdateUser={handleUpdateUser}
          isDarkMode={isDarkMode} 
          onToggleDarkMode={toggleDarkMode}
          language={language}
          onToggleLanguage={toggleLanguage}
          onLogout={handleLogout}
          t={t.settings}
        />;
      default:
        return <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} language={language} />;
    }
  };

  return (
    <div className={`h-screen w-full bg-gray-50 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 flex flex-row relative transition-colors duration-200 overflow-hidden`}>
      {/* Sidebar for Desktop */}
      {!activeCourse && (
          <Sidebar 
            currentTab={currentTab} 
            onTabChange={handleTabChange} 
            user={user}
            labels={t.nav}
            isDarkMode={isDarkMode}
            onToggleDarkMode={toggleDarkMode}
            language={language}
            onToggleLanguage={toggleLanguage}
            onLogout={handleLogout}
          />
      )}

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto no-scrollbar scroll-smooth relative">
        <div className="max-w-7xl mx-auto w-full h-full">
            {renderContent()}
        </div>
      </main>

      {/* Bottom Nav for Mobile */}
      {!activeCourse && (
          <BottomNav currentTab={currentTab} onTabChange={handleTabChange} labels={t.nav} />
      )}
    </div>
  );
};

