const App: React.FC = () => {
  const [currentTab, setCurrentTab] = useState<Tab>('home');
  const [courses, setCourses] = useState<Course[]>(MOCK_COURSES);
  const [activeCourse, setActiveCourse] = useState<Course | null>(null);
  const [user, setUser] = useState<User>(MOCK_USER);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // State lifted to App level
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('vi');

  const t = TRANSLATIONS[language];

  const toggleDarkMode = () => {
    setIsDarkMode(prev => {
      const newMode = !prev;
      if (newMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
      return newMode;
    });
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'vi' ? 'en' : 'vi');
  };

  const handleLogin = (userData: User) => {
    setUser(userData);
    setIsAuthenticated(true);
    setCurrentTab('home');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(MOCK_USER);
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
  };

  const handleTabChange = (tab: Tab) => {
    setCurrentTab(tab);
    setActiveCourse(null);
  };

  const handleCourseClick = (course: Course) => {
    setActiveCourse(course);
  };

  const handleCourseGenerated = (newCourse: Course) => {
    setCourses(prev => [newCourse, ...prev]);
    setActiveCourse(newCourse); 
  };

  const handleUpdateCourse = (updatedCourse: Course) => {
    setCourses(prev => prev.map(c => c.id === updatedCourse.id ? updatedCourse : c));
    if (activeCourse && activeCourse.id === updatedCourse.id) {
        setActiveCourse(updatedCourse);
    }
  };

  const handleLessonComplete = (courseId: string, moduleId: string, lessonId: string) => {
    const updateCourseData = (course: Course) => {
      // Deep clone and update modules
      const newModules = course.modules.map(mod => {
        if (mod.id !== moduleId) return mod;
        return {
          ...mod,
          lessons: mod.lessons.map(les => {
            if (les.id !== lessonId) return les;
            return { ...les, isCompleted: true };
          })
        };
      });

      // Recalculate progress
      let totalLessons = 0;
      let completedLessons = 0;
      newModules.forEach(m => m.lessons.forEach(l => {
        totalLessons++;
        if (l.isCompleted) completedLessons++;
      }));

      const newProgress = totalLessons === 0 ? 0 : Math.round((completedLessons / totalLessons) * 100);

      return {
        ...course,
        modules: newModules,
        progress: newProgress
      };
    };

    // Update global courses state
    setCourses(prevCourses => prevCourses.map(c => 
      c.id === courseId ? updateCourseData(c) : c
    ));

    // Update active course if needed (so UI updates immediately)
    if (activeCourse && activeCourse.id === courseId) {
      setActiveCourse(prev => prev ? updateCourseData(prev) : null);
    }
  };

  // Auth Guard
  if (!isAuthenticated) {
    return (
        <div className={`min-h-screen ${isDarkMode ? 'dark' : ''}`}>
             <Auth 
                onLogin={handleLogin} 
                language={language}
                onToggleLanguage={toggleLanguage}
                t={t.auth}
             />
        </div>
    );
  }

  const renderContent = () => {
    let content;
    let key;

    if (activeCourse) {
      key = `course-${activeCourse.id}`;
      content = (
        <CourseDetail 
          key={activeCourse.id}
          course={activeCourse} 
          allCourses={courses}
          onCourseClick={handleCourseClick}
          onBack={() => setActiveCourse(null)} 
          language={language}
          onLessonComplete={handleLessonComplete}
          onCourseUpdate={handleUpdateCourse}
        />
      );
    } else {
      key = currentTab;
      switch (currentTab) {
        case 'home':
          content = <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} language={language} />;
          break;
        case 'search':
          content = <Search courses={courses} onCourseClick={handleCourseClick} t={t.search} language={language} />;
          break;
        case 'create':
          content = <CourseGenerator onCourseGenerated={handleCourseGenerated} t={t.generator} language={language} />;
          break;
        case 'chat':
          content = <ChatTutor t={t.chat} language={language} />;
          break;
        case 'settings':
          content = <Settings 
            user={user} 
            onUpdateUser={handleUpdateUser}
            isDarkMode={isDarkMode} 
            onToggleDarkMode={toggleDarkMode}
            language={language}
            onToggleLanguage={toggleLanguage}
            onLogout={handleLogout}
            t={t.settings}
          />;
          break;
        default:
          content = <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} language={language} />;
      }
    }

    return (
      <div key={key} className="h-full animate-page-enter">
        {content}
      </div>
    );
  };

  return (
    <div className={`h-screen w-full bg-gray-50 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 flex flex-row relative transition-colors duration-200 overflow-hidden`}>
      {/* Sidebar for Desktop */}
      {!activeCourse && (
          <Sidebar 
            currentTab={currentTab} 
            onTabChange={handleTabChange} 
            user={user}
            labels={t.nav}
            isDarkMode={isDarkMode}
            onToggleDarkMode={toggleDarkMode}
            language={language}
            onToggleLanguage={toggleLanguage}
            onLogout={handleLogout}
          />
      )}

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto no-scrollbar scroll-smooth relative">
        <div className="max-w-7xl mx-auto w-full h-full">
            {renderContent()}
        </div>
      </main>

      {/* Bottom Nav for Mobile */}
      {!activeCourse && (
          <BottomNav currentTab={currentTab} onTabChange={handleTabChange} labels={t.nav} />
      )}
    </div>
  );
};

