            <>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">{t.title}</h1>
                <p className="text-gray-500 dark:text-gray-400 text-sm">{t.selectMode}</p>
            </>
        ) : (
            <div className="flex items-center justify-between">
                <button 
                    onClick={() => {
                        setMode('select');
                        setError(null);
                        setTopic('');
                        setSelectedFile(null);
                        setFileData(null);
                        resetManualForm();
                    }}
                    className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                >
                    <ChevronLeft className="text-gray-600 dark:text-gray-300" />
                </button>
                <h1 className="text-xl font-bold text-gray-900 dark:text-white">
                    {mode === 'ai' ? t.modeAI : mode === 'upload' ? t.modeUpload : t.modeManual}
                </h1>
                <div className="w-10"></div> {/* Spacer for centering */}
            </div>
        )}
      </div>

      {mode === 'select' && renderSelectMode()}
      {mode === 'ai' && renderAiMode()}
      {mode === 'upload' && renderUploadMode()}
      {mode === 'manual' && renderManualMode()}

      {/* Full screen editor overlay */}
      {editingLessonId && renderLessonEditor()}
    </div>
  );
};

