                                </div>
                                <div className="w-6 h-6 rounded-full bg-indigo-100 dark:bg-indigo-900/50 text-indigo-600 dark:text-indigo-400 flex items-center justify-center text-xs font-bold">
                                    {mIdx + 1}
                                </div>
                                <input
                                    type="text"
                                    value={module.title}
                                    onChange={(e) => updateModuleTitle(module.id, e.target.value)}
                                    className="flex-1 bg-transparent border-b border-transparent focus:border-indigo-500 outline-none text-sm font-bold text-gray-800 dark:text-gray-200 placeholder-gray-400"
                                    placeholder={t.moduleTitle}
                                />
                                <button onClick={() => deleteModule(module.id)} className="text-gray-400 hover:text-red-500">
                                    <Trash2 size={16} />
                                </button>
                            </div>

                            {/* Lessons List */}
                            <div className="space-y-3 pl-6">
                                {module.lessons.map((lesson, lIdx) => {
                                    const isLessonDragOver = dragOverId === lesson.id;
                                    const isLessonJustMoved = lastMovedId === lesson.id;

                                    return (
                                        <div 
                                            key={lesson.id} 
                                            draggable
                                            onDragStart={(e) => onLessonDragStart(e, lesson.id, module.id)}
                                            onDragOver={(e) => onLessonDragOver(e, lesson.id, module.id)}
                                            onDrop={(e) => onLessonDrop(e, lesson.id, module.id)}
                                            className={`rounded-xl p-3 shadow-sm border transition-all duration-300 ${
                                                isLessonDragOver
                                                ? 'border-l-4 border-indigo-500 border-t-gray-200 border-r-gray-200 border-b-gray-200 bg-indigo-50 dark:bg-indigo-900/20 scale-[1.02]'
                                                : isLessonJustMoved
                                                    ? 'border-green-500 bg-green-50/50 dark:bg-green-900/10'
                                                    : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-700'
                                            } ${draggedItem?.id === lesson.id ? 'opacity-40' : ''}`}
                                        >
                                            <div className="flex items-center gap-2 mb-2">
                                                <div className="cursor-grab active:cursor-grabbing text-gray-300 hover:text-indigo-500">
                                                    <GripVertical size={14} />
                                                </div>
                                                <input
                                                    type="text"
                                                    value={lesson.title}
                                                    onChange={(e) => updateLesson(module.id, lesson.id, 'title', e.target.value)}
                                                    className="flex-1 bg-transparent border-b border-gray-100 dark:border-gray-700 focus:border-indigo-500 outline-none text-sm font-medium text-gray-800 dark:text-gray-200 placeholder-gray-400 pb-1"
                                                    placeholder={t.lessonTitle}
                                                />
                                                <input 
                                                    type="text"
                                                    value={lesson.duration}
                                                    onChange={(e) => updateLesson(module.id, lesson.id, 'duration', e.target.value)}
                                                    className="w-16 bg-transparent border-b border-gray-100 dark:border-gray-700 focus:border-indigo-500 outline-none text-xs text-right text-gray-500 pb-1"
                                                    placeholder="5m"
                                                />
                                            </div>
                                            <div className="flex items-center justify-between pl-6">
                                                <button 
                                                    onClick={() => setEditingLessonId({modId: module.id, lesId: lesson.id})}
                                                    className={`flex items-center space-x-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${lesson.content ? 'bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400' : 'bg-gray-50 dark:bg-gray-700 text-gray-500'}`}
                                                >
                                                    <FileText size={12} />
                                                    <span>{t.editContent}</span>
                                                    {lesson.content && <div className="w-1.5 h-1.5 rounded-full bg-indigo-500 ml-1"></div>}
                                                </button>
                                                <button onClick={() => deleteLesson(module.id, lesson.id)} className="p-1.5 text-gray-400 hover:text-red-500 transition-colors">
                                                    <Trash2 size={14} />
                                                </button>
                                            </div>
                                        </div>
                                    );
                                })}
                                <button 
                                    onClick={() => addLesson(module.id)}
                                    className="w-full py-2 border border-dashed border-gray-300 dark:border-gray-600 rounded-xl text-xs font-medium text-gray-500 dark:text-gray-400 hover:border-indigo-500 hover:text-indigo-500 transition-colors flex items-center justify-center space-x-1"
                                >
                                    <Plus size={14} />
                                    <span>{t.addLesson}</span>
                                </button>
                            </div>
                        </div>
                    );
                })}

                <button 
                    onClick={addModule}
                    className="w-full py-3 bg-gray-100 dark:bg-gray-800 rounded-xl text-sm font-bold text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors flex items-center justify-center space-x-2"
                >
                    <Plus size={16} />
                    <span>{t.addModule}</span>
                </button>
             </div>
          </div>
      </div>
  );

  const renderMyCourses = () => (
      <div className="space-y-6">
        {myCourses.length > 0 ? (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                {myCourses.map(course => (
                    <CourseCard key={course.id} course={course} onClick={onCourseClick || (() => {})} />
                ))}
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="w-20 h-20 bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center mb-4 text-gray-400">
                    <BookOpen size={32} />
                </div>
                <h3 className="text-gray-900 dark:text-white font-bold mb-2">{t.emptyMyCourses}</h3>
                <button 
                    onClick={() => setActiveTab('create')}
                    className="text-indigo-600 dark:text-indigo-400 font-semibold text-sm hover:underline"
                >
                    {t.createFirst}
                </button>
            </div>
        )}
      </div>
  );

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pt-14 md:pt-8 px-6 pb-24 transition-colors duration-200">

      {/* Header with Tabs */}
      <div className="mb-8 flex flex-col items-center">
        {mode === 'select' ? (
            <>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-6">{t.title}</h1>

                <div className="flex bg-gray-200 dark:bg-gray-800 p-1 rounded-xl mb-6">
                    <button
                        onClick={() => setActiveTab('create')}
                        className={`flex items-center space-x-2 px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
                            activeTab === 'create'
                            ? 'bg-white dark:bg-gray-700 text-gray-900 dark:text-white shadow-sm'
                            : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                        }`}
                    >
                        <LayoutGrid size={16} />
                        <span>{t.tabCreate}</span>
                    </button>
                    <button
                        onClick={() => setActiveTab('my-courses')}
                        className={`flex items-center space-x-2 px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
                            activeTab === 'my-courses'
                            ? 'bg-white dark:bg-gray-700 text-gray-900 dark:text-white shadow-sm'
                            : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
                        }`}
                    >
                        <List size={16} />
                        <span>{t.tabMyCourses}</span>
                    </button>
                </div>
            </>
        ) : (
             <div className="flex items-center justify-between w-full">
                <button 
                    onClick={() => {
                        setMode('select');
                        setError(null);
                        setTopic('');
                        setSelectedFile(null);
                        setFileData(null);
                        resetManualForm();
                    }}
                    className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                >
                    <ChevronLeft className="text-gray-600 dark:text-gray-300" />
                </button>
                <h1 className="text-xl font-bold text-gray-900 dark:text-white">
                    {mode === 'ai' ? t.modeAI : mode === 'upload' ? t.modeUpload : t.modeManual}
                </h1>
                <div className="w-10"></div> {/* Spacer for centering */}
            </div>
        )}
      </div>

      {activeTab === 'create' && mode === 'select' && renderSelectMode()}
      {activeTab === 'create' && mode === 'ai' && renderAiMode()}
      {activeTab === 'create' && mode === 'upload' && renderUploadMode()}
      {activeTab === 'create' && mode === 'manual' && renderManualMode()}

      {activeTab === 'my-courses' && mode === 'select' && renderMyCourses()}

      {/* Full screen editor overlay */}
      {editingLessonId && renderLessonEditor()}
    </div>
  );
};

