                                <span className="text-xs font-bold">{course.visibility === 'public' ? (language === 'vi' ? 'Công khai' : 'Public') : (language === 'vi' ? 'Riêng tư' : 'Private')}</span>
                            </button>
                        </div>
                    </div>
                )}

