const App: React.FC = () => {
  const [currentTab, setCurrentTab] = useState<Tab>('home');
  const [courses, setCourses] = useState<Course[]>(MOCK_COURSES);
  const [activeCourse, setActiveCourse] = useState<Course | null>(null);
  const [user, setUser] = useState<User>(MOCK_USER);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  // State lifted to App level
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('vi');

  const t = TRANSLATIONS[language];

  const toggleDarkMode = () => {
    setIsDarkMode(prev => {
      const newMode = !prev;
      if (newMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
      return newMode;
    });
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'vi' ? 'en' : 'vi');
  };

  const handleLogin = (userData: User) => {
    // Merge streak defaults if not present
    const userWithStreak = {
        ...MOCK_USER, // fallback defaults
        ...userData,
    };
    setUser(userWithStreak);
    setIsAuthenticated(true);
    setCurrentTab('home');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(MOCK_USER);
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
  };

  const handleTabChange = (tab: Tab) => {
    setCurrentTab(tab);
    setActiveCourse(null);
  };

  const handleCourseClick = (course: Course) => {
    setActiveCourse(course);
  };

  const handleCourseGenerated = (newCourse: Course) => {
    const courseWithUserFlag = { ...newCourse, isCreatedByUser: true };
    setCourses(prev => [courseWithUserFlag, ...prev]);
    // Optionally jump to course detail or stay in my courses
    // For now, let's open it
    setActiveCourse(courseWithUserFlag); 
  };

  const handleUpdateCourse = (updatedCourse: Course) => {
    setCourses(prev => prev.map(c => c.id === updatedCourse.id ? updatedCourse : c));
    if (activeCourse && activeCourse.id === updatedCourse.id) {
        setActiveCourse(updatedCourse);
    }
  };

  const handleLessonComplete = (courseId: string, moduleId: string, lessonId: string) => {
    const updateCourseData = (course: Course) => {
      // Deep clone and update modules
      const newModules = course.modules.map(mod => {
        if (mod.id !== moduleId) return mod;
        return {
          ...mod,
          lessons: mod.lessons.map(les => {
            if (les.id !== lessonId) return les;
            return { ...les, isCompleted: true };
          })
        };
      });

      // Recalculate progress
      let totalLessons = 0;
      let completedLessons = 0;
      newModules.forEach(m => m.lessons.forEach(l => {
        totalLessons++;
        if (l.isCompleted) completedLessons++;
      }));

      const newProgress = totalLessons === 0 ? 0 : Math.round((completedLessons / totalLessons) * 100);

      return {
        ...course,
        modules: newModules,
        progress: newProgress
      };
    };

    // Update global courses state
    setCourses(prevCourses => prevCourses.map(c => 
      c.id === courseId ? updateCourseData(c) : c
    ));

    // Update user XP for completing lesson (Simple logic)
    setUser(prev => ({
        ...prev,
        xpToday: prev.xpToday + 10,
        points: prev.points + 10
    }));

    // Update active course if needed (so UI updates immediately)
    if (activeCourse && activeCourse.id === courseId) {
      setActiveCourse(prev => prev ? updateCourseData(prev) : null);
    }
  };

  // Auth Guard
  if (!isAuthenticated) {
    return (
        <div className={`min-h-screen ${isDarkMode ? 'dark' : ''}`}>
             <Auth 
                onLogin={handleLogin} 
                language={language}
                onToggleLanguage={toggleLanguage}
                t={t.auth}
             />
        </div>
    );
  }

  const renderContent = () => {
    let content;
    let key;

    if (activeCourse) {
      key = `course-${activeCourse.id}`;
      content = (
        <CourseDetail 
          key={activeCourse.id}
          course={activeCourse} 
          allCourses={courses}
          onCourseClick={handleCourseClick}
          onBack={() => setActiveCourse(null)} 
          language={language}
          onLessonComplete={handleLessonComplete}
          onCourseUpdate={handleUpdateCourse}
          commonT={t.common}
        />
      );
    } else {
      key = currentTab;
      switch (currentTab) {
        case 'home':
          content = <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} language={language} />;
          break;
        case 'search':
          content = <Search courses={courses} onCourseClick={handleCourseClick} t={t.search} language={language} />;
          break;
        case 'create':
          content = <CourseGenerator 
            onCourseGenerated={handleCourseGenerated} 
            t={t.generator} 
            language={language}
            courses={courses}
            onCourseClick={handleCourseClick}
          />;
          break;
        case 'chat':
          content = <ChatTutor t={t.chat} language={language} />;
          break;
        case 'settings':
          content = <Settings 
            user={user} 
            onUpdateUser={handleUpdateUser}
            isDarkMode={isDarkMode} 
            onToggleDarkMode={toggleDarkMode}
            language={language}
            onToggleLanguage={toggleLanguage}
            onLogout={handleLogout}
            t={t.settings}
          />;
          break;
        default:
          content = <Home user={user} courses={courses} onCourseClick={handleCourseClick} t={t.home} language={language} />;
      }
    }

    return (
      <div key={key} className="h-full animate-page-enter">
        {content}
      </div>
    );
  };

  return (
    <div className={`h-screen w-full bg-gray-50 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 flex flex-row relative transition-colors duration-200 overflow-hidden`}>
      {/* Sidebar for Desktop */}
      {!activeCourse && (
          <Sidebar 
            currentTab={currentTab} 
            onTabChange={handleTabChange} 
            user={user}
            labels={t.nav}
            isDarkMode={isDarkMode}
            onToggleDarkMode={toggleDarkMode}
            language={language}
            onToggleLanguage={toggleLanguage}
            onLogout={handleLogout}
          />
      )}

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto no-scrollbar scroll-smooth relative">
        <div className="max-w-7xl mx-auto w-full h-full">
            {renderContent()}
        </div>
      </main>

      {/* Bottom Nav for Mobile */}
      {!activeCourse && (
          <BottomNav currentTab={currentTab} onTabChange={handleTabChange} labels={t.nav} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { PlayCircle, Star, Users, Bot, PenTool, Lock, Globe, FileEdit, Share2, Check } from 'lucide-react';
import { Course } from '../types';

interface CourseCardProps {
  course: Course;
  onClick: (course: Course) => void;
}

const CourseCard: React.FC<CourseCardProps> = ({ course, onClick }) => {
  const [isCopied, setIsCopied] = useState(false);

  const handleShare = (e: React.MouseEvent) => {
    e.stopPropagation();
    const url = `${window.location.origin}?courseId=${course.id}`;
    navigator.clipboard.writeText(url).then(() => {
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
    }).catch(err => {
        console.error("Failed to copy", err);
    });
  };

  return (
    <div 
      onClick={() => onClick(course)}
      title={course.description}
      className="bg-white dark:bg-gray-800 rounded-2xl overflow-hidden shadow-sm hover:shadow-xl hover:scale-[1.03] transition-all duration-300 border border-gray-100 dark:border-gray-700 cursor-pointer active:scale-[0.98] transform group h-full flex flex-col relative"
    >
      <div className="relative h-32 w-full shrink-0 overflow-hidden">
        <img 
          src={course.thumbnail} 
          alt={course.title} 
          className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
        />

        {/* Share Button */}
        <button
            onClick={handleShare}
            className={`absolute top-2 left-2 p-1.5 backdrop-blur-md rounded-full text-white transition-all duration-300 z-30 shadow-sm flex items-center justify-center ${
                isCopied ? 'bg-green-500/90' : 'bg-black/30 hover:bg-black/60'
            } ${isCopied ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
            title="Share Course"
        >
            {isCopied ? <Check size={14} /> : <Share2 size={14} />}
        </button>

        {/* Description Tooltip Overlay */}
        <div className="absolute inset-0 bg-gray-900/80 backdrop-blur-[2px] p-4 flex flex-col items-center justify-center text-center opacity-0 group-hover:opacity-100 transition-all duration-300 z-10">
          <p className="text-white text-xs font-medium leading-relaxed line-clamp-3 mb-2 transform translate-y-4 group-hover:translate-y-0 transition-transform duration-300 delay-75">
            {course.description}
          </p>
          <div className="transform scale-75 group-hover:scale-100 transition-transform duration-300 delay-100 bg-white/20 rounded-full p-1.5 backdrop-blur-sm">
             <PlayCircle className="text-white w-5 h-5" fill="currentColor" fillOpacity={0.2} />
          </div>
        </div>

        {/* Badges Container */}
        <div className="absolute top-2 right-2 flex flex-col items-end space-y-1.5 z-20">
            {/* Status Badge */}
            {course.status === 'draft' && (
                <div className="bg-gray-600/90 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-sm flex items-center space-x-1">
                    <FileEdit size={10} />
                    <span>Bản nháp</span>
                </div>
            )}

            {course.status === 'published' && (
                 course.visibility === 'private' ? (
                    <div className="bg-red-500/90 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-sm flex items-center space-x-1">
                        <Lock size={10} />
                        <span>Riêng tư</span>
                    </div>
                 ) : (
                    <div className="bg-blue-500/90 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-sm flex items-center space-x-1">
                        <Globe size={10} />
                        <span>Công khai</span>
                    </div>
                 )
            )}

            {/* Origin Badge */}
            {course.isGenerated ? (
                <div className="bg-indigo-600/90 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-sm flex items-center space-x-1">
                    <Bot size={10} />
                    <span>AI</span>
                </div>
            ) : (
                <div className="bg-emerald-600/90 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-1 rounded-full shadow-sm flex items-center space-x-1">
                    <PenTool size={10} />
                    <span>Thủ công</span>
                </div>
            )}
        </div>
      </div>
      <div className="p-3 flex flex-col flex-1">
        <div className="flex items-center justify-between mb-1">
            <span className="text-xs font-semibold text-indigo-600 dark:text-indigo-400 uppercase tracking-wide truncate max-w-[70%]">{course.category}</span>
            <div className="flex items-center space-x-1 text-yellow-500">
                <Star size={12} fill="currentColor" />
                <span className="text-xs font-bold text-gray-700 dark:text-gray-300">{course.rating > 0 ? course.rating : 'New'}</span>
            </div>
        </div>
        <h3 className="font-bold text-gray-800 dark:text-white text-sm mb-1 line-clamp-2 leading-tight flex-1">
          {course.title}
        </h3>
        <p className="text-xs text-gray-500 dark:text-gray-400 line-clamp-1 mb-2">
          bởi {course.author}
        </p>

        <div className="flex items-center justify-between mt-auto pt-2">
             <div className="flex items-center text-gray-400 dark:text-gray-500 space-x-1">
                <Users size={12} />
                <span className="text-[10px]">{course.students.toLocaleString()} học viên</span>
             </div>
             {course.progress > 0 && (
                 <div className="flex items-center space-x-2">
                     <div className="w-12 h-1.5 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
                         <div className="h-full bg-green-500 rounded-full" style={{ width: `${course.progress}%` }}></div>
                     </div>
                     <span className="text-[10px] text-gray-500 dark:text-gray-400">{course.progress}%</span>
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

