              <div className="flex items-center justify-between p-4 border-b border-gray-100 dark:border-gray-800">
                  <button onClick={() => { setEditingLessonId(null); setIsEditorPreviewMode(false); }} className="flex items-center text-gray-600 dark:text-gray-300">
