                              {lesson.title || t.lessonTitle}
                          </label>
                          <textarea 
                              value={lesson.content || ''}
                              onChange={(e) => updateLesson(editingLessonId.modId, editingLessonId.lesId, 'content', e.target.value)}
                              className="w-full h-[calc(100%-2rem)] p-4 rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800 text-gray-800 dark:text-gray-100 focus:ring-2 focus:ring-indigo-500 outline-none resize-none font-mono text-sm leading-relaxed"
                              placeholder={t.content}
