import { GoogleGenAI, Type } from "@google/genai";
import { Course, Module, Lesson, Language, VerificationResult } from '../types';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const COURSE_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    description: { type: Type.STRING },
    category: { type: Type.STRING },
    modules: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          lessons: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                description: { type: Type.STRING },
                duration: { type: Type.STRING },
                content: { type: Type.STRING, description: "Detailed educational content for the lesson in Markdown format." }
              }
            }
          }
        }
      }
    }
  }
};

const LESSON_CONTENT_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    markdownContent: { type: Type.STRING, description: "The educational content in Markdown format." },
    youtubeVideos: {
      type: Type.ARRAY,
      description: "A list of 1-2 highly relevant YouTube videos found via search.",
      items: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          videoId: { type: Type.STRING, description: "The YouTube Video ID (e.g., dQw4w9WgXcQ)" }
        }
      }
    }
  }
};

const VERIFICATION_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    status: { 
      type: Type.STRING, 
      enum: ['ACCURATE', 'PARTIALLY_ACCURATE', 'INACCURATE'],
      description: "Overall accuracy assessment of the content." 
    },
    analysis: { 
      type: Type.STRING, 
      description: "A detailed analysis of the facts checked using Google Search." 
    },
    suggestedCorrections: { 
      type: Type.STRING, 
      description: "If there are inaccuracies, suggest corrections. Otherwise empty." 
    }
  }
};

export const generateCourseStructure = async (
  topic: string, 
  language: Language, 
  fileData?: { mimeType: string, data: string }
): Promise<Partial<Course>> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';

  try {
    const parts: any[] = [];

    // If a file is provided, prioritize it in the prompt
    if (fileData) {
        parts.push({
            inlineData: {
                mimeType: fileData.mimeType,
                data: fileData.data
            }
        });
        parts.push({
            text: `Analyze the attached file content and create a comprehensive course structure based on it.
            The content MUST be in ${langPrompt} language.
            The course should be structured for a mobile learning app.
            Include 3 modules, each with 2 lessons.
            For each lesson, you MUST generate detailed educational content in Markdown format (at least 200 words).
            The title and description should reflect the file content.
            Keep descriptions punchy and engaging in ${langPrompt}.`
        });
    } else {
        parts.push({
            text: `Create a comprehensive course structure for the topic: "${topic}". 
            The content MUST be in ${langPrompt} language.
            The course should be structured for a mobile learning app. 
            Include 3 modules, each with 2 lessons.
            For each lesson, you MUST generate detailed educational content in Markdown format (at least 200 words).
            Keep descriptions punchy and engaging in ${langPrompt}.`
        });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: parts.length === 1 ? parts[0].text : parts, // Handle simpler string format or array format
      config: {
        responseMimeType: "application/json",
        responseSchema: COURSE_SCHEMA,
      },
    });

    const data = JSON.parse(response.text || "{}");

    // Transform to match our internal types with IDs
    const modules: Module[] = data.modules?.map((mod: any, mIdx: number) => ({
      id: `m-${Date.now()}-${mIdx}`,
      title: mod.title,
      lessons: mod.lessons?.map((les: any, lIdx: number) => ({
        id: `l-${Date.now()}-${mIdx}-${lIdx}`,
        title: les.title,
        description: les.description,
        duration: les.duration || "5 min",
        content: les.content,
        isCompleted: false,
      })) || []
    })) || [];

    return {
      title: data.title || topic,
      description: data.description,
      category: data.category || "General",
      modules,
      thumbnail: `https://picsum.photos/seed/${(data.title || topic).replace(/\s/g, '')}/400/300`,
      author: "Gemini AI",
      rating: 5.0,
      students: 1,
      progress: 0,
      isGenerated: true,
      status: 'draft', // Default to draft for AI generated content
      visibility: 'private' // Default to private
    };
  } catch (error) {
    console.error("Error generating course:", error);
    throw error;
  }
};

export const generateLessonContent = async (courseTitle: string, lessonTitle: string, language: Language): Promise<{ content: string; sources: { title: string; uri: string }[]; videos: { title: string; videoId: string }[] }> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are an expert tutor. 
      1. Write a concise, engaging, and educational lesson content in ${langPrompt} for the lesson "${lessonTitle}" which is part of the course "${courseTitle}".
      2. USE Google Search to find 2 highly relevant YouTube videos explaining this.

      For the Markdown Content:
      - Include a brief introduction.
      - Key concepts with examples.
      - A short summary.
      - Keep it under 400 words.

      For the Videos:
      - ONLY include videos found in the search results.
      - Extract the real Video ID.
      `,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: LESSON_CONTENT_SCHEMA,
      }
    });

    const json = JSON.parse(response.text || "{}");
    const content = json.markdownContent || (language === 'vi' ? "Không tải được nội dung." : "Content could not be loaded.");

    // Extract grounding chunks from the metadata (for the web sources)
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => chunk.web)
      .filter((web: any) => web)
      .map((web: any) => ({ title: web.title, uri: web.uri })) || [];

    // Helper to extract YouTube ID
    const extractYouTubeId = (url: string) => {
        if (!url) return null;
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? match[2] : null;
    };

    // 1. Get videos from Sources (Grounding) - TRUST THESE MORE
    const sourceVideos = sources
        .filter((s: any) => s.uri && (s.uri.includes('youtube.com') || s.uri.includes('youtu.be')))
        .map((s: any) => ({
            title: s.title,
            videoId: extractYouTubeId(s.uri)
        }))
        .filter((v: any) => v.videoId);

    // 2. Get videos from JSON (Model generation)
    let modelVideos = json.youtubeVideos || [];

    // Combine: Start with source videos, then add model videos if they are different and valid
    const allVideos = [...sourceVideos];
    const existingIds = new Set(allVideos.map(v => v.videoId));

    modelVideos.forEach((v: any) => {
        if (v.videoId && v.videoId.length === 11 && !existingIds.has(v.videoId)) {
            allVideos.push(v);
            existingIds.add(v.videoId);
        }
    });

    return { content, sources, videos: allVideos };
  } catch (error) {
    console.error("Error generating lesson content:", error);
    return {
      content: language === 'vi' 
        ? "Xin lỗi, chúng tôi không thể tạo nội dung cho bài học này ngay bây giờ." 
        : "Sorry, we cannot generate content for this lesson right now.",
      sources: [],
      videos: []
    };
  }
};

export const verifyLessonContent = async (content: string, language: Language): Promise<VerificationResult> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Verify the accuracy of the following educational content using Google Search.
      Language: ${langPrompt}

      Content to verify:
      """
      ${content.substring(0, 1000)}...
      """

      Task:
      1. Check key facts, definitions, and claims against reliable web sources.
      2. Identify any inaccuracies or hallucinations.
      3. Provide a status (ACCURATE, PARTIALLY_ACCURATE, INACCURATE).
      4. Write a brief analysis explaining your findings.
      `,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: VERIFICATION_SCHEMA,
      }
    });

    const json = JSON.parse(response.text || "{}");

    // Extract sources from the verification step
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => chunk.web)
      .filter((web: any) => web)
      .map((web: any) => ({ title: web.title, uri: web.uri })) || [];

    return {
      status: json.status || 'ACCURATE',
      analysis: json.analysis || 'Verification complete.',
      suggestedCorrections: json.suggestedCorrections,
      sources: sources
    };
  } catch (error) {
    console.error("Verification error:", error);
    return {
      status: 'ACCURATE', // Default fallback
      analysis: language === 'vi' ? "Không thể xác minh lúc này." : "Could not verify at this time.",
      sources: []
    };
  }
};

export const chatWithTutor = async (history: { role: 'user' | 'model', text: string }[], message: string, language: Language) => {
  const langInstruction = language === 'vi' ? 'Vietnamese' : 'English';
  try {
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        history: history.map(h => ({
            role: h.role,
            parts: [{ text: h.text }]
        })),
        config: {
            systemInstruction: `You are Neuro, a friendly and encouraging AI learning companion. Help the student understand concepts, answer questions, and keep them motivated. You MUST converse in ${langInstruction}. Keep answers concise.`
        }
      });

      const result = await chat.sendMessage({ message });
      return result.text;
  } catch (error) {
      console.error("Chat error", error);
      return language === 'vi' 
        ? "Mình đang gặp chút sự cố kết nối. Thử lại sau nhé!"
        : "I'm having some connection issues. Please try again later!";
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { 
  Bold, Italic, Underline, Image as ImageIcon, 
  AlignLeft, AlignCenter, AlignRight, 
  List, ListOrdered, Undo, Redo, 
  Type, Highlighter, Sigma, X, Maximize, Minus, Plus
} from 'lucide-react';

interface RichTextEditorProps {
  initialContent: string;
  onChange: (content: string) => void;
  placeholder?: string;
  className?: string;
}

const RichTextEditor: React.FC<RichTextEditorProps> = ({ initialContent, onChange, placeholder, className }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [fontSize, setFontSize] = useState(15);

  // Initialize content
  useEffect(() => {
    if (editorRef.current) {
        // Simple check to prevent cursor jumping if content is similar
        if (editorRef.current.innerHTML !== initialContent) {
             // If initial content looks like Markdown (starts with # or *), wrap it in paragraphs for the HTML editor
             // This is a basic fallback. Ideally, use a markdown-to-html parser.
             // For now, we assume if it's editing, we just load it.
            editorRef.current.innerHTML = initialContent;
        }
    }
  }, []);

  const handleInput = () => {
    if (editorRef.current) {
      onChange(editorRef.current.innerHTML);
    }
  };

  const execCommand = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) {
        editorRef.current.focus();
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          execCommand('insertImage', event.target.result as string);
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const changeFontSize = (delta: number) => {
      const newSize = fontSize + delta;
      setFontSize(newSize);
      // Note: execCommand fontSize uses 1-7 scale, checking specifically for px requires span manipulation
      // For this simplified editor, we'll map to closest execCommand value or use styling wrapper
      // Let's use simple execCommand for robustness in this demo context
      const scale = newSize > 24 ? 7 : newSize > 18 ? 6 : newSize > 16 ? 5 : newSize > 14 ? 4 : newSize > 12 ? 3 : 2; 
      execCommand('fontSize', scale.toString());
  };

  const ToolbarButton = ({ 
    icon: Icon, 
    onClick, 
    isActive = false,
    label 
  }: { icon: any, onClick: () => void, isActive?: boolean, label?: string }) => (
    <button
      onClick={(e) => { e.preventDefault(); onClick(); }}
      className={`p-2 rounded hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors text-gray-600 dark:text-gray-300 ${isActive ? 'bg-indigo-50 text-indigo-600 dark:bg-indigo-900/30' : ''}`}
      title={label}
      type="button"
    >
      <Icon size={18} strokeWidth={2.5} />
    </button>
  );

  return (
    <div className={`flex flex-col border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden bg-white dark:bg-gray-800 ${className}`}>
      {/* Floating Toolbar Area */}
      <div className="flex flex-col border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 sticky top-0 z-10">

        {/* Top Row: General Utils */}
        <div className="flex items-center space-x-1 p-2 border-b border-gray-100 dark:border-gray-700 overflow-x-auto no-scrollbar">
            <ToolbarButton icon={Undo} onClick={() => execCommand('undo')} label="Undo" />
            <ToolbarButton icon={Redo} onClick={() => execCommand('redo')} label="Redo" />
            <ToolbarButton icon={X} onClick={() => execCommand('removeFormat')} label="Clear Format" />

            <div className="w-px h-5 bg-gray-300 mx-2"></div>

            <button className="flex items-center space-x-1 px-3 py-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-sm font-medium text-gray-700 dark:text-gray-200">
                <Sigma size={16} />
                <span>Công thức</span>
            </button>

            <button 
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center space-x-1 px-3 py-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-sm font-medium text-gray-700 dark:text-gray-200"
            >
                <ImageIcon size={16} />
                <span>Tải ảnh</span>
            </button>
            <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/*" 
                onChange={handleImageUpload} 
            />

            <div className="w-px h-5 bg-gray-300 mx-2"></div>

            <select 
                onChange={(e) => execCommand('formatBlock', e.target.value)}
                className="bg-transparent text-sm font-medium text-gray-700 dark:text-gray-200 outline-none cursor-pointer hover:bg-gray-100 p-1 rounded"
                defaultValue="p"
            >
                <option value="p">Normal</option>
                <option value="h1">Heading 1</option>
                <option value="h2">Heading 2</option>
                <option value="h3">Heading 3</option>
                <option value="blockquote">Quote</option>
            </select>
        </div>

        {/* Bottom Row: Formatting */}
        <div className="flex items-center space-x-1 p-2 overflow-x-auto no-scrollbar">
            <div className="flex items-center bg-gray-100 dark:bg-gray-700 rounded-lg px-1 mr-2">
                <button onClick={() => changeFontSize(-1)} className="p-1 hover:text-indigo-500"><Minus size={14}/></button>
                <span className="w-8 text-center text-sm font-bold">{fontSize}</span>
                <button onClick={() => changeFontSize(1)} className="p-1 hover:text-indigo-500"><Plus size={14}/></button>
            </div>

            <ToolbarButton icon={Bold} onClick={() => execCommand('bold')} label="Bold" />
            <ToolbarButton icon={Italic} onClick={() => execCommand('italic')} label="Italic" />
            <ToolbarButton icon={Underline} onClick={() => execCommand('underline')} label="Underline" />

            <div className="w-px h-5 bg-gray-300 mx-1"></div>

            <ToolbarButton icon={AlignLeft} onClick={() => execCommand('justifyLeft')} label="Left" />
            <ToolbarButton icon={AlignCenter} onClick={() => execCommand('justifyCenter')} label="Center" />
            <ToolbarButton icon={AlignRight} onClick={() => execCommand('justifyRight')} label="Right" />

            <div className="w-px h-5 bg-gray-300 mx-1"></div>

            <ToolbarButton icon={List} onClick={() => execCommand('insertUnorderedList')} label="Bullet List" />
            <ToolbarButton icon={ListOrdered} onClick={() => execCommand('insertOrderedList')} label="Number List" />

            <div className="flex-1"></div>
            <ToolbarButton icon={Maximize} onClick={() => {}} label="Full Screen" />
        </div>
      </div>

      {/* Editor Content */}
      <div 
        ref={editorRef}
        className="flex-1 p-4 md:p-6 outline-none overflow-y-auto prose prose-indigo dark:prose-invert max-w-none min-h-[400px]"
        contentEditable
        onInput={handleInput}
        style={{ fontSize: `${fontSize}px` }}
        // This effectively disables the default paragraph behavior of some browsers to use <div>
        // but for a simple editor we accept the browser default
      />

      {!initialContent && !editorRef.current?.innerHTML && (
        <div className="absolute top-[110px] left-6 text-gray-400 pointer-events-none">
            {placeholder || 'Start typing...'}
        </div>
      )}
    </div>
  );
};

export default RichTextEditor;

import React, { useState, useRef, useEffect } from 'react';
import { Course, Module, Lesson, Language, VerificationResult } from '../types';
import { ChevronLeft, PlayCircle, CheckCircle, Lock, Clock, BookOpen, ChevronDown, ChevronUp, ArrowLeft, Users, Star, Sparkles, Loader2, Link as LinkIcon, Youtube, ShieldCheck, AlertTriangle, Check, Camera, Edit2, Save, X, Globe, FileEdit, LayoutTemplate, ArrowRight } from 'lucide-react';
import { generateLessonContent, verifyLessonContent } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';
import CourseCard from '../components/CourseCard';
import RichTextEditor from '../components/RichTextEditor';

interface CourseDetailProps {
  course: Course;
  allCourses?: Course[];
  onCourseClick?: (course: Course) => void;
  onBack: () => void;
  language?: Language;
  onLessonComplete?: (courseId: string, moduleId: string, lessonId: string) => void;
  onCourseUpdate?: (course: Course) => void;
  onEditCourse?: (course: Course) => void;
  commonT?: any;
}

const CourseDetail: React.FC<CourseDetailProps> = ({ 
    course, 
    allCourses = [], 
    onCourseClick, 
    onBack, 
    language = 'vi', 
    onLessonComplete,
    onCourseUpdate,
    onEditCourse,
    commonT = { edit: 'Edit', save: 'Save', cancel: 'Cancel', editing: 'Editing', markdownSupport: 'Markdown' }
}) => {
  const [activeModuleId, setActiveModuleId] = useState<string | null>(course.modules[0]?.id || null);
  const [selectedLesson, setSelectedLesson] = useState<Lesson | null>(null);
  const [selectedModuleId, setSelectedModuleId] = useState<string | null>(null);
  const [lessonContent, setLessonContent] = useState<string>("");
  const [lessonSources, setLessonSources] = useState<{title: string, uri: string}[]>([]);
  const [lessonVideos, setLessonVideos] = useState<{title: string, videoId: string}[]>([]);
  const [loadingLesson, setLoadingLesson] = useState(false);
  const [isSourcesExpanded, setIsSourcesExpanded] = useState(false);

  // Edit Mode State
  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Verification State
  const [verificationResult, setVerificationResult] = useState<VerificationResult | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);

  // Determine related courses: same category, excluding current course
  const relatedCourses = allCourses
    .filter(c => c.id !== course.id)
    .sort((a, b) => {
        // Boost score if category matches
        const aScore = a.category === course.category ? 1 : 0;
        const bScore = b.category === course.category ? 1 : 0;
        return bScore - aScore;
    })
    .slice(0, 5);

  const handleLessonSelect = (lesson: Lesson, moduleId: string) => {
    setSelectedLesson(lesson);
    setSelectedModuleId(moduleId);
    setVerificationResult(null); // Reset verification on new lesson
    setIsEditing(false); // Reset edit mode
    setIsSourcesExpanded(false); // Reset sources collapse state

    // If content exists, show it. Otherwise, reset content to empty to show the Generate UI.
    if (lesson.content) {
      setLessonContent(lesson.content);
      setLessonSources(lesson.sources || []);
      setLessonVideos(lesson.videos || []);
    } else {
      setLessonContent("");
      setLessonSources([]);
      setLessonVideos([]);
    }
  };

  const handleGenerateContent = async () => {
    if (!selectedLesson || loadingLesson) return;

    setLoadingLesson(true);
    setLessonSources([]);
    setLessonVideos([]);
    setVerificationResult(null);
    setIsSourcesExpanded(false);
    try {
      const result = await generateLessonContent(course.title, selectedLesson.title, language as Language);
      setLessonContent(result.content);
      setLessonSources(result.sources);
      setLessonVideos(result.videos);

      // Update the local lesson object so it persists in memory for this session
      selectedLesson.content = result.content;
      selectedLesson.sources = result.sources;
      selectedLesson.videos = result.videos;

      // Also update via parent if possible
      if (onCourseUpdate && selectedModuleId) {
          updateCourseContent(selectedModuleId, selectedLesson.id, result.content, result.sources, result.videos);
      }
    } catch (e) {
      setLessonContent(language === 'vi' ? "Lỗi tải nội dung." : "Error loading content.");
    } finally {
      setLoadingLesson(false);
    }
  };

  const handleVerifyContent = async () => {
    if (!lessonContent || isVerifying) return;

    setIsVerifying(true);
    try {
        const result = await verifyLessonContent(lessonContent, language as Language);
        setVerificationResult(result);
    } catch (e) {
        console.error(e);
    } finally {
        setIsVerifying(false);
    }
  };

  const handleCompleteLesson = () => {
    if (onLessonComplete && selectedLesson && selectedModuleId) {
        onLessonComplete(course.id, selectedModuleId, selectedLesson.id);
    }
  };

  // Logic to find and navigate to the next lesson
  const handleNextLesson = () => {
      if (!selectedLesson || !selectedModuleId) return;

      // Find current module index
      const currentModuleIndex = course.modules.findIndex(m => m.id === selectedModuleId);
      if (currentModuleIndex === -1) return;

      const currentModule = course.modules[currentModuleIndex];
      const currentLessonIndex = currentModule.lessons.findIndex(l => l.id === selectedLesson.id);

      // Check if there is a next lesson in the current module
      if (currentLessonIndex < currentModule.lessons.length - 1) {
          const nextLesson = currentModule.lessons[currentLessonIndex + 1];
          handleLessonSelect(nextLesson, selectedModuleId);
      } else {
          // Check if there is a next module
          if (currentModuleIndex < course.modules.length - 1) {
              const nextModule = course.modules[currentModuleIndex + 1];
              if (nextModule.lessons.length > 0) {
                  // Open next module and select first lesson
                  setActiveModuleId(nextModule.id);
                  handleLessonSelect(nextModule.lessons[0], nextModule.id);
              }
          } else {
              // Course complete!
              // Optionally show a "Course Completed" celebration here
              setSelectedLesson(null); // Go back to course overview
          }
      }
  };

  const handleRateLesson = (rating: number) => {
    if (!selectedLesson || !selectedModuleId || !onCourseUpdate) return;

    // Update local state first for immediate feedback
    const updatedLesson = { ...selectedLesson, userRating: rating };
    setSelectedLesson(updatedLesson);

    // Propagate to global state
    const newModules = course.modules.map(mod => {
        if (mod.id !== selectedModuleId) return mod;
        return {
            ...mod,
            lessons: mod.lessons.map(les => {
                if (les.id !== selectedLesson.id) return les;
                return { ...les, userRating: rating };
            })
        };
    });
    onCourseUpdate({ ...course, modules: newModules });
  };

  const toggleModule = (id: string) => {
    setActiveModuleId(activeModuleId === id ? null : id);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && onCourseUpdate) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = reader.result as string;
            onCourseUpdate({ ...course, thumbnail: base64String });
        };
        reader.readAsDataURL(file);
    }
  };

  const handleToggleStatus = () => {
      if (!onCourseUpdate) return;
      const newStatus = course.status === 'published' ? 'draft' : 'published';
      onCourseUpdate({ ...course, status: newStatus });
  };

  const handleToggleVisibility = () => {
      if (!onCourseUpdate) return;
      const newVisibility = course.visibility === 'public' ? 'private' : 'public';
      onCourseUpdate({ ...course, visibility: newVisibility });
  };

  // Logic to update course content in global state
  const updateCourseContent = (moduleId: string, lessonId: string, content: string, sources?: any[], videos?: any[]) => {
      if (!onCourseUpdate) return;

      const newModules = course.modules.map(mod => {
          if (mod.id !== moduleId) return mod;
          return {
              ...mod,
              lessons: mod.lessons.map(les => {
                  if (les.id !== lessonId) return les;
                  return { ...les, content, sources, videos };
              })
          };
      });

      onCourseUpdate({ ...course, modules: newModules });
  };

  const handleStartEditing = () => {
      setEditedContent(lessonContent);
      setIsEditing(true);
  };

  const handleSaveEdit = () => {
      if (!selectedLesson || !selectedModuleId) return;
      setLessonContent(editedContent);
      setIsEditing(false);

      // Update persistent state
      updateCourseContent(selectedModuleId, selectedLesson.id, editedContent, lessonSources, lessonVideos);

      // Update local reference
      selectedLesson.content = editedContent;
  };

  const handleCancelEdit = () => {
      setIsEditing(false);
      setEditedContent("");
  };

  const renderContent = (content: string) => {
    // Basic heuristic to detect if content is HTML (from RichTextEditor) or Markdown (from Gemini)
    // If it contains typical HTML block tags, assume HTML.
    const isHtml = /<[a-z][\s\S]*>/i.test(content) && !content.trim().startsWith('```');

    if (isHtml) {
        return (
            <div 
                className="prose prose-indigo dark:prose-invert prose-lg max-w-none"
                dangerouslySetInnerHTML={{ __html: content }}
            />
        );
    }

    return (
        <div className="prose prose-indigo dark:prose-invert prose-lg max-w-none">
            <ReactMarkdown>{content}</ReactMarkdown>
        </div>
    );
  };

  const renderVerificationResult = () => {
      if (!verificationResult) return null;

      let bgColor = "bg-green-50 dark:bg-green-900/20";
      let borderColor = "border-green-200 dark:border-green-800";
      let textColor = "text-green-800 dark:text-green-200";
      let icon = <Check size={20} className="text-green-600 dark:text-green-400" />;
      let title = language === 'vi' ? "Thông tin chính xác" : "Information Accurate";

      if (verificationResult.status === 'PARTIALLY_ACCURATE') {
          bgColor = "bg-yellow-50 dark:bg-yellow-900/20";
          borderColor = "border-yellow-200 dark:border-yellow-800";
          textColor = "text-yellow-800 dark:text-yellow-200";
          icon = <AlertTriangle size={20} className="text-yellow-600 dark:text-yellow-400" />;
          title = language === 'vi' ? "Lưu ý một số điểm" : "Partially Accurate";
      } else if (verificationResult.status === 'INACCURATE') {
          bgColor = "bg-red-50 dark:bg-red-900/20";
          borderColor = "border-red-200 dark:border-red-800";
          textColor = "text-red-800 dark:text-red-200";
          icon = <AlertTriangle size={20} className="text-red-600 dark:text-red-400" />;
          title = language === 'vi' ? "Thông tin không chính xác" : "Inaccurate Information";
      }

      return (
          <div className={`mt-6 rounded-xl border ${borderColor} ${bgColor} p-4 transition-all duration-300`}>
              <div className="flex items-center space-x-2 mb-2">
                  {icon}
                  <h4 className={`font-bold ${textColor}`}>{title}</h4>
              </div>
              <p className="text-sm text-gray-700 dark:text-gray-300 mb-3 leading-relaxed">
                  {verificationResult.analysis}
              </p>
              {verificationResult.suggestedCorrections && (
                  <div className="mb-3 text-sm bg-white dark:bg-gray-800 p-3 rounded-lg border border-gray-100 dark:border-gray-700">
                      <span className="font-bold text-gray-900 dark:text-white block mb-1">
                        {language === 'vi' ? "Đề xuất chỉnh sửa:" : "Correction:"}
                      </span>
                      <span className="text-gray-600 dark:text-gray-400">
                          {verificationResult.suggestedCorrections}
                      </span>
                  </div>
              )}
              {verificationResult.sources.length > 0 && (
                  <div>
                      <span className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-2">
                        {language === 'vi' ? "Nguồn xác minh:" : "Verified Sources:"}
                      </span>
                      <div className="space-y-1">
                          {verificationResult.sources.map((src, i) => (
                              <a 
                                key={i} 
                                href={src.uri} 
                                target="_blank" 
                                rel="noreferrer" 
                                className="block text-xs text-indigo-600 dark:text-indigo-400 truncate hover:underline"
                              >
                                  {src.title}
                              </a>
                          ))}
                      </div>
                  </div>
              )}
          </div>
      );
  };

  if (selectedLesson) {
    return (
      <div className="fixed inset-0 bg-white dark:bg-gray-900 z-50 overflow-y-auto no-scrollbar transition-colors duration-200 flex justify-center">
        <div className="w-full max-w-4xl bg-white dark:bg-gray-900 shadow-2xl min-h-screen relative flex flex-col">
            <div className="sticky top-0 bg-white dark:bg-gray-900 border-b border-gray-100 dark:border-gray-800 px-6 py-4 flex items-center justify-between z-10 transition-colors">
                <div className="flex items-center space-x-4">
                    <button 
                        onClick={() => setSelectedLesson(null)}
                        className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                    >
                        <ChevronLeft size={24} className="text-gray-700 dark:text-gray-200" />
                    </button>
                    <div>
                        <h3 className="text-base font-bold text-gray-900 dark:text-white line-clamp-1">{selectedLesson.title}</h3>
                        <p className="text-xs text-gray-500 dark:text-gray-400">{course.title}</p>
                    </div>
                </div>

                {/* Edit Toggle for Creators */}
                {course.isCreatedByUser && !isEditing && lessonContent && (
                    <button 
                        onClick={handleStartEditing}
                        className="p-2 bg-gray-100 dark:bg-gray-800 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 text-gray-600 dark:text-gray-300 hover:text-indigo-600 dark:hover:text-indigo-400 rounded-lg transition-colors flex items-center space-x-2"
                        title={commonT.edit}
                    >
                        <Edit2 size={18} />
                        <span className="hidden sm:inline text-xs font-bold">{commonT.edit}</span>
                    </button>
                )}

                {isEditing && (
                    <div className="flex items-center space-x-2">
                        <button 
                            onClick={handleCancelEdit}
                            className="p-2 text-gray-500 hover:text-red-500 transition-colors"
                            title={commonT.cancel}
                        >
                            <X size={20} />
                        </button>
                        <button 
                            onClick={handleSaveEdit}
                            className="flex items-center space-x-2 px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm font-bold transition-colors"
                        >
                            <Save size={16} />
                            <span>{commonT.save}</span>
                        </button>
                    </div>
                )}
            </div>

            <div className="p-6 md:p-10 flex-1 pb-24">
                {loadingLesson ? (
                    <div className="flex flex-col items-center justify-center h-64 space-y-4">
                        <div className="w-10 h-10 border-4 border-indigo-200 border-t-indigo-600 dark:border-indigo-900 dark:border-t-indigo-500 rounded-full animate-spin"></div>
                        <p className="text-gray-500 dark:text-gray-400 text-sm animate-pulse">AI đang soạn bài học cho bạn...</p>
                    </div>
                ) : isEditing ? (
                    <div className="h-full flex flex-col">
                         <div className="mb-2 flex justify-between items-center">
                             <span className="text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-wider">{commonT.editing}</span>
                         </div>
                         <RichTextEditor 
                             initialContent={editedContent}
                             onChange={setEditedContent}
                             className="min-h-[500px]"
                         />
                    </div>
                ) : lessonContent ? (
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">{selectedLesson.title}</h1>
                        {renderContent(lessonContent)}

                        {/* Rating Section */}
                        <div className="mt-10 mb-6 py-6 border-y border-gray-100 dark:border-gray-800 flex flex-col items-center justify-center">
                            <p className="text-sm font-bold text-gray-500 dark:text-gray-400 mb-3 uppercase tracking-wider">
                                {language === 'vi' ? 'Đánh giá bài học này' : 'Rate this lesson'}
                            </p>
                            <div className="flex items-center space-x-3">
                                {[1, 2, 3, 4, 5].map((star) => (
                                    <button
                                        key={star}
                                        onClick={() => handleRateLesson(star)}
                                        className="p-1 focus:outline-none transform hover:scale-110 transition-transform duration-200"
                                    >
                                        <Star 
                                            size={32} 
                                            className={`${
                                                (selectedLesson.userRating || 0) >= star 
                                                ? 'fill-yellow-400 text-yellow-400 drop-shadow-sm' 
                                                : 'text-gray-300 dark:text-gray-600 hover:text-yellow-200 dark:hover:text-yellow-800'
                                            }`} 
                                        />
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Verification Button */}
                        {!verificationResult && (
                            <div className="mt-8 flex justify-center">
                                <button
                                    onClick={handleVerifyContent}
                                    disabled={isVerifying}
                                    className={`flex items-center space-x-2 px-5 py-2.5 rounded-full text-sm font-semibold transition-all border ${
                                        isVerifying 
                                        ? 'bg-gray-100 text-gray-400 border-gray-200 dark:bg-gray-800 dark:border-gray-700' 
                                        : 'bg-white text-indigo-600 border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300 dark:bg-gray-800 dark:text-indigo-400 dark:border-gray-700 dark:hover:bg-gray-750'
                                    }`}
                                >
                                    {isVerifying ? (
                                        <>
                                            <Loader2 size={16} className="animate-spin" />
                                            <span>{language === 'vi' ? 'Đang kiểm tra...' : 'Verifying...'}</span>
                                        </>
                                    ) : (
                                        <>
                                            <ShieldCheck size={16} />
                                            <span>{language === 'vi' ? 'Kiểm tra lại bằng Google' : 'Verify with Google'}</span>
                                        </>
                                    )}
                                </button>
                            </div>
                        )}

                        {/* Verification Result Area */}
                        {renderVerificationResult()}

                        {/* YouTube Videos Section */}
                        {lessonVideos.length > 0 && (
                            <div className="mt-8 pt-6 border-t border-gray-100 dark:border-gray-800">
                                <h4 className="flex items-center text-sm font-bold text-gray-700 dark:text-gray-300 mb-4">
                                    <Youtube size={16} className="mr-2 text-red-600" />
                                    {language === 'vi' ? 'Video bài giảng' : 'Video Tutorial'}
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {lessonVideos.map((video, idx) => (
                                        <div key={idx} className="overflow-hidden rounded-xl bg-black shadow-lg">
                                            <div className="relative pb-[56.25%] h-0">
                                                <iframe
                                                    src={`https://www.youtube.com/embed/${video.videoId}`}
                                                    title={video.title}
                                                    className="absolute top-0 left-0 w-full h-full"
                                                    frameBorder="0"
                                                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                                    allowFullScreen
                                                />
                                            </div>
                                            <div className="p-3 bg-gray-50 dark:bg-gray-800">
                                                <p className="text-xs font-medium text-gray-900 dark:text-white line-clamp-1">{video.title}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {/* Sources Section - Collapsible */}
                        {lessonSources.length > 0 && (
                            <div className="mt-8 border-t border-gray-100 dark:border-gray-800">
                                <button 
                                    onClick={() => setIsSourcesExpanded(!isSourcesExpanded)}
                                    className="w-full flex items-center justify-between py-4 text-left group"
                                >
                                    <h4 className="flex items-center text-sm font-bold text-gray-700 dark:text-gray-300">
                                        <LinkIcon size={16} className="mr-2" />
                                        {language === 'vi' ? 'Nguồn tham khảo' : 'Sources'}
                                        <span className="ml-2 px-2 py-0.5 bg-gray-100 dark:bg-gray-800 rounded-full text-[10px] text-gray-500">
                                            {lessonSources.length}
                                        </span>
                                    </h4>
                                    {isSourcesExpanded ? (
                                        <ChevronUp size={20} className="text-gray-400 group-hover:text-indigo-600 dark:group-hover:text-indigo-400" />
                                    ) : (
