import React, { useRef, useEffect, useState } from 'react';
import { 
  Bold, Italic, Underline, Image as ImageIcon, 
  AlignLeft, AlignCenter, AlignRight, 
  List, ListOrdered, Undo, Redo, 
  Type, Highlighter, Sigma, X, Maximize, Minus, Plus
} from 'lucide-react';

interface RichTextEditorProps {
  initialContent: string;
  onChange: (content: string) => void;
  placeholder?: string;
  className?: string;
}

const RichTextEditor: React.FC<RichTextEditorProps> = ({ initialContent, onChange, placeholder, className }) => {
  const editorRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [fontSize, setFontSize] = useState(15);
  const [isEmpty, setIsEmpty] = useState(!initialContent);

  // Initialize content
  useEffect(() => {
    if (editorRef.current) {
        // Simple check to prevent cursor jumping if content is similar
        if (editorRef.current.innerHTML !== initialContent) {
             // If initial content looks like Markdown (starts with # or *), wrap it in paragraphs for the HTML editor
             // This is a basic fallback. Ideally, use a markdown-to-html parser.
             // For now, we assume if it's editing, we just load it.
            editorRef.current.innerHTML = initialContent;
        }
    }
    checkEmpty();
  }, [initialContent]); // Re-run if initialContent changes to keep sync if external update happens

  const checkEmpty = () => {
    if (editorRef.current) {
        const text = editorRef.current.innerText.trim();
        setIsEmpty(text === '' && (!editorRef.current.innerHTML || editorRef.current.innerHTML === '<br>'));
    }
  };

  const handleInput = () => {
    if (editorRef.current) {
      onChange(editorRef.current.innerHTML);
      checkEmpty();
    }
  };

  const execCommand = (command: string, value: string | undefined = undefined) => {
    document.execCommand(command, false, value);
    if (editorRef.current) {
        editorRef.current.focus();
    }
    handleInput(); // Trigger update for buttons like Bold/Italic which change content/style
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          execCommand('insertImage', event.target.result as string);
        }
      };
      reader.readAsDataURL(file);
    }
    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const changeFontSize = (delta: number) => {
      const newSize = fontSize + delta;
      setFontSize(newSize);
      // Note: execCommand fontSize uses 1-7 scale, checking specifically for px requires span manipulation
      // For this simplified editor, we'll map to closest execCommand value or use styling wrapper
      // Let's use simple execCommand for robustness in this demo context
      const scale = newSize > 24 ? 7 : newSize > 18 ? 6 : newSize > 16 ? 5 : newSize > 14 ? 4 : newSize > 12 ? 3 : 2; 
      execCommand('fontSize', scale.toString());
  };

  const ToolbarButton = ({ 
    icon: Icon, 
    onClick, 
    isActive = false,
    label 
  }: { icon: any, onClick: () => void, isActive?: boolean, label?: string }) => (
    <button
      onClick={(e) => { e.preventDefault(); onClick(); }}
      className={`p-2 rounded hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors text-gray-600 dark:text-gray-300 ${isActive ? 'bg-indigo-50 text-indigo-600 dark:bg-indigo-900/30' : ''}`}
      title={label}
      type="button"
    >
      <Icon size={18} strokeWidth={2.5} />
    </button>
  );

  return (
    <div className={`flex flex-col border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden bg-white dark:bg-gray-800 ${className}`}>
      {/* Floating Toolbar Area */}
      <div className="flex flex-col border-b border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 sticky top-0 z-10">

        {/* Top Row: General Utils */}
        <div className="flex items-center space-x-1 p-2 border-b border-gray-100 dark:border-gray-700 overflow-x-auto no-scrollbar">
            <ToolbarButton icon={Undo} onClick={() => execCommand('undo')} label="Undo" />
            <ToolbarButton icon={Redo} onClick={() => execCommand('redo')} label="Redo" />
            <ToolbarButton icon={X} onClick={() => execCommand('removeFormat')} label="Clear Format" />

            <div className="w-px h-5 bg-gray-300 mx-2"></div>

            <button className="flex items-center space-x-1 px-3 py-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-sm font-medium text-gray-700 dark:text-gray-200">
                <Sigma size={16} />
                <span>Công thức</span>
            </button>

            <button 
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center space-x-1 px-3 py-1.5 rounded hover:bg-gray-100 dark:hover:bg-gray-700 text-sm font-medium text-gray-700 dark:text-gray-200"
            >
                <ImageIcon size={16} />
                <span>Tải ảnh</span>
            </button>
            <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept="image/*" 
                onChange={handleImageUpload} 
            />

            <div className="w-px h-5 bg-gray-300 mx-2"></div>

            <select 
                onChange={(e) => execCommand('formatBlock', e.target.value)}
                className="bg-transparent text-sm font-medium text-gray-700 dark:text-gray-200 outline-none cursor-pointer hover:bg-gray-100 p-1 rounded"
                defaultValue="p"
            >
                <option value="p">Normal</option>
                <option value="h1">Heading 1</option>
                <option value="h2">Heading 2</option>
                <option value="h3">Heading 3</option>
                <option value="blockquote">Quote</option>
            </select>
        </div>

        {/* Bottom Row: Formatting */}
        <div className="flex items-center space-x-1 p-2 overflow-x-auto no-scrollbar">
            <div className="flex items-center bg-gray-100 dark:bg-gray-700 rounded-lg px-1 mr-2">
                <button onClick={() => changeFontSize(-1)} className="p-1 hover:text-indigo-500"><Minus size={14}/></button>
                <span className="w-8 text-center text-sm font-bold">{fontSize}</span>
                <button onClick={() => changeFontSize(1)} className="p-1 hover:text-indigo-500"><Plus size={14}/></button>
            </div>

            <ToolbarButton icon={Bold} onClick={() => execCommand('bold')} label="Bold" />
            <ToolbarButton icon={Italic} onClick={() => execCommand('italic')} label="Italic" />
            <ToolbarButton icon={Underline} onClick={() => execCommand('underline')} label="Underline" />

            <div className="w-px h-5 bg-gray-300 mx-1"></div>

            <ToolbarButton icon={AlignLeft} onClick={() => execCommand('justifyLeft')} label="Left" />
            <ToolbarButton icon={AlignCenter} onClick={() => execCommand('justifyCenter')} label="Center" />
            <ToolbarButton icon={AlignRight} onClick={() => execCommand('justifyRight')} label="Right" />

            <div className="w-px h-5 bg-gray-300 mx-1"></div>

            <ToolbarButton icon={List} onClick={() => execCommand('insertUnorderedList')} label="Bullet List" />
            <ToolbarButton icon={ListOrdered} onClick={() => execCommand('insertOrderedList')} label="Number List" />

            <div className="flex-1"></div>
            <ToolbarButton icon={Maximize} onClick={() => {}} label="Full Screen" />
        </div>
      </div>

      {/* Editor Content Wrapper */}
      <div className="relative flex-1 flex flex-col min-h-0">
        <div 
            ref={editorRef}
            className="flex-1 p-4 md:p-6 outline-none overflow-y-auto prose prose-indigo dark:prose-invert max-w-none min-h-[400px]"
            contentEditable
            onInput={handleInput}
            style={{ fontSize: `${fontSize}px` }}
        />

        {isEmpty && (
            <div className="absolute top-0 left-0 p-4 md:p-6 text-gray-400 pointer-events-none select-none">
                {placeholder || 'Start typing...'}
            </div>
        )}
      </div>
    </div>
  );
};

export default RichTextEditor;

import React, { useState, useEffect } from 'react';
import { Sparkles, Loader2, BookOpen, ArrowRight, PenTool, ChevronLeft, Plus, Trash2, FileText, Save, GripVertical, Check, UploadCloud, FileType, Eye, Edit3, Image as ImageIcon, LayoutGrid, List, AlertTriangle } from 'lucide-react';
import { generateCourseStructure } from '../services/geminiService';
import { Course, Language, Module, Lesson } from '../types';
import ReactMarkdown from 'react-markdown';
import CourseCard from '../components/CourseCard';
import RichTextEditor from '../components/RichTextEditor';

interface CourseGeneratorProps {
  onCourseGenerated: (course: Course) => void;
  t: any;
  language: Language;
  courses?: Course[];
  onCourseClick?: (course: Course) => void;
  initialData?: Course | null;
  onCancel?: () => void;
}

type Mode = 'select' | 'ai' | 'manual' | 'upload';
type ViewTab = 'create' | 'my-courses';

const CourseGenerator: React.FC<CourseGeneratorProps> = ({ onCourseGenerated, t, language, courses = [], onCourseClick, initialData, onCancel }) => {
  const [activeTab, setActiveTab] = useState<ViewTab>('create');
  const [mode, setMode] = useState<Mode>('select');
  const [topic, setTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Upload State
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [fileData, setFileData] = useState<{ mimeType: string; data: string } | null>(null);

  // Manual creation state
  const [manualTitle, setManualTitle] = useState('');
  const [manualDesc, setManualDesc] = useState('');
  const [manualCategory, setManualCategory] = useState('');
  const [manualThumbnail, setManualThumbnail] = useState<string | null>(null);
  const [manualModules, setManualModules] = useState<Module[]>([
    { id: `m-${Date.now()}`, title: '', lessons: [] }
  ]);
  const [editingLessonId, setEditingLessonId] = useState<{modId: string, lesId: string} | null>(null);
  const [isEditorPreviewMode, setIsEditorPreviewMode] = useState(false);

  // Drag and Drop State
  const [draggedItem, setDraggedItem] = useState<{ type: 'module' | 'lesson', id: string, parentId?: string } | null>(null);
  const [dragOverId, setDragOverId] = useState<string | null>(null);
  const [lastMovedId, setLastMovedId] = useState<string | null>(null);

  const myCourses = courses.filter(c => c.isCreatedByUser);

  // Effect to load initialData when provided (Editing Mode)
  useEffect(() => {
    if (initialData) {
        setMode('manual');
        setManualTitle(initialData.title);
        setManualDesc(initialData.description);
        setManualCategory(initialData.category);
        setManualThumbnail(initialData.thumbnail);
        setManualModules(initialData.modules);
    } else {
        // Reset if initialData is cleared (e.g. going back to main menu manually)
        // resetManualForm(); // Be careful not to loop
    }
  }, [initialData]);

  const handleAiGenerate = async () => {
    // Determine if we have enough input: either a topic text OR a file
    if (!topic.trim() && !fileData) return;

    setIsGenerating(true);
    setError(null);

    try {
      // Pass fileData if it exists
      const partialCourse = await generateCourseStructure(
          topic, 
          language, 
          fileData || undefined
      );

      const newCourse: Course = {
        id: `gen-${Date.now()}`,
        title: partialCourse.title || topic || "Uploaded Course",
        description: partialCourse.description || "Khóa học tạo bởi AI",
        thumbnail: partialCourse.thumbnail || "",
        author: "Neuro AI",
        category: partialCourse.category || "Tổng quát",
        rating: 5.0,
        students: 0,
        modules: partialCourse.modules || [],
        progress: 0,
        isGenerated: true,
        status: 'draft',
        visibility: 'private',
        isCreatedByUser: true
      };

      onCourseGenerated(newCourse);
    } catch (err) {
      setError(t.error);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];

          // Basic validation (size < 5MB)
          if (file.size > 5 * 1024 * 1024) {
              setError("File is too large (Max 5MB)");
              return;
          }

          setSelectedFile(file);
          setError(null);

          // Read file as Base64
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64String = reader.result as string;
              // Remove the Data URL prefix (e.g., "data:application/pdf;base64,")
              const base64Data = base64String.split(',')[1];
              setFileData({
                  mimeType: file.type,
                  data: base64Data
              });
          };
          reader.readAsDataURL(file);
      }
  };

  const handleThumbnailUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          // Basic validation for image
          if (file.size > 5 * 1024 * 1024) return;

          const reader = new FileReader();
          reader.onloadend = () => {
              setManualThumbnail(reader.result as string);
          };
          reader.readAsDataURL(file);
      }
  };

  const handleManualCreate = () => {
      setError(null);
      if (!manualTitle.trim()) return;

      // Validate Modules and Lessons
      let isValid = true;

      if (manualModules.length === 0) {
           setError(language === 'vi' ? 'Vui lòng thêm ít nhất một chương' : 'Please add at least one module');
           return;
      }

      for (const module of manualModules) {
          if (!module.title.trim()) {
              setError(language === 'vi' ? 'Vui lòng nhập tên cho tất cả các chương' : 'Please enter a title for all modules');
              isValid = false;
              break;
          }

          for (const lesson of module.lessons) {
              if (!lesson.title.trim()) {
                  setError(language === 'vi' ? `Vui lòng nhập tên bài học trong chương "${module.title}"` : `Please enter a title for all lessons in "${module.title}"`);
                  isValid = false;
                  break;
              }
          }
          if (!isValid) break;
      }

      if (!isValid) return;

      const newCourse: Course = {
          id: initialData ? initialData.id : `manual-${Date.now()}`,
          title: manualTitle,
          description: manualDesc || (language === 'vi' ? 'Khóa học thủ công' : 'Manual Course'),
          thumbnail: manualThumbnail || `https://picsum.photos/seed/${manualTitle.replace(/\s/g, '')}/400/300`,
          author: initialData ? initialData.author : 'Me',
          category: manualCategory || 'General',
          rating: initialData ? initialData.rating : 0,
          students: initialData ? initialData.students : 0,
          progress: initialData ? initialData.progress : 0,
          modules: manualModules,
          status: initialData ? initialData.status : 'draft',
          visibility: initialData ? initialData.visibility : 'private',
          isCreatedByUser: true
      };
      onCourseGenerated(newCourse);
  };

  const resetManualForm = () => {
      setManualTitle('');
      setManualDesc('');
      setManualCategory('');
      setManualThumbnail(null);
      setManualModules([{ id: `m-${Date.now()}`, title: '', lessons: [] }]);
      setEditingLessonId(null);
      setIsEditorPreviewMode(false);
      setError(null);
  };

  // --- Curriculum Builders ---

  const addModule = () => {
    setManualModules([...manualModules, { id: `m-${Date.now()}`, title: '', lessons: [] }]);
  };

  const deleteModule = (moduleId: string) => {
    if (manualModules.length <= 1) return;
    setManualModules(manualModules.filter(m => m.id !== moduleId));
  };

  const updateModuleTitle = (moduleId: string, title: string) => {
    setManualModules(manualModules.map(m => m.id === moduleId ? { ...m, title } : m));
  };

  const addLesson = (moduleId: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return {
                ...m,
                lessons: [...m.lessons, {
                    id: `l-${Date.now()}`,
                    title: '',
                    description: '',
                    duration: '5 min',
                    isCompleted: false,
                    content: ''
                }]
            };
        }
        return m;
    }));
  };

  const deleteLesson = (moduleId: string, lessonId: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return { ...m, lessons: m.lessons.filter(l => l.id !== lessonId) };
        }
        return m;
    }));
  };

  const updateLesson = (moduleId: string, lessonId: string, field: keyof Lesson, value: string) => {
    setManualModules(manualModules.map(m => {
        if (m.id === moduleId) {
            return {
                ...m,
                lessons: m.lessons.map(l => l.id === lessonId ? { ...l, [field]: value } : l)
            };
        }
        return m;
    }));
  };

  const getEditingLesson = () => {
      if (!editingLessonId) return null;
      const mod = manualModules.find(m => m.id === editingLessonId.modId);
      if (!mod) return null;
      return mod.lessons.find(l => l.id === editingLessonId.lesId);
  };

  // --- Drag and Drop Handlers ---

  const triggerDropAnimation = (id: string) => {
      setLastMovedId(id);
      setTimeout(() => setLastMovedId(null), 1000); // Extended slightly for visual cue
  };

  const onModuleDragStart = (e: React.DragEvent, id: string) => {
     setDraggedItem({ type: 'module', id });
     e.dataTransfer.effectAllowed = 'move';
     // Just a little hint for mobile polyfill if needed, mostly automatic
  };

  const onModuleDragOver = (e: React.DragEvent, id: string) => {
     e.preventDefault();
     if (draggedItem?.type !== 'module' || draggedItem.id === id) return;
     setDragOverId(id);
  };

  const onModuleDrop = (e: React.DragEvent, targetId: string) => {
     e.preventDefault();
     setDragOverId(null);
     if (!draggedItem || draggedItem.type !== 'module') return;

     const oldIndex = manualModules.findIndex(m => m.id === draggedItem.id);
     const newIndex = manualModules.findIndex(m => m.id === targetId);

     if (oldIndex !== -1 && newIndex !== -1 && oldIndex !== newIndex) {
         const newModules = [...manualModules];
         const [moved] = newModules.splice(oldIndex, 1);
         newModules.splice(newIndex, 0, moved);
         setManualModules(newModules);
         triggerDropAnimation(draggedItem.id);
     }
     setDraggedItem(null);
  };

  const onLessonDragStart = (e: React.DragEvent, id: string, parentId: string) => {
     e.stopPropagation();
     setDraggedItem({ type: 'lesson', id, parentId });
     e.dataTransfer.effectAllowed = 'move';
  };

  const onLessonDragOver = (e: React.DragEvent, id: string, parentId: string) => {
     e.preventDefault();
     e.stopPropagation();
     // Only allow drop if it's a lesson from the SAME module
     if (draggedItem?.type !== 'lesson' || draggedItem.id === id || draggedItem.parentId !== parentId) return;
     setDragOverId(id);
  };

  const onLessonDrop = (e: React.DragEvent, targetId: string, parentId: string) => {
     e.preventDefault();
     e.stopPropagation();
     setDragOverId(null);

     if (!draggedItem || draggedItem.type !== 'lesson' || draggedItem.parentId !== parentId) return;

     const modIndex = manualModules.findIndex(m => m.id === parentId);
     if (modIndex === -1) return;

     const module = manualModules[modIndex];
     const oldIndex = module.lessons.findIndex(l => l.id === draggedItem.id);
     const newIndex = module.lessons.findIndex(l => l.id === targetId);

     if (oldIndex !== -1 && newIndex !== -1 && oldIndex !== newIndex) {
         const newModules = [...manualModules];
         const newLessons = [...module.lessons];
         const [moved] = newLessons.splice(oldIndex, 1);
         newLessons.splice(newIndex, 0, moved);
         newModules[modIndex] = { ...module, lessons: newLessons };
         setManualModules(newModules);
         triggerDropAnimation(draggedItem.id);
     }
     setDraggedItem(null);
  };

