  const fileInputRef = useRef<HTMLInputElement>(null);

  // Verification State
  const [verificationResult, setVerificationResult] = useState<VerificationResult | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);

  // Determine related courses: same category, excluding current course
  const relatedCourses = allCourses
    .filter(c => c.id !== course.id)
    .sort((a, b) => {
        // Boost score if category matches
        const aScore = a.category === course.category ? 1 : 0;
        const bScore = b.category === course.category ? 1 : 0;
        return bScore - aScore;
    })
    .slice(0, 5);

  const handleLessonSelect = (lesson: Lesson, moduleId: string) => {
    setSelectedLesson(lesson);
    setSelectedModuleId(moduleId);
    setVerificationResult(null); // Reset verification on new lesson
    setIsEditing(false); // Reset edit mode
    setIsSourcesExpanded(false); // Reset sources collapse state

    // If content exists, show it. Otherwise, reset content to empty to show the Generate UI.
    if (lesson.content) {
      setLessonContent(lesson.content);
      setLessonSources(lesson.sources || []);
      setLessonVideos(lesson.videos || []);
      setLessonImages(lesson.images || []);
    } else {
      setLessonContent("");
      setLessonSources([]);
      setLessonVideos([]);
      setLessonImages([]);
    }
  };

  const handleGenerateContent = async () => {
    if (!selectedLesson || loadingLesson) return;

    setLoadingLesson(true);
    setLessonSources([]);
    setLessonVideos([]);
    setLessonImages([]);
    setVerificationResult(null);
    setIsSourcesExpanded(false);
    try {
      const result = await generateLessonContent(course.title, selectedLesson.title, language as Language);
      setLessonContent(result.content);
      setLessonSources(result.sources);
      setLessonVideos(result.videos);
      setLessonImages(result.images);

      // Update the local lesson object so it persists in memory for this session
      selectedLesson.content = result.content;
      selectedLesson.sources = result.sources;
      selectedLesson.videos = result.videos;
      selectedLesson.images = result.images;

      // Also update via parent if possible
      if (onCourseUpdate && selectedModuleId) {
          updateCourseContent(selectedModuleId, selectedLesson.id, result.content, result.sources, result.videos, result.images);
      }
    } catch (e) {
      setLessonContent(language === 'vi' ? "Lỗi tải nội dung." : "Error loading content.");
    } finally {
      setLoadingLesson(false);
    }
  };

  const handleVerifyContent = async () => {
    if (!lessonContent || isVerifying) return;

    setIsVerifying(true);
    try {
        const result = await verifyLessonContent(lessonContent, language as Language);
        setVerificationResult(result);
    } catch (e) {
        console.error(e);
    } finally {
        setIsVerifying(false);
    }
  };

  const handleCompleteLesson = () => {
    if (onLessonComplete && selectedLesson && selectedModuleId) {
        onLessonComplete(course.id, selectedModuleId, selectedLesson.id);
    }
  };

  const handleNextLesson = () => {
      if (!selectedLesson || !selectedModuleId) return;

      const currentModuleIndex = course.modules.findIndex(m => m.id === selectedModuleId);
      if (currentModuleIndex === -1) return;

      const currentModule = course.modules[currentModuleIndex];
      const currentLessonIndex = currentModule.lessons.findIndex(l => l.id === selectedLesson.id);

      if (currentLessonIndex < currentModule.lessons.length - 1) {
          const nextLesson = currentModule.lessons[currentLessonIndex + 1];
          handleLessonSelect(nextLesson, selectedModuleId);
      } else {
          if (currentModuleIndex < course.modules.length - 1) {
              const nextModule = course.modules[currentModuleIndex + 1];
              if (nextModule.lessons.length > 0) {
                  setActiveModuleId(nextModule.id);
                  handleLessonSelect(nextModule.lessons[0], nextModule.id);
              }
          } else {
              setSelectedLesson(null);
          }
      }
  };

  const handleRateLesson = (rating: number) => {
    if (!selectedLesson || !selectedModuleId || !onCourseUpdate) return;

    const updatedLesson = { ...selectedLesson, userRating: rating };
    setSelectedLesson(updatedLesson);

    const newModules = course.modules.map(mod => {
        if (mod.id !== selectedModuleId) return mod;
        return {
            ...mod,
            lessons: mod.lessons.map(les => {
                if (les.id !== selectedLesson.id) return les;
                return { ...les, userRating: rating };
            })
        };
    });
    onCourseUpdate({ ...course, modules: newModules });
  };

  const toggleModule = (id: string) => {
    setActiveModuleId(activeModuleId === id ? null : id);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && onCourseUpdate) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = reader.result as string;
            onCourseUpdate({ ...course, thumbnail: base64String });
        };
        reader.readAsDataURL(file);
    }
  };

  const handleToggleStatus = () => {
      if (!onCourseUpdate) return;
      const newStatus = course.status === 'published' ? 'draft' : 'published';
      onCourseUpdate({ ...course, status: newStatus });
  };

  const handleToggleVisibility = () => {
      if (!onCourseUpdate) return;
      const newVisibility = course.visibility === 'public' ? 'private' : 'public';
      onCourseUpdate({ ...course, visibility: newVisibility });
  };

  const updateCourseContent = (moduleId: string, lessonId: string, content: string, sources?: any[], videos?: any[], images?: any[]) => {
      if (!onCourseUpdate) return;

      const newModules = course.modules.map(mod => {
          if (mod.id !== moduleId) return mod;
          return {
              ...mod,
              lessons: mod.lessons.map(les => {
                  if (les.id !== lessonId) return les;
                  return { ...les, content, sources, videos, images };
              })
          };
      });

      onCourseUpdate({ ...course, modules: newModules });
  };

  const handleStartEditing = () => {
      setEditedContent(lessonContent);
      setIsEditing(true);
  };

  const handleSaveEdit = () => {
      if (!selectedLesson || !selectedModuleId) return;
      setLessonContent(editedContent);
      setIsEditing(false);
      updateCourseContent(selectedModuleId, selectedLesson.id, editedContent, lessonSources, lessonVideos, lessonImages);
      selectedLesson.content = editedContent;
  };

  const handleCancelEdit = () => {
      setIsEditing(false);
      setEditedContent("");
  };

  const renderContent = (content: string) => {
    const isHtml = /<[a-z][\s\S]*>/i.test(content) && !content.trim().startsWith('```');
    if (isHtml) {
        return (
            <div 
                className="prose prose-indigo dark:prose-invert prose-lg max-w-none"
                dangerouslySetInnerHTML={{ __html: content }}
            />
        );
    }
    return (
        <div className="prose prose-indigo dark:prose-invert prose-lg max-w-none">
            <ReactMarkdown>{content}</ReactMarkdown>
        </div>
    );
  };

  const renderVerificationResult = () => {
      if (!verificationResult) return null;

      let bgColor = "bg-green-50 dark:bg-green-900/20";
      let borderColor = "border-green-200 dark:border-green-800";
      let textColor = "text-green-800 dark:text-green-200";
      let icon = <Check size={20} className="text-green-600 dark:text-green-400" />;
      let title = language === 'vi' ? "Thông tin chính xác" : "Information Accurate";

      if (verificationResult.status === 'PARTIALLY_ACCURATE') {
          bgColor = "bg-yellow-50 dark:bg-yellow-900/20";
          borderColor = "border-yellow-200 dark:border-yellow-800";
          textColor = "text-yellow-800 dark:text-yellow-200";
          icon = <AlertTriangle size={20} className="text-yellow-600 dark:text-yellow-400" />;
          title = language === 'vi' ? "Lưu ý một số điểm" : "Partially Accurate";
      } else if (verificationResult.status === 'INACCURATE') {
          bgColor = "bg-red-50 dark:bg-red-900/20";
          borderColor = "border-red-200 dark:border-red-800";
          textColor = "text-red-800 dark:text-red-200";
          icon = <AlertTriangle size={20} className="text-red-600 dark:text-red-400" />;
          title = language === 'vi' ? "Thông tin không chính xác" : "Inaccurate Information";
      }

      return (
          <div className={`mt-6 rounded-xl border ${borderColor} ${bgColor} p-4 transition-all duration-300`}>
              <div className="flex items-center space-x-2 mb-2">
                  {icon}
                  <h4 className={`font-bold ${textColor}`}>{title}</h4>
              </div>
              <p className="text-sm text-gray-700 dark:text-gray-300 mb-3 leading-relaxed">
                  {verificationResult.analysis}
              </p>
              {verificationResult.suggestedCorrections && (
                  <div className="mb-3 text-sm bg-white dark:bg-gray-800 p-3 rounded-lg border border-gray-100 dark:border-gray-700">
                      <span className="font-bold text-gray-900 dark:text-white block mb-1">
                        {language === 'vi' ? "Đề xuất chỉnh sửa:" : "Correction:"}
                      </span>
                      <span className="text-gray-600 dark:text-gray-400">
                          {verificationResult.suggestedCorrections}
                      </span>
                  </div>
              )}
              {verificationResult.sources.length > 0 && (
                  <div>
                      <span className="text-xs font-bold text-gray-500 dark:text-gray-400 block mb-2">
                        {language === 'vi' ? "Nguồn xác minh:" : "Verified Sources:"}
                      </span>
                      <div className="space-y-1">
                          {verificationResult.sources.map((src, i) => (
                              <a 
                                key={i} 
                                href={src.uri} 
                                target="_blank" 
                                rel="noreferrer" 
                                className="block text-xs text-indigo-600 dark:text-indigo-400 truncate hover:underline"
                              >
                                  {src.title}
                              </a>
                          ))}
                      </div>
                  </div>
              )}
          </div>
      );
  };

  if (selectedLesson) {
    return (
      <div className="fixed inset-0 bg-white dark:bg-gray-900 z-50 overflow-y-auto no-scrollbar transition-colors duration-200 flex justify-center">
        <div className="w-full max-w-4xl bg-white dark:bg-gray-900 shadow-2xl min-h-screen relative flex flex-col">
            <div className="sticky top-0 bg-white dark:bg-gray-900 border-b border-gray-100 dark:border-gray-800 px-6 py-4 flex items-center justify-between z-10 transition-colors">
                <div className="flex items-center space-x-4">
                    <button 
                        onClick={() => setSelectedLesson(null)}
                        className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                    >
                        <ChevronLeft size={24} className="text-gray-700 dark:text-gray-200" />
                    </button>
                    <div>
                        <h3 className="text-base font-bold text-gray-900 dark:text-white line-clamp-1">{selectedLesson.title}</h3>
                        <p className="text-xs text-gray-500 dark:text-gray-400">{course.title}</p>
                    </div>
                </div>

                {course.isCreatedByUser && !isEditing && lessonContent && (
                    <button 
                        onClick={handleStartEditing}
                        className="p-2 bg-gray-100 dark:bg-gray-800 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 text-gray-600 dark:text-gray-300 hover:text-indigo-600 dark:hover:text-indigo-400 rounded-lg transition-colors flex items-center space-x-2"
                        title={commonT.edit}
                    >
                        <Edit2 size={18} />
                        <span className="hidden sm:inline text-xs font-bold">{commonT.edit}</span>
                    </button>
                )}

                {isEditing && (
                    <div className="flex items-center space-x-2">
                        <button 
                            onClick={handleCancelEdit}
                            className="p-2 text-gray-500 hover:text-red-500 transition-colors"
                            title={commonT.cancel}
                        >
                            <X size={20} />
                        </button>
                        <button 
                            onClick={handleSaveEdit}
                            className="flex items-center space-x-2 px-3 py-1.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg text-sm font-bold transition-colors"
                        >
                            <Save size={16} />
                            <span>{commonT.save}</span>
                        </button>
                    </div>
                )}
            </div>

            <div className="p-6 md:p-10 flex-1 pb-24">
                {loadingLesson ? (
                    <div className="flex flex-col items-center justify-center h-64 space-y-4">
                        <div className="w-10 h-10 border-4 border-indigo-200 border-t-indigo-600 dark:border-indigo-900 dark:border-t-indigo-500 rounded-full animate-spin"></div>
                        <p className="text-gray-500 dark:text-gray-400 text-sm animate-pulse">AI đang soạn bài học và tìm kiếm hình ảnh minh họa...</p>
                    </div>
                ) : isEditing ? (
                    <div className="h-full flex flex-col">
                         <div className="mb-2 flex justify-between items-center">
                             <span className="text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase tracking-wider">{commonT.editing}</span>
                         </div>
                         <RichTextEditor 
                             initialContent={editedContent}
                             onChange={setEditedContent}
                             className="min-h-[500px]"
                         />
                    </div>
                ) : lessonContent ? (
                    <div>
                        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">{selectedLesson.title}</h1>

                        {/* Images Section */}
                        {lessonImages.length > 0 && (
                            <div className="mb-8 grid grid-cols-1 sm:grid-cols-2 gap-4">
                                {lessonImages.map((img, idx) => (
                                    <div key={idx} className="group relative rounded-2xl overflow-hidden bg-gray-100 dark:bg-gray-800 border border-gray-100 dark:border-gray-700 shadow-sm transition-all hover:shadow-md">
                                        <img 
                                            src={img.url} 
                                            alt={img.title} 
                                            className="w-full h-48 sm:h-56 object-cover transition-transform duration-500 group-hover:scale-110" 
                                            onError={(e) => {
                                                (e.target as HTMLImageElement).style.display = 'none';
                                            }}
                                        />
                                        <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-end p-4">
                                            <p className="text-white text-xs font-bold">{img.title}</p>
                                        </div>
                                        <div className="absolute bottom-2 right-2 p-1.5 bg-black/40 backdrop-blur-md rounded-lg text-white group-hover:hidden">
                                            <ImageIcon size={14} />
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        {renderContent(lessonContent)}

                        {/* Rating Section */}
                        <div className="mt-10 mb-6 py-6 border-y border-gray-100 dark:border-gray-800 flex flex-col items-center justify-center">
                            <p className="text-sm font-bold text-gray-500 dark:text-gray-400 mb-3 uppercase tracking-wider">
                                {language === 'vi' ? 'Đánh giá bài học này' : 'Rate this lesson'}
                            </p>
                            <div className="flex items-center space-x-3">
                                {[1, 2, 3, 4, 5].map((star) => (
                                    <button
                                        key={star}
                                        onClick={() => handleRateLesson(star)}
                                        className="p-1 focus:outline-none transform hover:scale-110 transition-transform duration-200"
                                    >
                                        <Star 
                                            size={32} 
                                            className={`${
                                                (selectedLesson.userRating || 0) >= star 
                                                ? 'fill-yellow-400 text-yellow-400 drop-shadow-sm' 
                                                : 'text-gray-300 dark:text-gray-600 hover:text-yellow-200 dark:hover:text-yellow-800'
                                            }`} 
                                        />
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Verification Button */}
                        {!verificationResult && (
                            <div className="mt-8 flex justify-center">
                                <button
                                    onClick={handleVerifyContent}
                                    disabled={isVerifying}
                                    className={`flex items-center space-x-2 px-5 py-2.5 rounded-full text-sm font-semibold transition-all border ${
                                        isVerifying 
                                        ? 'bg-gray-100 text-gray-400 border-gray-200 dark:bg-gray-800 dark:border-gray-700' 
                                        : 'bg-white text-indigo-600 border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300 dark:bg-gray-800 dark:text-indigo-400 dark:border-gray-700 dark:hover:bg-gray-750'
                                    }`}
                                >
                                    {isVerifying ? (
                                        <>
                                            <Loader2 size={16} className="animate-spin" />
                                            <span>{language === 'vi' ? 'Đang kiểm tra...' : 'Verifying...'}</span>
                                        </>
                                    ) : (
                                        <>
                                            <ShieldCheck size={16} />
                                            <span>{language === 'vi' ? 'Kiểm tra lại bằng Google' : 'Verify with Google'}</span>
                                        </>
                                    )}
                                </button>
                            </div>
                        )}

                        {renderVerificationResult()}

                        {/* YouTube Videos Section */}
                        {lessonVideos.length > 0 && (
                            <div className="mt-8 pt-6 border-t border-gray-100 dark:border-gray-800">
                                <h4 className="flex items-center text-sm font-bold text-gray-700 dark:text-gray-300 mb-4">
                                    <Youtube size={16} className="mr-2 text-red-600" />
                                    {language === 'vi' ? 'Video bài giảng' : 'Video Tutorial'}
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {lessonVideos.map((video, idx) => (
                                        <div key={idx} className="overflow-hidden rounded-xl bg-black shadow-lg">
                                            <div className="relative pb-[56.25%] h-0">
                                                <iframe
                                                    src={`https://www.youtube.com/embed/${video.videoId}`}
                                                    title={video.title}
                                                    className="absolute top-0 left-0 w-full h-full"
                                                    frameBorder="0"
                                                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                                                    allowFullScreen
                                                />
                                            </div>
                                            <div className="p-3 bg-gray-50 dark:bg-gray-800">
                                                <p className="text-xs font-medium text-gray-900 dark:text-white line-clamp-1">{video.title}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )}

                        {lessonSources.length > 0 && (
                            <div className="mt-8 border-t border-gray-100 dark:border-gray-800">
                                <button 
                                    onClick={() => setIsSourcesExpanded(!isSourcesExpanded)}
                                    className="w-full flex items-center justify-between py-4 text-left group"
                                >
                                    <h4 className="flex items-center text-sm font-bold text-gray-700 dark:text-gray-300">
                                        <LinkIcon size={16} className="mr-2" />
                                        {language === 'vi' ? 'Nguồn tham khảo' : 'Sources'}
                                        <span className="ml-2 px-2 py-0.5 bg-gray-100 dark:bg-gray-800 rounded-full text-[10px] text-gray-500">
                                            {lessonSources.length}
                                        </span>
                                    </h4>
                                    {isSourcesExpanded ? (
                                        <ChevronUp size={20} className="text-gray-400 group-hover:text-indigo-600 dark:group-hover:text-indigo-400" />
                                    ) : (
                                        <ChevronDown size={20} className="text-gray-400 group-hover:text-indigo-600 dark:group-hover:text-indigo-400" />
                                    )}
                                </button>

                                {isSourcesExpanded && (
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2 pb-6 animate-fadeIn">
                                        {lessonSources.map((source, idx) => (
                                            <a 
                                                key={idx} 
                                                href={source.uri} 
                                                target="_blank" 
                                                rel="noopener noreferrer"
                                                className="flex items-start p-3 bg-gray-50 dark:bg-gray-800 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-750 transition-colors group/link"
                                            >
                                                <div className="flex-1 min-w-0">
                                                    <p className="text-xs font-medium text-indigo-600 dark:text-indigo-400 truncate group-hover/link:underline">
                                                        {source.title}
                                                    </p>
                                                    <p className="text-[10px] text-gray-400 dark:text-gray-500 truncate mt-0.5">
                                                        {source.uri}
                                                    </p>
                                                </div>
                                            </a>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center py-20 text-center space-y-6">
                        <div className="w-24 h-24 bg-indigo-50 dark:bg-indigo-900/20 rounded-full flex items-center justify-center mb-2">
                            <Sparkles size={40} className="text-indigo-600 dark:text-indigo-400" />
                        </div>
                        <div>
                            <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">
                                {language === 'vi' ? 'Nội dung chưa sẵn sàng' : 'Content Not Ready'}
                            </h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400 max-w-sm mx-auto">
                                {language === 'vi' 
                                    ? 'Bài học này chưa có nội dung chi tiết. Hãy để AI tạo nội dung tùy chỉnh cho bạn.' 
                                    : 'This lesson does not have detailed content yet. Let AI generate custom content for you.'}
                            </p>
                        </div>
                        <button 
                            onClick={handleGenerateContent}
                            disabled={loadingLesson}
                            className={`flex items-center space-x-2 font-bold py-3.5 px-10 rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none transition-all active:scale-[0.98] ${
                                loadingLesson 
                                ? 'bg-gray-300 dark:bg-gray-700 text-gray-500 cursor-not-allowed' 
                                : 'bg-indigo-600 hover:bg-indigo-700 text-white'
                            }`}
                        >
                            {loadingLesson ? <Loader2 size={20} className="animate-spin" /> : <Sparkles size={20} />}
                            <span>{language === 'vi' ? 'Tạo nội dung với AI' : 'Generate with AI'}</span>
                        </button>
                    </div>
                )}
            </div>

            <div className="sticky bottom-0 left-0 right-0 p-4 bg-white dark:bg-gray-900 border-t border-gray-100 dark:border-gray-800 transition-colors z-20 flex space-x-3">
                <button 
                    onClick={handleCompleteLesson} 
                    disabled={(!lessonContent && !isEditing) || loadingLesson}
                    className={`flex-1 font-bold py-4 rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none transition-all active:scale-[0.98] flex justify-center items-center space-x-2 ${
                        (!lessonContent && !isEditing) || loadingLesson
                        ? 'bg-gray-200 dark:bg-gray-800 text-gray-400 dark:text-gray-600 cursor-not-allowed shadow-none'
                        : 'bg-indigo-600 dark:bg-indigo-500 text-white'
                    }`}
                >
                    {language === 'vi' ? 'Hoàn thành bài học' : 'Complete Lesson'}
                </button>

                <button
                    onClick={() => {
                        handleCompleteLesson();
                        handleNextLesson();
                    }}
                    disabled={(!lessonContent && !isEditing) || loadingLesson}
                    className={`font-bold py-4 px-6 rounded-xl border-2 transition-all active:scale-[0.98] flex items-center justify-center ${
                         (!lessonContent && !isEditing) || loadingLesson
                         ? 'border-gray-200 text-gray-300 dark:border-gray-700 dark:text-gray-600 cursor-not-allowed'
                         : 'border-indigo-100 dark:border-gray-700 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-gray-800'
                    }`}
                >
                    <span className="hidden md:inline mr-2">{language === 'vi' ? 'Tiếp theo' : 'Next'}</span>
                    <ArrowRight size={20} />
                </button>
            </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-24 md:pb-0 relative transition-colors duration-200">
      <div className="md:flex md:h-screen md:overflow-hidden">
        <div className="md:w-1/3 md:overflow-y-auto md:border-r border-gray-200 dark:border-gray-700">
            <div className="relative h-64 md:h-72 bg-gray-900 group">
                <img 
                    src={course.thumbnail} 
                    alt={course.title}
                    className="w-full h-full object-cover opacity-60" 
                />
                <div className="absolute inset-0 bg-gradient-to-t from-gray-900 to-transparent"></div>
                <button 
                    onClick={onBack}
                    className="absolute top-4 left-4 p-2 bg-black/30 backdrop-blur-md rounded-full text-white hover:bg-black/50 transition-colors z-10"
                >
                    <ArrowLeft size={20} />
                </button>

                <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="absolute top-4 right-4 p-2 bg-black/30 hover:bg-black/50 backdrop-blur-md rounded-full text-white transition-all z-20 md:opacity-0 md:group-hover:opacity-100"
                    title={language === 'vi' ? "Thay đổi ảnh bìa" : "Change Cover"}
                >
                    <Camera size={20} />
                </button>
                <input 
                    type="file" 
                    ref={fileInputRef}
                    className="hidden" 
                    accept="image/*"
                    onChange={handleImageUpload}
                />

