                            <p className="text-xs text-gray-400 dark:text-gray-400">{language === 'vi' ? 'Giảng viên' : 'Instructor'}</p>
                            <p className="text-sm font-bold text-gray-800 dark:text-white">{course.author}</p>
                        </div>
                    </div>
                    <div className="text-right">
                        <p className="text-xs text-gray-400 dark:text-gray-400">{language === 'vi' ? 'Tiến độ' : 'Progress'}</p>
