            <div className="p-6 md:p-10 flex-1 pb-32">
                {loadingLesson ? (
                    <div className="flex flex-col items-center justify-center h-64 space-y-4">
                        <Loader2 className="w-10 h-10 text-indigo-600 animate-spin" />
                        <p className="text-gray-500 dark:text-gray-400 text-sm">Neuro AI đang soạn nội dung...</p>
                    </div>
                ) : isEditing ? (
                    <RichTextEditor initialContent={editedContent} onChange={setEditedContent} className="min-h-[500px]" />
                ) : lessonContent ? (
                    <div className="animate-page-enter">
                        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-8 border-b border-gray-100 dark:border-gray-800 pb-4">{selectedLesson.title}</h1>

                        {lessonImages.length > 0 && (
                            <div className="mb-8 grid grid-cols-1 sm:grid-cols-2 gap-4">
                                {lessonImages.map((img, idx) => (
                                    <div key={idx} className="group relative rounded-2xl overflow-hidden border border-gray-100 dark:border-gray-700 shadow-sm">
                                        <img src={img.url} alt={img.title} className="w-full h-48 sm:h-56 object-cover transition-transform group-hover:scale-105" onError={(e) => (e.currentTarget.style.display = 'none')} />
                                        <div className="absolute inset-x-0 bottom-0 bg-black/60 backdrop-blur-sm p-3 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <p className="text-white text-xs font-medium">{img.title}</p>
                                        </div>
