export const generateCourseStructure = async (
  topic: string, 
  language: Language, 
  fileData?: { mimeType: string, data: string }
): Promise<Partial<Course>> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';

  try {
    const parts: any[] = [];

    if (fileData) {
        parts.push({
            inlineData: {
                mimeType: fileData.mimeType,
                data: fileData.data
            }
        });
        parts.push({
            text: `Analyze the attached file content and create a comprehensive course structure based on it.
            The content MUST be in ${langPrompt} language.
            Include 3 modules, each with 2 lessons.
            For each lesson, generate detailed educational content in Markdown format (at least 200 words). 
            Use clear headings (## and ###), bullet points, and bold text for key concepts to make it highly readable.`
        });
    } else {
        parts.push({
            text: `Create a comprehensive course structure for the topic: "${topic}". 
            The content MUST be in ${langPrompt} language.
            Include 3 modules, each with 2 lessons.
            For each lesson, generate detailed educational content in Markdown format (at least 200 words).
            Use clear headings (## and ###), bullet points, and bold text for key concepts to make it highly readable.`
        });
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: parts.length === 1 ? parts[0].text : parts,
      config: {
        responseMimeType: "application/json",
        responseSchema: COURSE_SCHEMA,
      },
    });

    const data = JSON.parse(response.text || "{}");

    const modules: Module[] = data.modules?.map((mod: any, mIdx: number) => ({
      id: `m-${Date.now()}-${mIdx}`,
      title: mod.title,
      lessons: mod.lessons?.map((les: any, lIdx: number) => ({
        id: `l-${Date.now()}-${mIdx}-${lIdx}`,
        title: les.title,
        description: les.description,
        duration: les.duration || "5 min",
        content: (les.content || "").replace(/\\n/g, '\n'),
        isCompleted: false,
      })) || []
    })) || [];

    return {
      title: data.title || topic,
      description: data.description,
      category: data.category || "General",
      modules,
      thumbnail: `https://picsum.photos/seed/${(data.title || topic).replace(/\s/g, '')}/400/300`,
      author: "Gemini AI",
      rating: 5.0,
      students: 1,
      progress: 0,
      isGenerated: true,
      status: 'draft',
      visibility: 'private',
      isCreatedByUser: true
    };
  } catch (error) {
    console.error("Error generating course:", error);
    throw error;
  }
};

export const generateLessonContent = async (courseTitle: string, lessonTitle: string, language: Language): Promise<{ content: string; sources: { title: string; uri: string }[]; videos: { title: string; videoId: string }[]; images: { title: string; url: string }[] }> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are an expert tutor writing content for a student in ${langPrompt}.

      Topic: Lesson "${lessonTitle}" of course "${courseTitle}".

      INSTRUCTIONS:
      1. Write a comprehensive lesson with a clear logical flow using Markdown.
      2. USE GOOGLE SEARCH to find 2-3 REAL and ACCESSIBLE image/diagram URLs that illustrate the lesson concepts.
      3. USE GOOGLE SEARCH to find 1-2 relevant YouTube videos.

      BE SPECIFIC: When searching for images, look for "educational diagrams", "infographics", or "real-world examples" related to the topic.`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: LESSON_CONTENT_SCHEMA,
      }
    });

    const json = JSON.parse(response.text || "{}");
    const content = (json.markdownContent || "").replace(/\\n/g, '\n');
    const images = json.images || [];

    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => chunk.web)
      .filter((web: any) => web)
      .map((web: any) => ({ title: web.title, uri: web.uri })) || [];

    const extractYouTubeId = (url: string) => {
        if (!url) return null;
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? match[2] : null;
    };

    const sourceVideos = sources
        .filter((s: any) => s.uri && (s.uri.includes('youtube.com') || s.uri.includes('youtu.be')))
        .map((s: any) => ({
            title: s.title,
            videoId: extractYouTubeId(s.uri)
        }))
        .filter((v: any) => v.videoId);

    let modelVideos = json.youtubeVideos || [];
    const allVideos = [...sourceVideos];
    const existingIds = new Set(allVideos.map(v => v.videoId));

    modelVideos.forEach((v: any) => {
        if (v.videoId && v.videoId.length === 11 && !existingIds.has(v.videoId)) {
            allVideos.push(v);
            existingIds.add(v.videoId);
        }
    });

    return { content, sources, videos: allVideos, images };
  } catch (error) {
    console.error("Error generating lesson content:", error);
    return { content: "", sources: [], videos: [], images: [] };
  }
};

export const verifyLessonContent = async (content: string, language: Language): Promise<VerificationResult> => {
  const langPrompt = language === 'vi' ? 'Vietnamese' : 'English';
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Verify educational content in ${langPrompt}:\n${content.substring(0, 1000)}`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: VERIFICATION_SCHEMA,
      }
    });
    const json = JSON.parse(response.text || "{}");
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => chunk.web)
      .filter((web: any) => web)
      .map((web: any) => ({ title: web.title, uri: web.uri })) || [];
    return {
      status: json.status || 'ACCURATE',
      analysis: json.analysis || 'Verification complete.',
      suggestedCorrections: json.suggestedCorrections,
      sources: sources
    };
  } catch (error) {
    return { status: 'ACCURATE', analysis: "", sources: [] };
  }
};

export const chatWithTutor = async (history: { role: 'user' | 'model', text: string }[], message: string, language: Language) => {
  const langInstruction = language === 'vi' ? 'Vietnamese' : 'English';
  try {
      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        history: history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
        config: { systemInstruction: `You are Neuro AI tutor in ${langInstruction}.` }
      });
      const result = await chat.sendMessage({ message });
      return result.text;
  } catch (error) {
      return "";
  }
}

import React, { useState, useRef, useEffect } from 'react';
import { Course, Module, Lesson, Language, VerificationResult } from '../types';
import { ChevronLeft, PlayCircle, CheckCircle, Lock, Clock, BookOpen, ChevronDown, ChevronUp, ArrowLeft, Users, Star, Sparkles, Loader2, Link as LinkIcon, Youtube, ShieldCheck, AlertTriangle, Check, Camera, Edit2, Save, X, Globe, FileEdit, LayoutTemplate, ArrowRight, Image as ImageIcon } from 'lucide-react';
import { generateLessonContent, verifyLessonContent } from '../services/geminiService';
import ReactMarkdown from 'react-markdown';
import CourseCard from '../components/CourseCard';
import RichTextEditor from '../components/RichTextEditor';

interface CourseDetailProps {
  course: Course;
  allCourses?: Course[];
  onCourseClick?: (course: Course) => void;
  onBack: () => void;
  language?: Language;
  onLessonComplete?: (courseId: string, moduleId: string, lessonId: string) => void;
  onCourseUpdate?: (course: Course) => void;
  onEditCourse?: (course: Course) => void;
  commonT?: any;
}

const CourseDetail: React.FC<CourseDetailProps> = ({ 
    course, 
    allCourses = [], 
    onCourseClick, 
    onBack, 
    language = 'vi', 
    onLessonComplete,
    onCourseUpdate,
    onEditCourse,
    commonT = { edit: 'Edit', save: 'Save', cancel: 'Cancel', editing: 'Editing', markdownSupport: 'Markdown' }
}) => {
  const [activeModuleId, setActiveModuleId] = useState<string | null>(course.modules[0]?.id || null);
  const [selectedLesson, setSelectedLesson] = useState<Lesson | null>(null);
  const [selectedModuleId, setSelectedModuleId] = useState<string | null>(null);
  const [lessonContent, setLessonContent] = useState<string>("");
  const [lessonSources, setLessonSources] = useState<{title: string, uri: string}[]>([]);
  const [lessonVideos, setLessonVideos] = useState<{title: string, videoId: string}[]>([]);
  const [lessonImages, setLessonImages] = useState<{title: string, url: string}[]>([]);
  const [loadingLesson, setLoadingLesson] = useState(false);
  const [isSourcesExpanded, setIsSourcesExpanded] = useState(false);

  const [isEditing, setIsEditing] = useState(false);
  const [editedContent, setEditedContent] = useState("");
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [verificationResult, setVerificationResult] = useState<VerificationResult | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);

  const relatedCourses = allCourses
    .filter(c => c.id !== course.id)
    .sort((a, b) => (b.category === course.category ? 1 : 0) - (a.category === course.category ? 1 : 0))
    .slice(0, 5);

  const handleLessonSelect = (lesson: Lesson, moduleId: string) => {
    setSelectedLesson(lesson);
    setSelectedModuleId(moduleId);
    setVerificationResult(null);
    setIsEditing(false);
    setIsSourcesExpanded(false);

    if (lesson.content) {
      const sanitized = lesson.content.replace(/\\n/g, '\n');
      setLessonContent(sanitized);
      setLessonSources(lesson.sources || []);
      setLessonVideos(lesson.videos || []);
      setLessonImages(lesson.images || []);
    } else {
      setLessonContent("");
      setLessonSources([]);
      setLessonVideos([]);
      setLessonImages([]);
    }
  };

  const handleGenerateContent = async () => {
    if (!selectedLesson || loadingLesson) return;
    setLoadingLesson(true);
    setVerificationResult(null);
    try {
      const result = await generateLessonContent(course.title, selectedLesson.title, language as Language);
      setLessonContent(result.content);
      setLessonSources(result.sources);
      setLessonVideos(result.videos);
      setLessonImages(result.images);

      if (onCourseUpdate && selectedModuleId) {
          updateCourseContent(selectedModuleId, selectedLesson.id, result.content, result.sources, result.videos, result.images);
      }
    } catch (e) {
      setLessonContent("");
    } finally {
      setLoadingLesson(false);
    }
  };

  const handleVerifyContent = async () => {
    if (!lessonContent || isVerifying) return;
    setIsVerifying(true);
    try {
        const result = await verifyLessonContent(lessonContent, language as Language);
        setVerificationResult(result);
    } catch (e) {
        console.error(e);
    } finally {
        setIsVerifying(false);
    }
  };

  const handleCompleteLesson = () => {
    if (onLessonComplete && selectedLesson && selectedModuleId) {
        onLessonComplete(course.id, selectedModuleId, selectedLesson.id);
    }
  };

  const handleNextLesson = () => {
      if (!selectedLesson || !selectedModuleId) return;
      const currentModuleIndex = course.modules.findIndex(m => m.id === selectedModuleId);
      if (currentModuleIndex === -1) return;
      const currentModule = course.modules[currentModuleIndex];
      const currentLessonIndex = currentModule.lessons.findIndex(l => l.id === selectedLesson.id);

      if (currentLessonIndex < currentModule.lessons.length - 1) {
          handleLessonSelect(currentModule.lessons[currentLessonIndex + 1], selectedModuleId);
      } else if (currentModuleIndex < course.modules.length - 1) {
          const nextModule = course.modules[currentModuleIndex + 1];
          if (nextModule.lessons.length > 0) {
              setActiveModuleId(nextModule.id);
              handleLessonSelect(nextModule.lessons[0], nextModule.id);
          }
      } else {
          setSelectedLesson(null);
      }
  };

  const handleRateLesson = (rating: number) => {
    if (!selectedLesson || !selectedModuleId || !onCourseUpdate) return;
    const newModules = course.modules.map(mod => mod.id !== selectedModuleId ? mod : {
        ...mod,
        lessons: mod.lessons.map(les => les.id !== selectedLesson.id ? les : { ...les, userRating: rating })
    });
    onCourseUpdate({ ...course, modules: newModules });
