     if (draggedItem?.type !== 'lesson' || draggedItem.id === id || draggedItem.parentId !== parentId) return;
     setDragOverId(id);
  };

  const onLessonDrop = (e: React.DragEvent, targetId: string, parentId: string) => {
     e.preventDefault();
