          </div>
      ) : (
        <>
            {mode === 'select' && renderSelectMode()}
            {mode === 'ai' && renderAiMode()}
            {mode === 'upload' && renderUploadMode()}
            {mode === 'manual' && renderManualMode()}
        </>
      )}

      {/* Lesson Editor Modal */}
      {editingLessonId && renderLessonEditor()}

      {/* Manual Mode Footer Actions */}
      {mode === 'manual' && (
          <div className="fixed bottom-0 left-0 right-0 p-4 bg-white dark:bg-gray-800 border-t border-gray-100 dark:border-gray-700 z-40 md:pl-72 flex justify-end space-x-4">
              <button 
                onClick={onCancel || (() => setMode('select'))}
                className="px-6 py-3 rounded-xl font-bold text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
              >
                  {t.cancel || "Cancel"}
              </button>
              <button 
                onClick={handleManualCreate}
                className="px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold shadow-lg shadow-indigo-200 dark:shadow-none transition-colors flex items-center space-x-2"
              >
                  <Save size={18} />
                  <span>{initialData ? t.updateManual : t.save}</span>
              </button>
          </div>
      )}
    </div>
  );
};

